INSERT INTO public.deep_cases (id, market_id, day, slot, content, tags) VALUES
($ml$52b5fe99-7479-525d-a31c-73d326c1f6d0$ml$::uuid, $ml$spacetech$ml$, 1, 1, $ml${"id": "spacetech-d1-c1", "title": "A rocket maker goes public", "lessonTitle": "Who builds the space industry", "slot": 1, "type": "apply", "brief": {"headline": "In August 2025, Firefly Aerospace raised $868 million in its stock market debut. It priced shares at $45, above its $41 to $43 range, for a value of $6.5 billion.", "kicker": "Apply the lesson: a new space company raises money from the public.", "fullText": "Firefly, based in Cedar Park, Texas, develops launch vehicles and spacecraft. It sold about 19.3 million shares and upsized the deal.\n\nIts Alpha rocket reached orbit in 2022. At the time Firefly priced an Alpha launch at $15 million, for up to 1,300 kg to orbit. That is the new space model from the lesson: a rocket sold as a service at a set price, not a vehicle built to one government's order.", "sources": [{"url": "https://news.bloomberglaw.com/private-equity/spacecraft-maker-firefly-raises-868-million-in-upsized-ipo", "label": "Bloomberg Law, Firefly raises $868 million in IPO, Aug 2025"}, {"url": "https://www.cnbc.com/2022/10/03/firefly-aerospace-reaches-orbit-joining-spacex-rocket-lab-and-others.html", "label": "CNBC, Firefly reaches orbit, Oct 2022"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Firefly priced above its range and sold more shares than planned. What does that signal?", "options": ["Investors wanted more shares than were on offer", "NASA set the share price for Firefly", "The company needed to sell rockets cheaper"], "correctIndex": 0, "explanation": "An upsized deal priced above its range means demand for the shares outran the supply."}, "numbers": {"kind": "numberSense", "prompt": "Firefly sold about 19.3 million shares at $45 each. About how much did it raise, in millions?", "min": 0, "max": 2000, "value": 868, "unit": "M", "explanation": "19.3 million times $45 is about $868 million."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at Firefly the week after its IPO.", "prompt": "What makes your answer stand out?", "options": ["Talk mostly about the share price jump", "Say it works just like a prime contractor", "Show you know it sells launches at set prices"], "correctIndex": 2, "consequences": ["The share price says little about the job you want.", "Primes build to government orders; Firefly sells rides.", "That shows you understand how it earns money."], "explanation": "Knowing the business model, a rocket sold at a set price, shows you understand the company."}, "proReasoning": "Strong candidates explain how a company makes money before they talk about its stock.", "commonMistake": "Treating a new space company like a defense prime.", "mentalModel": "Know how the company sells, then talk about the role."}, "invest": {"call": {"kind": "theCall", "situation": "Firefly lists at $45 a share, valued at $6.5 billion.", "prompt": "What do you study first?", "options": ["How its launch business earns money", "Only how far the shares rose on day one", "Whether its rocket is the largest one flying"], "correctIndex": 0, "consequences": ["Revenue from launches decides what the shares are worth.", "A first-day move says nothing about the business.", "Size alone does not make a launcher profitable."], "explanation": "A valuation rests on future revenue, so the launch business comes first."}, "proReasoning": "Investors look past the debut price to how the company will earn money.", "commonMistake": "Judging a space stock by its first trading day.", "mentalModel": "Value the business, not the debut."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your space startup watches Firefly raise $868 million from public investors.", "prompt": "What does it tell you?", "options": ["Private money for space is gone now", "Investors back space firms with a clear service", "Every space startup should list right away"], "correctIndex": 1, "consequences": ["Strong demand for shares points the other way.", "A rocket sold at a set price is easy for investors to read.", "A listing needs a business that public investors can follow."], "explanation": "A clear service with a set price is something investors can value."}, "proReasoning": "Founders study what investors paid for: a product with a price.", "commonMistake": "Reading one IPO as a reason to rush to the market.", "mentalModel": "Build a service investors can price."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a rocket company would sell shares to the public.", "prompt": "What's the main reason?", "options": ["Because NASA requires every rocket maker to", "So it never has to sell a launch again", "To raise money to build and fly rockets"], "correctIndex": 2, "consequences": ["NASA does not require a listing.", "Selling launches is how it earns money.", "Rockets cost a lot to build before they earn anything."], "explanation": "Building rockets takes large sums up front. Selling shares is one way to pay for it."}, "proReasoning": "Space companies need money long before their rockets earn it back.", "commonMistake": "Thinking public markets are only for big, old companies.", "mentalModel": "Shares fund the rockets."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:38fb58402fdb$ml$]::text[]),
($ml$578a5f5e-bb5b-54e9-a9df-9c1e7d392f1b$ml$::uuid, $ml$spacetech$ml$, 1, 2, $ml${"id": "spacetech-d1-c2", "title": "Half the rockets, most of the cargo", "lessonTitle": "Who builds the space industry", "slot": 2, "type": "connect", "brief": {"headline": "SpaceX flew 165 of the world's 320 orbital launches in 2025, and 123 of them carried its own Starlink satellites. The same lesson showed that 78% of the $613 billion space economy was commercial.", "kicker": "Connect two ideas from day 1: who builds, and who controls the ride.", "fullText": "Day 1 split the industry into primes, which build for governments, and new space companies, which sell launches and services at set prices. It also gave the rule that access to launch shapes everything downstream.\n\nPut the two together. A new space company flew more than half of all orbital launches, and most of its rockets carried its own internet satellites. A market that is mostly commercial runs through one company's ride to orbit.", "sources": [{"url": "https://www.jalopnik.com/2067687/spacex-half-orbital-rocket-launches-2025/", "label": "Jalopnik, SpaceX over half of 2025 launches"}, {"url": "https://www.spacefoundation.org/2025/07/22/the-space-report-2025-q2/", "label": "Space Foundation, The Space Report 2025 Q2"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the chain in order, from rocket to market.", "steps": ["SpaceX builds and flies its own rockets", "It flies more than half of all launches", "Most of its flights carry Starlink", "Its spare seats go to other customers", "Rivals plan around its schedule and prices"], "explanation": "Owning the rocket comes first. Flying often lets SpaceX fill most rides with its own product and sell the rest."}, "numbers": {"kind": "numberSense", "prompt": "What share of 2025's 320 orbital launches did SpaceX fly, in percent?", "min": 0, "max": 80, "value": 52, "unit": "%", "explanation": "165 of 320 is about 52%, more than every other launcher combined."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks you to map the space industry in one minute.", "prompt": "What do you lead with?", "options": ["Primes, new space firms, and who controls launch", "A list of every rocket that flew last year", "The history of the Space Shuttle"], "correctIndex": 0, "consequences": ["That ties who builds to who decides access.", "A list hides the structure of the market.", "History does not explain today's market."], "explanation": "The map has two layers: who builds, and who controls the ride everyone depends on."}, "proReasoning": "Good answers explain structure, then give one number, like 165 of 320 launches.", "commonMistake": "Listing companies without saying how they relate.", "mentalModel": "Structure first, then the number."}, "invest": {"call": {"kind": "theCall", "situation": "You compare a satellite company with SpaceX, which flew 165 of 320 launches.", "prompt": "What risk do you flag?", "options": ["Commercial demand is too small to matter", "The satellite firm depends on a rival's rocket", "SpaceX may stop launching altogether"], "correctIndex": 1, "consequences": ["Commercial activity was 78% of the economy.", "SpaceX sets the schedule and price of its rides.", "Nothing suggests SpaceX will stop flying."], "explanation": "A company that rents launches from a competitor carries that dependence in its plan."}, "proReasoning": "Investors ask who owns the ride before they value what rides on it.", "commonMistake": "Ignoring launch dependence when valuing satellites.", "mentalModel": "Ask who controls the ride."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup needs orbit, and one company flies most of the rockets.", "prompt": "How do you plan?", "options": ["Assume SpaceX will always have a seat", "Wait until launch gets much cheaper", "Design to fit more than one rocket"], "correctIndex": 2, "consequences": ["Its own satellites fill most of its flights.", "Waiting costs you time to market.", "A second option protects your schedule."], "explanation": "When one provider dominates, fitting a second rocket keeps you from being stuck."}, "proReasoning": "Founders design for two rides before they need one.", "commonMistake": "Building a satellite that fits only one rocket.", "mentalModel": "Fit two rides, book one."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that one company flew more than half the world's rockets.", "prompt": "Why does that matter beyond SpaceX?", "options": ["Most space businesses depend on its ride", "It means space is mostly government again", "It only matters for astronauts"], "correctIndex": 0, "consequences": ["Satellites of all kinds need a launch first.", "The economy was 78% commercial.", "Most launches carry satellites, not people."], "explanation": "Every satellite business starts with a launch, so who flies the rockets touches the whole industry."}, "proReasoning": "Launch is the gate every space business passes through.", "commonMistake": "Seeing launch counts as a sports score.", "mentalModel": "Whoever flies, shapes the rest."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:bc50c7b338b8$ml$]::text[]),
($ml$e1cd9ba3-7c7e-5f11-a0d2-3abfb6d25fd9$ml$::uuid, $ml$spacetech$ml$, 1, 3, $ml${"id": "spacetech-d1-c3", "title": "Sell to a prime or sell a service", "lessonTitle": "Who builds the space industry", "slot": 3, "type": "decide", "brief": {"headline": "You run a young company that makes satellite parts. A prime offers a long subcontract; commercial buyers want a product at a set price. In 2024, 78% of the $613 billion space economy was commercial.", "kicker": "Decide: which customer world do you build for first?", "fullText": "The lesson showed two worlds. Primes like Lockheed Martin build for governments, and Lockheed's space sales grew 4% in 2025. New space companies sell launches and services at set prices.\n\nGovernments spent $132 billion on space in 2024. The rest of the $613 billion economy was commercial. You can take one long contract with a prime, or build a standard product for many commercial buyers.", "sources": [{"url": "https://www.spacefoundation.org/2025/07/22/the-space-report-2025-q2/", "label": "Space Foundation, The Space Report 2025 Q2"}, {"url": "https://www.satellitetoday.com/finance/2026/01/29/lockheed-martin-space-sales-grew-4-in-2025/", "label": "Via Satellite, Lockheed Martin Space 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Which buyer group spent more on space in 2024?", "left": {"name": "Governments", "note": "$132 billion in 2024"}, "right": {"name": "Commercial activity", "note": "78% of a $613 billion economy"}, "correctIndex": 1, "explanation": "78% of $613 billion is about $478 billion, more than three times government spending."}, "numbers": {"kind": "numberSense", "prompt": "78% of the $613 billion space economy was commercial. About how many billions is that?", "min": 0, "max": 700, "value": 478, "unit": "B", "explanation": "About $478 billion, against $132 billion from governments."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You must choose between a role at a prime and one at a new space firm.", "prompt": "What do you weigh first?", "options": ["Which office is the closest to your home", "How each one wins and delivers its work", "Which company logo looks better on a CV"], "correctIndex": 1, "consequences": ["Commute matters, but it is not the core choice.", "Contracts and set prices shape very different jobs.", "A logo does not tell you the daily work."], "explanation": "Primes work to government contracts; new space firms sell products. The job follows the model."}, "proReasoning": "People who know both worlds pick the one that fits how they like to work.", "commonMistake": "Assuming all space jobs look the same.", "mentalModel": "Pick the model, then the company."}, "invest": {"call": {"kind": "theCall", "situation": "Your fund can back a parts maker selling to primes or to commercial buyers.", "prompt": "Which market is bigger?", "options": ["Government, at $132 billion a year", "They are about the same size", "Commercial, at about 78% of the economy"], "correctIndex": 2, "consequences": ["Large, but about a quarter of commercial.", "One is more than three times the other.", "$478 billion against $132 billion."], "explanation": "Governments anchor space, but commercial activity is most of the market."}, "proReasoning": "Investors size the market before judging the company in it.", "commonMistake": "Assuming space is mostly a government market.", "mentalModel": "Size the market first."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're a founder offered one long subcontract with a prime.", "prompt": "What do you check before signing?", "options": ["How much of your capacity it locks up", "Only the prestige of working with a prime", "Whether the prime pays you in cash"], "correctIndex": 0, "consequences": ["A big subcontract can crowd out commercial buyers.", "Prestige does not pay for growth.", "Payment terms matter, but capacity matters more here."], "explanation": "One large customer brings stability, but it can keep you from building a product many buyers want."}, "proReasoning": "Founders weigh the steady contract against the bigger market it may block.", "commonMistake": "Letting one customer shape your whole product.", "mentalModel": "Keep room for the bigger market."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks space is paid for mostly by governments.", "prompt": "What do you tell them?", "options": ["Space has no commercial market yet", "Most of it is commercial, about 78%", "Yes, governments pay for nearly all of it"], "correctIndex": 1, "consequences": ["Commercial activity was most of the total.", "Satellite services and products dominate.", "Governments spent $132 billion of $613 billion."], "explanation": "Governments matter, but most of the $613 billion space economy is commercial."}, "proReasoning": "Space today is a business as much as a government program.", "commonMistake": "Picturing space as only NASA and the military.", "mentalModel": "Space is mostly business now."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:11ea899cf7f3$ml$]::text[]),
($ml$57c26b69-1d2c-506e-ae5b-7ed6d0739dea$ml$::uuid, $ml$spacetech$ml$, 2, 1, $ml${"id": "spacetech-d2-c1", "title": "Who paid for Starliner's trouble", "lessonTitle": "Who pays for space", "slot": 1, "type": "apply", "brief": {"headline": "Boeing's Starliner losses reached about $2 billion by early 2025. NASA had awarded Boeing $4.2 billion in 2014 on a fixed-price contract, and SpaceX $2.6 billion.", "kicker": "Apply the lesson: on a fixed price, the builder pays for overruns.", "fullText": "Starliner's first crewed test launched on June 5, 2024, with two astronauts, for a planned eight-day stay. Thruster problems on the way to the station led NASA to judge it unsafe for the return, and Starliner came home empty on September 6, 2024.\n\nBoeing reported $523 million in Commercial Crew losses for 2024 alone. Because the contract was fixed price, those losses fell on Boeing, not on NASA.", "sources": [{"url": "https://spacepolicyonline.com/news/boeings-starliner-losses-reach-2-billion/", "label": "SpacePolicyOnline, Boeing's Starliner losses reach $2 billion, Feb 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["NASA covered Boeing's Starliner overruns.", "Starliner returned to Earth without its crew in 2024.", "Boeing's 2024 Commercial Crew losses were $523 million."], "fakeIndex": 0, "explanation": "The contract was fixed price, so Boeing absorbed the losses."}, "numbers": {"kind": "numberSense", "prompt": "NASA awarded Boeing $4.2 billion and SpaceX $2.6 billion. How much more did Boeing get, in billions?", "min": 0, "max": 4, "value": 1.6, "unit": "B", "explanation": "$1.6 billion more, yet SpaceX flew crews first."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an interview why Boeing, not NASA, took the Starliner losses.", "prompt": "What's your answer?", "options": ["The fixed-price contract put the risk on Boeing", "NASA ran out of money for the whole program", "Boeing chose to donate the extra work for free"], "correctIndex": 0, "consequences": ["Fixed price means the builder covers overruns.", "NASA paid the agreed price, as planned.", "It was a contract term, not a gift."], "explanation": "Under a fixed-price contract, the company carries the cost of anything that goes wrong."}, "proReasoning": "Candidates who read contract types can explain who pays when a program slips.", "commonMistake": "Assuming the government always pays for overruns.", "mentalModel": "Know who carries the risk."}, "invest": {"call": {"kind": "theCall", "situation": "Boeing reports about $2 billion of Starliner losses on a fixed-price deal.", "prompt": "What does this teach you about such contracts?", "options": ["They never show up in a company earnings report", "Overruns land on the contractor's results", "The customer refunds them a few years later"], "correctIndex": 1, "consequences": ["$523 million hit 2024 alone.", "Boeing booked the losses in its own results.", "NASA paid the agreed price only."], "explanation": "Fixed-price contracts move cost risk onto the company, and investors see it in earnings."}, "proReasoning": "Investors check which contracts are fixed price before a program slips.", "commonMistake": "Treating a big contract award as pure upside.", "mentalModel": "Read the contract type."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup is offered a fixed-price contract to build a new spacecraft.", "prompt": "What do you do before signing?", "options": ["Bid as low as possible to win", "Assume the customer will pay overruns", "Price in the risk of things going wrong"], "correctIndex": 2, "consequences": ["A thin bid can sink you, as Starliner shows.", "Fixed price means you pay overruns.", "A buffer protects you if the work runs long."], "explanation": "On fixed price, every surprise comes out of your pocket, so price the risk in."}, "proReasoning": "Founders bid fixed price only on work they know how to estimate.", "commonMistake": "Underbidding new hardware on a fixed price.", "mentalModel": "Bid what it will really cost."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Starliner came home without its crew.", "prompt": "What's the reason?", "options": ["NASA judged it unsafe after thruster trouble", "The astronauts refused to leave the station", "Starliner was never meant to carry people"], "correctIndex": 0, "consequences": ["Thruster problems led to an empty return.", "NASA decided, not the crew.", "It was built to carry astronauts."], "explanation": "Thruster problems on the way up made NASA unwilling to risk the crew on the way down."}, "proReasoning": "Safety calls in human spaceflight can override a mission plan.", "commonMistake": "Thinking a crewed vehicle always brings its crew home.", "mentalModel": "Safety decides the ride home."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b6a2f44871b1$ml$]::text[]),
($ml$9bb91c4e-ef4f-50f3-80c5-bf67b5930915$ml$::uuid, $ml$spacetech$ml$, 2, 2, $ml${"id": "spacetech-d2-c2", "title": "Governments pay, but not for everything", "lessonTitle": "Who pays for space", "slot": 2, "type": "connect", "brief": {"headline": "Governments spent $132 billion on space in 2024, in an economy of $613 billion. On day 1 you saw that most of it is commercial; on day 2, that NASA now buys rides as services.", "kicker": "Connect day 1 and day 2: the biggest buyer is not the whole market.", "fullText": "Day 1 showed that 78% of the space economy was commercial in 2024. Day 2 showed governments spending $132 billion, and NASA changing how it buys.\n\nFor crew and cargo, NASA paid fixed prices for services instead of owning the vehicles. Commercial cargo and crew cost NASA about $7.6 billion to develop, against about $50.1 billion for the Shuttle. A big buyer that pays for services helps companies that also sell to everyone else.", "sources": [{"url": "https://www.spacefoundation.org/2025/07/22/the-space-report-2025-q2/", "label": "Space Foundation, The Space Report 2025 Q2"}, {"url": "https://www.planetary.org/articles/nasas-commercial-crew-is-a-great-deal-for-the-agency", "label": "Planetary Society, commercial crew economics"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Governments spent $132 billion of a $613 billion space economy. Roughly what share is that?", "options": ["About a fifth", "About half", "Nearly all of it"], "correctIndex": 0, "explanation": "$132 billion is about 22% of $613 billion."}, "numbers": {"kind": "numberSense", "prompt": "Commercial crew and cargo cost NASA about $7.6 billion to develop, the Shuttle $50.1 billion. How many times more?", "min": 0, "max": 12, "value": 6.6, "unit": "x", "explanation": "About 6.6 times more, for one government-owned vehicle."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a company that sells to NASA and to commercial customers.", "prompt": "How do you describe its customers?", "options": ["Government work barely matters to the business", "NASA anchors it, commercial buyers grow it", "NASA is the only customer that really matters"], "correctIndex": 1, "consequences": ["$132 billion a year is a lot of work.", "That matches a market that is mostly commercial.", "Commercial buyers are most of the market."], "explanation": "Government buying steadies the business; commercial demand is the larger market."}, "proReasoning": "Good hires know which customers pay today and which grow tomorrow.", "commonMistake": "Seeing a space firm as a government supplier only.", "mentalModel": "Anchor plus market."}, "invest": {"call": {"kind": "theCall", "situation": "A space company gets 90% of its revenue from NASA.", "prompt": "What do you weigh?", "options": ["Nothing, NASA always pays", "Only its share price this year", "Its exposure to budget swings"], "correctIndex": 2, "consequences": ["Budgets change year to year.", "Revenue risk matters more than one year of prices.", "Budget fights can move that revenue."], "explanation": "Revenue tied to one government budget moves when the budget does."}, "proReasoning": "Investors look for a mix of government and commercial customers.", "commonMistake": "Treating government revenue as risk free.", "mentalModel": "Check the customer mix."}, "build_startup": {"call": {"kind": "theCall", "situation": "NASA offers to buy your service at a fixed price, as it did with crew.", "prompt": "What else should you plan?", "options": ["Selling the same service to other buyers", "Making the service NASA-only", "Handing NASA ownership of the vehicle"], "correctIndex": 0, "consequences": ["Other buyers spread your costs.", "One buyer leaves you exposed.", "The service model means you keep the vehicle."], "explanation": "Buying services lets companies sell the same capability to others. That's the point."}, "proReasoning": "Founders use an anchor customer to build something many can buy.", "commonMistake": "Building only what one agency needs.", "mentalModel": "Sell the service widely."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a Crew Dragon seat costs so much less than a Shuttle seat.", "prompt": "What changed?", "options": ["Rockets stopped needing fuel", "NASA bought rides as a service", "Astronauts started paying their own way"], "correctIndex": 1, "consequences": ["Fuel is still part of every launch.", "Companies owned the vehicles and carried the risk.", "NASA still pays for its astronauts."], "explanation": "NASA stopped owning the vehicle and paid for seats. Companies had reason to keep costs down."}, "proReasoning": "Who owns the vehicle changes who works to cut its cost.", "commonMistake": "Thinking only better engines made space cheaper.", "mentalModel": "Buying rides changed the price."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:acb268d1a869$ml$]::text[]),
($ml$0577bf87-7187-58f3-819f-51e5d0b709e6$ml$::uuid, $ml$spacetech$ml$, 2, 3, $ml${"id": "spacetech-d2-c3", "title": "Bid a fixed price for crew rides", "lessonTitle": "Who pays for space", "slot": 3, "type": "decide", "brief": {"headline": "You run a company bidding to fly NASA crews. NASA wants a fixed price. Under commercial crew, contracts stayed within 3% of their original amounts.", "kicker": "Decide: how do you price a fixed-price crew service?", "fullText": "The lesson showed NASA committing a fixed sum for commercial crew while the companies carried the risk. A Crew Dragon seat cost NASA an estimated $60 to $67 million, against about $90 million on Soyuz and $170 million on the Shuttle.\n\nIf you win at a fixed price, every overrun is yours. If you bid too high, you lose to a cheaper rival.", "sources": [{"url": "https://www.planetary.org/articles/nasas-commercial-crew-is-a-great-deal-for-the-agency", "label": "Planetary Society, commercial crew economics"}]}, "evidence": {"kind": "faceOff", "prompt": "Under which contract does the company pay for its own overruns?", "left": {"name": "Fixed-price contract", "note": "The buyer pays an agreed sum"}, "right": {"name": "Cost-based contract", "note": "The buyer pays costs plus a fee"}, "correctIndex": 0, "explanation": "On a fixed price, the agreed sum does not move, so overruns fall on the company."}, "numbers": {"kind": "numberSense", "prompt": "Commercial crew contracts stayed within what percent of their original amounts?", "min": 0, "max": 10, "value": 3, "unit": "%", "explanation": "Within 3%, because the companies, not NASA, carried the overruns."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the program manager on a fixed-price crew bid.", "prompt": "What is your main job after winning?", "options": ["Ask NASA for more money each year", "Add features the contract did not ask for", "Keep costs inside the agreed price"], "correctIndex": 2, "consequences": ["Fixed price means the sum does not grow.", "Extra scope adds cost you cannot bill.", "Every overrun comes out of the company's margin."], "explanation": "On fixed price, the program manager protects the margin by controlling cost and scope."}, "proReasoning": "Managers on fixed-price work treat every change as a cost they own.", "commonMistake": "Running fixed-price work like a cost-based program.", "mentalModel": "Guard the price you agreed."}, "invest": {"call": {"kind": "theCall", "situation": "Two companies win fixed-price crew contracts; one is new to human spaceflight.", "prompt": "Where is the bigger risk?", "options": ["The newcomer, who may underestimate costs", "The experienced one, who knows the work", "Neither, since NASA pays overruns"], "correctIndex": 0, "consequences": ["New work is harder to estimate.", "Experience lowers the chance of surprises.", "Fixed price means NASA does not."], "explanation": "Fixed price is safest for companies that can estimate the work well."}, "proReasoning": "Investors ask how well a contractor can estimate before trusting a fixed price.", "commonMistake": "Assuming every fixed-price win is good news.", "mentalModel": "Bet on the best estimator."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your bid must beat a rival quoting $64 million a seat.", "prompt": "How do you set your price?", "options": ["Far above, hoping NASA pays more", "From your real costs plus a margin", "At $1 below the rival, whatever it costs"], "correctIndex": 1, "consequences": ["NASA picks on price and confidence.", "A price you can deliver keeps you alive.", "Winning at a loss is how losses pile up."], "explanation": "A fixed price must cover your costs. Winning below cost just postpones the loss."}, "proReasoning": "Founders price from costs up, then decide if they can compete.", "commonMistake": "Pricing only against the competitor.", "mentalModel": "Price from your costs."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why NASA likes fixed-price deals.", "prompt": "What's the main reason?", "options": ["Fixed price always gets NASA the best rocket", "It lets NASA skip its usual safety reviews", "Its cost is known, and companies carry the risk"], "correctIndex": 2, "consequences": ["Price does not guarantee quality.", "Safety reviews still apply.", "NASA knows what it will pay."], "explanation": "Fixed price tells NASA what it will spend and moves the overrun risk to the builder."}, "proReasoning": "Fixed price trades flexibility for a known cost.", "commonMistake": "Thinking fixed price means cheap and simple.", "mentalModel": "Known cost, shifted risk."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a8976bcec1da$ml$]::text[]),
($ml$6e3a050c-1cda-50ee-b13a-bd23db00df3d$ml$::uuid, $ml$spacetech$ml$, 3, 1, $ml${"id": "spacetech-d3-c1", "title": "Renting a rival's rocket", "lessonTitle": "Who holds the power in orbit", "slot": 1, "type": "apply", "brief": {"headline": "In December 2023, Amazon bought three Falcon 9 launches from SpaceX for Kuiper, its rival to Starlink. An FCC deadline required 1,618 Kuiper satellites in orbit by July 30, 2026.", "kicker": "Apply the lesson: even a rival has to rent SpaceX's ride.", "fullText": "In 2022 Amazon had booked 77 launches across Arianespace, Blue Origin and ULA. But Ariane 6 had not yet flown, New Glenn was still in development, and Vulcan's first flight kept slipping.\n\nWith 1,618 satellites due by mid-2026, half of its first-generation network, Amazon turned to the company running the competing network. SpaceX builds the rocket, flies it and runs Starlink, so it controlled the ride its rival needed.", "sources": [{"url": "https://spaceflightnow.com/2023/12/01/amazon-buys-three-launches-from-spacex-for-rival-internet-constellation/", "label": "Spaceflight Now, Amazon buys three launches from SpaceX, Dec 2023"}]}, "evidence": {"kind": "faceOff", "prompt": "Who held more bargaining power in this deal?", "left": {"name": "SpaceX", "note": "Owns the rocket that was ready to fly"}, "right": {"name": "Amazon", "note": "Needed launches before a deadline"}, "correctIndex": 0, "explanation": "Amazon had a deadline and few ready rockets. SpaceX had the ride."}, "numbers": {"kind": "numberSense", "prompt": "Amazon's 1,618 satellites were half its first-generation network. About how big was the full network, in thousands?", "min": 0, "max": 8, "value": 3.2, "unit": "K", "explanation": "About 3,200 satellites, so 1,618 was the first half."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked why Amazon would pay its biggest rival to launch.", "prompt": "What's your answer?", "options": ["Amazon wanted to help Starlink grow", "Its other rockets were not ready in time", "SpaceX offered the launches for free"], "correctIndex": 1, "consequences": ["It was a deadline, not goodwill.", "Ariane 6, New Glenn and Vulcan were all delayed.", "There is no sign the launches were free."], "explanation": "With a hard deadline and delayed rockets, the only ready ride belonged to a rival."}, "proReasoning": "Candidates who link deals to launch availability show they see the real constraint.", "commonMistake": "Reading the deal as friendship between rivals.", "mentalModel": "Follow the ride that is ready."}, "invest": {"call": {"kind": "theCall", "situation": "Amazon books launches from SpaceX, which also runs Starlink.", "prompt": "What does this say about SpaceX?", "options": ["It is losing the satellite internet race", "It has spare rockets it cannot sell", "It earns money even from its rivals"], "correctIndex": 2, "consequences": ["Selling launches does not mean losing.", "Its own satellites fill most rides.", "Rivals pay for its ride."], "explanation": "Owning the ride means competitors pay you to compete with you."}, "proReasoning": "Investors value a company that profits whichever side wins downstream.", "commonMistake": "Seeing the deal as a sign SpaceX is weak.", "mentalModel": "The ride owner wins either way."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your satellite network must launch on a deadline, and rockets are scarce.", "prompt": "What do you do?", "options": ["Book early with more than one provider", "Wait for a new rocket to be ready", "Trust that a deadline will be moved"], "correctIndex": 0, "consequences": ["Spreading bookings protects the deadline.", "New rockets often slip.", "Counting on an extension is a gamble."], "explanation": "Amazon spread bookings and still needed a rival. Book early and widely."}, "proReasoning": "Founders treat launch capacity as scarce and book ahead.", "commonMistake": "Betting a deadline on a rocket that has not flown.", "mentalModel": "Book early, book twice."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend is surprised that Amazon launches on SpaceX rockets.", "prompt": "Why does it happen?", "options": ["Every satellite must use SpaceX by law", "Few rockets were ready, and SpaceX had them", "Amazon owns part of SpaceX"], "correctIndex": 1, "consequences": ["No law requires it.", "Others were delayed, so Amazon rented the ready ride.", "Amazon does not own SpaceX."], "explanation": "Rivals still need a ride to orbit, and SpaceX had rockets that were ready."}, "proReasoning": "In space, competitors are often customers too.", "commonMistake": "Thinking rivals never do business together.", "mentalModel": "The ride decides."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9902cf7e7594$ml$]::text[]),
($ml$cf84a262-a442-5f4a-a366-e8d4782d4095$ml$::uuid, $ml$spacetech$ml$, 3, 2, $ml${"id": "spacetech-d3-c2", "title": "Most rides carry its own product", "lessonTitle": "Who holds the power in orbit", "slot": 2, "type": "connect", "brief": {"headline": "In 2025, 123 of SpaceX's 165 launches carried Starlink. Day 1 showed it flying most of the world's rockets; day 3 showed why that gives it power.", "kicker": "Connect day 1 and day 3: flying most rockets means owning the gate.", "fullText": "On day 1 you saw SpaceX fly 165 of 320 orbital launches in 2025. On day 3 you saw that it is vertically integrated: it builds the rockets, flies them, and runs Starlink on top.\n\nAbout three in four of its launches carried its own satellites. The remaining seats went to governments and other companies, often at prices below rivals like Arianespace and ULA, which charge upward of $100 million for similar launches.", "sources": [{"url": "https://www.jalopnik.com/2067687/spacex-half-orbital-rocket-launches-2025/", "label": "Jalopnik, SpaceX over half of 2025 launches"}, {"url": "https://www.fool.com/investing/2026/04/12/spacex-launches-more-rockets-than-anyone-else/", "label": "Motley Fool, SpaceX launches more than anyone"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each fact a sign of vertical integration?", "buckets": ["Integration", "Not integration"], "items": [{"text": "SpaceX builds its own rockets", "bucket": 0}, {"text": "It flies its own Starlink satellites", "bucket": 0}, {"text": "It sells internet service to users", "bucket": 0}, {"text": "Rivals charge over $100 million a launch", "bucket": 1}, {"text": "320 launches flew worldwide in 2025", "bucket": 1}], "explanation": "Integration means owning each step: rocket, launch and service. Rival prices and total counts are context."}, "numbers": {"kind": "numberSense", "prompt": "How many of SpaceX's 165 launches in 2025 did not carry Starlink?", "min": 0, "max": 165, "value": 42, "unit": "launches", "explanation": "165 minus 123 is 42 launches for other customers."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a satellite operator that launches with SpaceX.", "prompt": "What smart question do you ask?", "options": ["Which of the rockets looks best on video", "How many launches SpaceX flew back in 2010", "What happens if SpaceX fills its rides first"], "correctIndex": 2, "consequences": ["Looks do not decide launch risk.", "Old counts do not help today.", "That shows you see the dependence."], "explanation": "Most SpaceX flights carry its own satellites, so customers compete with Starlink for seats."}, "proReasoning": "Good questions name the real risk in a company's plan.", "commonMistake": "Assuming a seat is always available.", "mentalModel": "Ask about the seat, not the show."}, "invest": {"call": {"kind": "theCall", "situation": "You compare SpaceX with a launcher that only sells rides.", "prompt": "What gives SpaceX an edge?", "options": ["It fills most rockets with its own product", "It charges more for a launch than anyone else", "It flies fewer, larger and slower missions"], "correctIndex": 0, "consequences": ["Starlink keeps its rockets busy.", "Its prices are lower than rivals.", "It flies more than anyone."], "explanation": "A launcher with its own payloads keeps its rockets flying whatever outside demand does."}, "proReasoning": "Investors see integration as a cushion against weak demand.", "commonMistake": "Comparing launchers on price alone.", "mentalModel": "Own payloads keep rockets busy."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells launches only, with no satellites of your own.", "prompt": "What's your weak spot against SpaceX?", "options": ["Customers prefer integrated firms by law", "You depend fully on outside customers", "You have too many rockets to fly"], "correctIndex": 1, "consequences": ["No law favors integration.", "Without your own payloads, slow demand hurts.", "Few new launchers have spare rockets."], "explanation": "SpaceX fills its rides with Starlink. A launch-only company lives on outside demand."}, "proReasoning": "Founders plan for a dry spell in customer demand.", "commonMistake": "Assuming demand for launches will always be there.", "mentalModel": "Plan for empty months."}, "curiosity": {"call": {"kind": "theCall", "situation": "You learn three in four SpaceX launches carry its own satellites.", "prompt": "What does that mean?", "options": ["Most of its launches fail", "It no longer sells launches", "It is its own biggest customer"], "correctIndex": 2, "consequences": ["Its launches succeed almost every time.", "It still sells 42 launches a year.", "Starlink fills most of its rides."], "explanation": "SpaceX launches mostly for itself, which keeps its rockets busy."}, "proReasoning": "A company can be both the ride and the main passenger.", "commonMistake": "Thinking SpaceX launches mostly for others.", "mentalModel": "Its own best customer."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5954e640ea7a$ml$]::text[]),
($ml$6bc3cfba-21a4-590d-9e72-c5c82b7a1df0$ml$::uuid, $ml$spacetech$ml$, 3, 3, $ml${"id": "spacetech-d3-c3", "title": "Protect your launch plan", "lessonTitle": "Who holds the power in orbit", "slot": 3, "type": "decide", "brief": {"headline": "You run a satellite operator. Arianespace and ULA charge upward of $100 million for launches similar to Falcon 9, and about 40,000 objects are tracked in orbit.", "kicker": "Decide: how do you keep your satellites from waiting on the ground?", "fullText": "The lesson's rule: power sits with whoever controls the ride to orbit. SpaceX sells its spare seats below rival prices, but its own satellites fill most of its rockets.\n\nUseful orbits are also filling up. About 40,000 objects are tracked, and about 11,000 of them are active satellites. You need a ride on time and a slot that is not crowded.", "sources": [{"url": "https://www.fool.com/investing/2026/04/12/spacex-launches-more-rockets-than-anyone-else/", "label": "Motley Fool, SpaceX launches more than anyone"}, {"url": "https://www.esa.int/Space_Safety/Space_Debris/ESA_Space_Environment_Report_2025", "label": "ESA Space Environment Report 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each move cut your launch risk?", "buckets": ["Cuts risk", "Doesn't"], "items": [{"text": "Booking a second provider", "bucket": 0}, {"text": "Booking well before the satellite is done", "bucket": 0}, {"text": "Designing to fit two rockets", "bucket": 0}, {"text": "Waiting to book until launch day nears", "bucket": 1}, {"text": "Relying on one rocket only", "bucket": 1}], "explanation": "Early bookings and a second option keep a slip from grounding you."}, "numbers": {"kind": "numberSense", "prompt": "About 40,000 objects are tracked and about 11,000 are active satellites. How many are not, in thousands?", "min": 0, "max": 50, "value": 29, "unit": "K", "explanation": "About 29,000 tracked objects are debris or dead hardware."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the launch manager for a 20-satellite program.", "prompt": "What's your first move?", "options": ["Book a primary ride and a backup", "Pick the cheapest rocket and wait", "Leave launch to the end of the program"], "correctIndex": 0, "consequences": ["A backup keeps the program moving.", "Cheap does not help if it slips.", "Late booking means no seat."], "explanation": "Launch managers protect the schedule with a second option."}, "proReasoning": "The best launch plans assume something will slip.", "commonMistake": "Treating launch as a last-minute purchase.", "mentalModel": "Primary plus backup."}, "invest": {"call": {"kind": "theCall", "situation": "An operator relies on one launcher for its whole network.", "prompt": "How do you rate that plan?", "options": ["Irrelevant to the business", "Risky, one slip delays all revenue", "Safe, one supplier is simpler"], "correctIndex": 1, "consequences": ["Launch timing drives revenue.", "No launch means no service to sell.", "Simple is not the same as safe."], "explanation": "One launcher is one point of failure for the whole revenue plan."}, "proReasoning": "Investors discount plans that hang on a single ride.", "commonMistake": "Ignoring launch risk in a satellite plan.", "mentalModel": "One ride, one risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your first satellite is ready in nine months.", "prompt": "When do you book launch?", "options": ["When the satellite is finished", "After a rival launches first", "Now, and line up a backup"], "correctIndex": 2, "consequences": ["By then, seats may be gone.", "Waiting gains nothing.", "Early booking secures a seat."], "explanation": "Rides are scarce and planned far ahead. Book while you build."}, "proReasoning": "Founders book launch long before the hardware is done.", "commonMistake": "Building first and looking for a ride later.", "mentalModel": "Build and book together."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why satellite firms book rockets so far ahead.", "prompt": "What's the reason?", "options": ["Rides are scarce and planned far ahead", "Rockets take years to fuel", "Launch tickets get cheaper later"], "correctIndex": 0, "consequences": ["Seats fill early.", "Fueling takes hours, not years.", "Prices tend to rise, not fall."], "explanation": "Few rockets fly, and most seats are spoken for. Booking early secures one."}, "proReasoning": "Getting to orbit is planned like a rare flight, not a bus.", "commonMistake": "Thinking you can buy a launch like a train ticket.", "mentalModel": "Book early, fly on time."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3b486a53c972$ml$]::text[]),
($ml$710ed667-f430-539a-bf13-926543e1fad6$ml$::uuid, $ml$spacetech$ml$, 4, 1, $ml${"id": "spacetech-d4-c1", "title": "The middle-size rocket", "lessonTitle": "The numbers that decide space economics", "slot": 1, "type": "apply", "brief": {"headline": "In 2022, Firefly priced an Alpha launch at $15 million for up to 1,300 kg to orbit. That is roughly $11,500 per kilogram, against about $3,400 on a Falcon 9.", "kicker": "Apply the lesson: a smaller rocket costs more per kilogram.", "fullText": "Alpha reached orbit in October 2022 on its second attempt. Firefly placed it in the medium-lift segment, between small and heavy rockets, and planned six launches in 2023.\n\nFalcon 9 carries about 22 tons for an advertised $74 million. Per kilogram, Alpha costs several times more. Customers pick it when they need a whole rocket for one mission, on their own date and orbit.", "sources": [{"url": "https://www.cnbc.com/2022/10/03/firefly-aerospace-reaches-orbit-joining-spacex-rocket-lab-and-others.html", "label": "CNBC, Firefly reaches orbit, Oct 2022"}, {"url": "https://www.fool.com/investing/2026/04/12/spacex-launches-more-rockets-than-anyone-else/", "label": "Motley Fool, SpaceX launches more than anyone"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why would a customer pay Alpha's higher price per kilogram?", "options": ["It flies when and where they need", "It is cheaper in total for 20 tons", "It carries more than a Falcon 9"], "correctIndex": 0, "explanation": "A dedicated small rocket sells control over timing and orbit, not the lowest cost per kg."}, "numbers": {"kind": "numberSense", "prompt": "$15 million for 1,300 kg is about how many thousand dollars per kilogram?", "min": 0, "max": 30, "value": 11.5, "unit": "K", "explanation": "About $11,500 per kg, roughly three times Falcon 9."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you are asked to compare Alpha and Falcon 9.", "prompt": "What do you say first?", "options": ["Which of the two looks better at liftoff", "Only their total launch prices, nothing else", "Cost per kilogram, then what each one is for"], "correctIndex": 2, "consequences": ["Looks do not decide a purchase.", "Totals hide what you get per kg.", "That is how the industry compares rides."], "explanation": "Cost per kilogram is the industry's yardstick; mission fit explains why both sell."}, "proReasoning": "Engineers and analysts quote dollars per kilogram, then the use case.", "commonMistake": "Comparing launch prices without the mass they carry.", "mentalModel": "Per kilogram, then purpose."}, "invest": {"call": {"kind": "theCall", "situation": "A medium-lift launcher costs about $11,500 per kg against $3,400.", "prompt": "What must it prove?", "options": ["That enough customers need dedicated rides", "That it can beat Falcon 9 on price per kg", "That it can carry 22 tons"], "correctIndex": 0, "consequences": ["Its value is timing and orbit control.", "At its size, that is unlikely.", "That is a heavy rocket's job."], "explanation": "A smaller rocket can't win on cost per kg. It wins on customers who need their own ride."}, "proReasoning": "Investors ask which customers will pay for control, and how many.", "commonMistake": "Expecting small rockets to match heavy ones per kg.", "mentalModel": "Find the customers who pay for control."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your 800 kg satellite needs a specific orbit by a fixed date.", "prompt": "Which ride do you price first?", "options": ["Whatever is the cheapest per kg", "A dedicated medium rocket like Alpha", "A full Falcon 9 just for yourself"], "correctIndex": 1, "consequences": ["Cheapest per kg may not go your way.", "It fits your mass, orbit and date.", "You would pay for 22 tons of room."], "explanation": "A rocket sized to your satellite gives you your orbit and date without paying for empty room."}, "proReasoning": "Founders match the rocket to the mission before comparing prices.", "commonMistake": "Picking a ride on price per kg alone.", "mentalModel": "Size the rocket to the job."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why small rockets cost more per kilogram.", "prompt": "What's the reason?", "options": ["Small rockets burn a rarer, pricier fuel", "They have to fly much farther to orbit", "Many costs stay the same as rockets shrink"], "correctIndex": 2, "consequences": ["Fuel is not the main difference.", "They fly to the same orbits.", "Crews, pads and engines cost a lot at any size."], "explanation": "Building, testing and launching any rocket has big fixed costs, so fewer kilograms share them."}, "proReasoning": "Fixed costs spread over less mass make each kilogram cost more.", "commonMistake": "Thinking price scales evenly with size.", "mentalModel": "Small rockets carry fixed costs too."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4561b8cf5ca9$ml$]::text[]),
($ml$fb586bfd-1d45-5924-ab38-3fc255851f7a$ml$::uuid, $ml$spacetech$ml$, 4, 2, $ml${"id": "spacetech-d4-c2", "title": "When rides got a price tag", "lessonTitle": "The numbers that decide space economics", "slot": 2, "type": "connect", "brief": {"headline": "SpaceX raised Falcon 9's advertised price 6.1% in 2026, to $74 million. On day 2 you saw NASA start buying rides at fixed prices; on day 4, how buyers compare those prices.", "kicker": "Connect day 2 and day 4: a published price lets buyers compare rides.", "fullText": "Day 2 showed NASA paying fixed prices for crew rides, at an estimated $60 to $67 million per Crew Dragon seat. Day 4 showed buyers dividing launch prices by mass: about $74 million for 22 tons on Falcon 9 is roughly $3,400 per kilogram.\n\nOnce rides are sold as services at set prices, anyone can compare them. That is how cost per kilogram became the number every launch is judged by.", "sources": [{"url": "https://www.planetary.org/articles/nasas-commercial-crew-is-a-great-deal-for-the-agency", "label": "Planetary Society, commercial crew economics"}, {"url": "https://www.fool.com/investing/2026/04/12/spacex-launches-more-rockets-than-anyone-else/", "label": "Motley Fool, SpaceX launches more than anyone"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Falcon 9's advertised price rose 6.1% in 2026.", "A Crew Dragon seat costs NASA about $60 to $67 million.", "Under fixed-price crew deals, NASA paid every overrun."], "fakeIndex": 2, "explanation": "Under fixed price, the companies carried overruns, not NASA."}, "numbers": {"kind": "numberSense", "prompt": "Falcon 9's price rose 6.1% to $74 million. About what was it before, in millions?", "min": 0, "max": 100, "value": 70, "unit": "M", "explanation": "$74 million divided by 1.061 is about $70 million."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked how launch buyers compare offers.", "prompt": "What's your answer?", "options": ["They divide the price by the mass carried", "They pick the rocket with the most engines", "They choose the newest rocket"], "correctIndex": 0, "consequences": ["Dollars per kg puts rides side by side.", "Engine count is not a price.", "New does not mean cheaper."], "explanation": "Set prices and known capacity let buyers compare rides in dollars per kilogram."}, "proReasoning": "People who quote price per kg sound like they have bought a launch.", "commonMistake": "Comparing rockets on features instead of price per kg.", "mentalModel": "Price divided by mass."}, "invest": {"call": {"kind": "theCall", "situation": "SpaceX raises its advertised price 6.1% and keeps flying full rockets.", "prompt": "What does that tell you?", "options": ["Its customers are leaving for its rivals", "Demand is strong enough to bear higher prices", "Its costs must be running out of control"], "correctIndex": 1, "consequences": ["Rivals charge over $100 million.", "Full rockets at higher prices mean pricing power.", "A price rise alone does not show that."], "explanation": "Raising prices while rivals still charge more is a sign of pricing power."}, "proReasoning": "Investors read price increases alongside demand.", "commonMistake": "Reading every price rise as a cost problem.", "mentalModel": "Price up, demand steady: power."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your launch startup must publish a price.", "prompt": "What do you anchor it to?", "options": ["The highest price any rival charges", "Whatever customers once paid NASA", "Your cost per kg against Falcon 9"], "correctIndex": 2, "consequences": ["High prices lose to cheaper rides.", "NASA seat prices are a different product.", "Buyers will compare you to $3,400 per kg."], "explanation": "Buyers compare every ride with Falcon 9 per kilogram. Know where you sit."}, "proReasoning": "Founders know the benchmark their buyers use.", "commonMistake": "Pricing without a benchmark.", "mentalModel": "Know your price per kg."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why space prices are quoted per kilogram.", "prompt": "Why is it useful?", "options": ["It lets you compare rockets of any size", "Rockets are weighed before every launch", "It is a rule set by the FAA"], "correctIndex": 0, "consequences": ["Big and small rides become comparable.", "Weighing is not why it is used.", "No agency sets the unit."], "explanation": "Dividing price by mass turns very different rockets into one comparable number."}, "proReasoning": "One shared yardstick makes a market easier to read.", "commonMistake": "Thinking a launch price means the same across rockets.", "mentalModel": "One yardstick for every rocket."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d3f4510151f9$ml$]::text[]),
($ml$c3a2f7e7-d465-5e5b-8388-873edb14b680$ml$::uuid, $ml$spacetech$ml$, 4, 3, $ml${"id": "spacetech-d4-c3", "title": "Pay per launch or per kilogram", "lessonTitle": "The numbers that decide space economics", "slot": 3, "type": "decide", "brief": {"headline": "You plan a 600 kg satellite. Rocket Lab's Electron costs about $8.4 million but carries less than a ton. A Falcon 9 costs $74 million for about 22 tons.", "kicker": "Decide: which price matters for your mission?", "fullText": "The lesson's rule: cost per kilogram decides what is worth launching. Falcon 9 works out to about $3,400 per kilogram, far below Electron.\n\nBut you do not need 22 tons. Buying a whole Falcon 9 for 600 kg would cost far more in total than an Electron. The cheapest price per kilogram is not always the cheapest launch for you.", "sources": [{"url": "https://www.fool.com/investing/2026/04/12/spacex-launches-more-rockets-than-anyone-else/", "label": "Motley Fool, SpaceX launches more than anyone"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which rocket does each fact describe?", "buckets": ["Falcon 9", "Electron"], "items": [{"text": "Lower price per launch", "bucket": 1}, {"text": "Lower price per kilogram", "bucket": 0}, {"text": "About 22 tons to low orbit", "bucket": 0}, {"text": "Carries less than a ton", "bucket": 1}, {"text": "About $74 million advertised", "bucket": 0}], "explanation": "Electron is cheaper per launch; Falcon 9 is cheaper per kilogram."}, "numbers": {"kind": "numberSense", "prompt": "Falcon 9 is about $3,400 per kg; Electron is $8.4 million for under a ton. Electron per kg is at least how many times?", "min": 0, "max": 6, "value": 2.5, "unit": "x", "explanation": "$8.4 million for 1,000 kg is $8,400 per kg, about 2.5 times Falcon 9, and more for lighter loads."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager wants the cheapest ride for a 600 kg satellite.", "prompt": "What do you recommend?", "options": ["Always buy the smallest rocket on offer", "Compare total cost for your mass, not per kg", "Always buy the lowest price per kg there is"], "correctIndex": 1, "consequences": ["Smallest may not reach your orbit.", "A whole Falcon 9 costs $74 million total.", "Per kg helps only if you fill the rocket."], "explanation": "For one small satellite, the total bill matters. Per kg helps when you can use the capacity."}, "proReasoning": "Analysts ask what the customer actually pays, not just the unit price.", "commonMistake": "Quoting cost per kg for a rocket you would barely fill.", "mentalModel": "Total cost for your mass."}, "invest": {"call": {"kind": "theCall", "situation": "A launcher has the lowest cost per kg but sells only whole rockets.", "prompt": "Who will it lose?", "options": ["Large constellations", "Governments with big payloads", "Small customers who cannot fill it"], "correctIndex": 2, "consequences": ["They can fill a rocket.", "Big payloads use the capacity.", "They pay for empty space."], "explanation": "Low cost per kg only helps buyers who fill the rocket, or share it."}, "proReasoning": "Investors check which customers a pricing model actually fits.", "commonMistake": "Assuming the lowest unit price wins every customer.", "mentalModel": "Match price model to customer."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup can launch one 600 kg satellite or wait and launch five.", "prompt": "How does that change the math?", "options": ["Five may fill a big rocket and cut cost per kg", "One satellite is always cheapest", "The number of satellites does not matter"], "correctIndex": 0, "consequences": ["More mass makes a big rocket's price pay off.", "Not if you can share or fill a bigger ride.", "Mass changes which rocket is cheapest."], "explanation": "The more mass you launch together, the more a big rocket's low per kg price helps."}, "proReasoning": "Founders plan batches to make cheaper rides worth it.", "commonMistake": "Planning launches one satellite at a time without checking batches.", "mentalModel": "Batch to use the cheap ride."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks the cheapest rocket per kg is always the best deal.", "prompt": "What do you say?", "options": ["No, small rockets are always cheaper", "Only if you can use most of its room", "Yes, always pick the lowest per kg"], "correctIndex": 1, "consequences": ["Per kg, small rockets cost more.", "Empty room still costs money.", "A whole rocket costs its full price."], "explanation": "A big rocket is cheap per kg only when you fill it. One small satellite may cost less on a small rocket."}, "proReasoning": "Unit prices help when you buy the whole unit.", "commonMistake": "Confusing a low unit price with a low bill.", "mentalModel": "Cheap per kg needs a full rocket."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:30f7fb0ee24e$ml$]::text[]),
($ml$9b817028-f126-5215-80aa-a03ea035709d$ml$::uuid, $ml$spacetech$ml$, 5, 1, $ml${"id": "spacetech-d5-c1", "title": "The first space junk fine", "lessonTitle": "The rules that govern orbit", "slot": 1, "type": "apply", "brief": {"headline": "In October 2023, the FCC fined Dish $150,000, its first space debris fine. Dish had planned to retire EchoStar-7 300 km above geostationary orbit, but it ended up only 122 km above.", "kicker": "Apply the lesson: cleanup plans are now enforced.", "fullText": "EchoStar-7 launched in February 2002. Dish's debris plan promised to move it to a disposal orbit 300 km above the busy geostationary ring when its mission ended. It fell well short.\n\nIn the settlement on October 2, 2023, Dish admitted liability and paid the penalty. The amount was small, but the message was not: a satellite's end-of-life plan is a promise regulators can hold an operator to.", "sources": [{"url": "https://www.satellitetoday.com/government-military/2023/10/03/fcc-fines-dish-150000-for-failed-deorbit/", "label": "Via Satellite, FCC fines Dish $150,000, Oct 2023"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the case in order.", "steps": ["EchoStar-7 launches in 2002", "Dish plans to retire it 300 km higher", "The satellite ends up only 122 km higher", "Dish admits liability and pays $150,000"], "explanation": "A disposal plan made at licensing became the standard the FCC enforced years later."}, "numbers": {"kind": "numberSense", "prompt": "EchoStar-7 was to rise 300 km above geostationary orbit but reached 122 km. How many km short?", "min": 0, "max": 300, "value": 178, "unit": "km", "explanation": "178 km short of the planned disposal orbit."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a satellite operations engineer near a satellite's end of life.", "prompt": "What do you protect first?", "options": ["Enough fuel to reach the disposal orbit", "One more year of paid service to customers", "The spare parts kept on board the craft"], "correctIndex": 0, "consequences": ["That keeps the debris plan you filed.", "Extra service can leave too little fuel.", "Parts do not move a satellite."], "explanation": "Dish fell short of its disposal orbit. Saving fuel for the last move is part of the job."}, "proReasoning": "Operators plan the last maneuver as carefully as the first.", "commonMistake": "Treating end of life as an afterthought.", "mentalModel": "Save fuel for the exit."}, "invest": {"call": {"kind": "theCall", "situation": "The FCC issues its first debris fine, only $150,000.", "prompt": "Why might it still matter?", "options": ["It applies only to Dish", "It shows the rules will be enforced", "It will bankrupt satellite operators"], "correctIndex": 1, "consequences": ["The rule covers every licensee.", "A first fine sets a precedent.", "$150,000 is small for an operator."], "explanation": "The first fine signals that debris plans are binding. Bigger cases can follow."}, "proReasoning": "Investors watch first enforcement actions as signals of future cost.", "commonMistake": "Dismissing a small fine as noise.", "mentalModel": "Precedent, not the price."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're designing your company's first satellite.", "prompt": "How do you treat the disposal plan?", "options": ["As paperwork to file once and then forget", "As a problem for some future team to solve", "As a design requirement with fuel set aside"], "correctIndex": 2, "consequences": ["Dish found out it is enforced.", "Later fixes cost more.", "Regulators can hold you to it."], "explanation": "Your filing becomes a promise. Design the fuel and the plan in from the start."}, "proReasoning": "Founders budget for the end of a satellite's life on day one.", "commonMistake": "Filing a debris plan the hardware cannot meet.", "mentalModel": "Design the exit in."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a TV company was fined over space.", "prompt": "What's the reason?", "options": ["Its old satellite was not moved far enough", "It broadcast TV without a valid license", "It launched its own rocket illegally"], "correctIndex": 0, "consequences": ["It stopped 122 km up, not 300 km.", "The fine was about debris.", "Dish did not launch a rocket."], "explanation": "Dead satellites must be moved out of busy orbits. Dish moved EchoStar-7 too little."}, "proReasoning": "Even old satellites come with cleanup duties.", "commonMistake": "Thinking space has no rules once you are up there.", "mentalModel": "Clean up after your satellite."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:83299a14911e$ml$]::text[]),
($ml$2ad1cb9c-a936-5e7d-a7a2-ffe340836b50$ml$::uuid, $ml$spacetech$ml$, 5, 2, $ml${"id": "spacetech-d5-c2", "title": "Crowding meets cleanup", "lessonTitle": "The rules that govern orbit", "slot": 2, "type": "connect", "brief": {"headline": "About 40,000 objects are tracked in orbit, and only about 11,000 are active satellites. Day 3 showed orbits filling up; day 5 showed why the FCC cut the deorbit limit from 25 years to 5.", "kicker": "Connect day 3 and day 5: a crowded orbit needs faster cleanup.", "fullText": "On day 3 you saw useful orbits filling up. On day 5 you saw ESA's warning: more than 1.2 million pieces of debris larger than 1 cm orbit Earth, and collisions create new debris faster than old debris falls back.\n\nThat is why the FCC now requires low-orbit satellites to deorbit within five years of their mission ending. Each dead satellite left up is one more object everyone else must avoid.", "sources": [{"url": "https://www.esa.int/Space_Safety/Space_Debris/ESA_Space_Environment_Report_2025", "label": "ESA Space Environment Report 2025"}, {"url": "https://www.satellitetoday.com/government-military/2022/09/30/fcc-adopts-5-year-rule-for-deorbiting-satellites/", "label": "Via Satellite, FCC five-year deorbit rule"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why can operators not just wait for debris to fall back to Earth?", "options": ["Collisions make debris faster than it falls", "Debris never falls back to Earth at all", "Letting debris fall back is against the law"], "correctIndex": 0, "explanation": "ESA says debris keeps growing because collisions add pieces faster than drag removes them."}, "numbers": {"kind": "numberSense", "prompt": "About 11,000 of 40,000 tracked objects are active satellites. About what percent is that?", "min": 0, "max": 60, "value": 28, "unit": "%", "explanation": "About 28%. Most tracked objects are dead hardware or debris."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a team running 200 low-orbit satellites.", "prompt": "What part of the job grows as orbits fill?", "options": ["Choosing launch music", "Tracking debris and planning disposal", "Designing logos for each satellite"], "correctIndex": 1, "consequences": ["Not part of operations.", "Crowding makes both daily work.", "Logos do not affect safety."], "explanation": "More objects mean more tracking, more avoidance and stricter disposal."}, "proReasoning": "Operators treat debris as a daily operating task.", "commonMistake": "Assuming space is empty enough to ignore debris.", "mentalModel": "Track, avoid, dispose."}, "invest": {"call": {"kind": "theCall", "situation": "Debris grows faster than it falls, and orbits are filling.", "prompt": "What long-term risk do you note?", "options": ["Launch prices will fall to zero", "Satellites will stop needing fuel", "Busy orbits could become costly to use"], "correctIndex": 2, "consequences": ["Debris does not lower prices.", "Avoidance uses more fuel.", "More avoidance and stricter rules add cost."], "explanation": "A cascade of collisions is a tail risk for every operator in a crowded orbit."}, "proReasoning": "Investors treat orbital crowding as a shared, rising cost.", "commonMistake": "Ignoring debris in a long-term satellite plan.", "mentalModel": "Crowding is a cost."}, "build_startup": {"call": {"kind": "theCall", "situation": "Debris keeps growing and the FCC now demands deorbit within five years.", "prompt": "Where is the opening?", "options": ["Services that help operators deorbit on time", "Satellites built so they never deorbit", "Fighting the five-year rule in court"], "correctIndex": 0, "consequences": ["Every operator now has this need.", "They would break the rule.", "The rule is already in force."], "explanation": "A rule every operator must meet creates demand for tools that help them meet it."}, "proReasoning": "Founders build for obligations that every customer shares.", "commonMistake": "Betting against a rule that is already in force.", "mentalModel": "Sell the solution to the rule."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why rules on space junk got tougher.", "prompt": "What's the reason?", "options": ["Rockets got louder at every launch", "Orbits are crowding and debris keeps growing", "Satellites got heavier and more costly"], "correctIndex": 1, "consequences": ["Noise is not the issue.", "More objects raise collision risk for all.", "Weight is not the issue."], "explanation": "More satellites and growing debris make every collision more costly, so cleanup got stricter."}, "proReasoning": "Shared orbits need shared rules.", "commonMistake": "Thinking space is too big to crowd.", "mentalModel": "Crowded orbits, tougher rules."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9b38aad84fca$ml$]::text[]),
($ml$0f03bfa4-6970-5f36-9d0b-5d3ec8a9c4a5$ml$::uuid, $ml$spacetech$ml$, 5, 3, $ml${"id": "spacetech-d5-c3", "title": "Plan the exit before launch", "lessonTitle": "The rules that govern orbit", "slot": 3, "type": "decide", "brief": {"headline": "You run a startup launching 100 low-orbit satellites. US rules require each one to deorbit within five years after its mission ends, down from 25.", "kicker": "Decide: how do you meet the five-year rule?", "fullText": "The FCC licenses satellites and sets the deorbit rule; the FAA licenses launches. Under the 2022 rule, low-orbit satellites must deorbit as soon as practicable and no later than five years after their mission ends.\n\nYou can add propulsion to lower each satellite at the end, or rely on drag and hope it is fast enough. Your design choice decides whether you can prove you comply.", "sources": [{"url": "https://www.satellitetoday.com/government-military/2022/09/30/fcc-adopts-5-year-rule-for-deorbiting-satellites/", "label": "Via Satellite, FCC five-year deorbit rule"}, {"url": "https://www.esa.int/Space_Safety/Space_Debris/ESA_Space_Environment_Report_2025", "label": "ESA Space Environment Report 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Which design makes the five-year rule easier to prove?", "left": {"name": "Satellite with its own deorbit thruster", "note": "Lowers itself when the mission ends"}, "right": {"name": "Satellite that relies on drag alone", "note": "Falls when the air slows it"}, "correctIndex": 0, "explanation": "Propulsion lets you choose when to come down instead of waiting on the air."}, "numbers": {"kind": "numberSense", "prompt": "The FCC cut the allowed time from 25 years to 5. How many times shorter is it?", "min": 0, "max": 12, "value": 5, "unit": "x", "explanation": "Five times shorter, with two years given to adjust."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a systems engineer sizing the satellite's fuel.", "prompt": "What do you include?", "options": ["Only enough for the mission", "As little as possible to save mass", "Enough to deorbit within five years"], "correctIndex": 2, "consequences": ["Then disposal is left to chance.", "Saving mass can cost your license.", "The rule makes disposal part of the mission."], "explanation": "Disposal is now a requirement, so the fuel budget must include it."}, "proReasoning": "Engineers size the fuel for the whole life, ending included.", "commonMistake": "Treating deorbit as optional.", "mentalModel": "Budget the last burn."}, "invest": {"call": {"kind": "theCall", "situation": "Two constellations plan 100 satellites; one has no deorbit thrusters.", "prompt": "Which one carries more risk?", "options": ["The one without thrusters", "The one with thrusters", "Neither, rules do not matter"], "correctIndex": 0, "consequences": ["It may not prove compliance.", "Thrusters add control.", "The FCC enforces debris plans."], "explanation": "Without a way to lower its satellites, an operator may struggle to meet the rule."}, "proReasoning": "Investors ask how each satellite leaves orbit.", "commonMistake": "Ignoring disposal in a constellation plan.", "mentalModel": "Ask how it comes down."}, "build_startup": {"call": {"kind": "theCall", "situation": "Adding thrusters raises each satellite's cost.", "prompt": "How do you decide?", "options": ["Wait and hope that the rule will change", "Weigh the cost against keeping your license", "Cut the thrusters out to save money now"], "correctIndex": 1, "consequences": ["The rule is already in force.", "Losing the license costs far more.", "Then you may not comply."], "explanation": "Compliance is a cost of being allowed to operate. Price it in."}, "proReasoning": "Founders treat rules as fixed costs, not options.", "commonMistake": "Saving money by designing out compliance.", "mentalModel": "Pay to stay licensed."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what happens to satellites when they stop working.", "prompt": "What do you say?", "options": ["They stay up in orbit forever", "Astronauts go up to collect them", "They must come down within five years"], "correctIndex": 2, "consequences": ["Most low satellites must come down.", "No one collects them.", "US rules require deorbit within five years."], "explanation": "In low orbit, dead satellites must be brought down within five years under US rules."}, "proReasoning": "Satellites now need a plan for their own ending.", "commonMistake": "Imagining space as a place where junk just floats away.", "mentalModel": "Down within five years."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d699b911962b$ml$]::text[]),
($ml$c9b6dbb8-03f8-59b8-bdb0-377542e4a697$ml$::uuid, $ml$spacetech$ml$, 6, 1, $ml${"id": "spacetech-d6-c1", "title": "Europe's navigation on an American rocket", "lessonTitle": "Europe's year without a rocket", "slot": 1, "type": "apply", "brief": {"headline": "On April 28, 2024, a SpaceX Falcon 9 launched two of Europe's Galileo navigation satellites. They had first been assigned to Ariane 6, which was nearly four years late.", "kicker": "Apply the lesson: with no rocket of its own, Europe rented one.", "fullText": "Galileo is Europe's own navigation system, built so Europe would not depend on anyone else. Yet with Ariane 5 retired and Ariane 6's first flight slipping to mid-2024, its satellites flew from Florida on an American rocket.\n\nThe mission needed so much performance that SpaceX did not recover the booster. Meanwhile ESA approved an extra €210 million a year to support Ariane 6, bringing ArianeGroup's support to €350 million a year.", "sources": [{"url": "https://europeanspaceflight.com/falcon-9-galileo-launch-highlights-ariane-6-failure/", "label": "European Spaceflight, Falcon 9 Galileo launch, Apr 2024"}]}, "evidence": {"kind": "faceOff", "prompt": "Which risk did this launch show most clearly?", "left": {"name": "Depending on one launcher", "note": "Ariane 6 was late, so plans broke"}, "right": {"name": "Running out of satellites", "note": "Europe had no satellites to launch"}, "correctIndex": 0, "explanation": "The satellites were ready. The rocket was not, so Europe needed someone else's."}, "numbers": {"kind": "numberSense", "prompt": "ESA's extra €210 million a year brought ArianeGroup's support to €350 million. What was it before, in millions?", "min": 0, "max": 400, "value": 140, "unit": "M", "explanation": "€350 million minus €210 million is €140 million a year before the increase."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work on Galileo's launch plan when Ariane 6 slips again.", "prompt": "What do you prepare?", "options": ["A request to redesign the satellites", "A case for moving to another rocket", "A plan to store the satellites for years"], "correctIndex": 1, "consequences": ["The satellites were ready to fly.", "Europe did move them to a Falcon 9.", "Storage delays a system Europe needs."], "explanation": "When the rocket is the bottleneck, the fix is another rocket, even a rival's."}, "proReasoning": "Launch planners keep a backup option ready before they need it.", "commonMistake": "Assuming a delayed rocket is the only option.", "mentalModel": "Have the backup ready."}, "invest": {"call": {"kind": "theCall", "situation": "Europe launches its own navigation satellites on a SpaceX rocket.", "prompt": "What does that tell you about the market?", "options": ["European rockets now lead the market", "Navigation satellites are losing value", "Who can fly on time wins the contract"], "correctIndex": 2, "consequences": ["Ariane 6 was the one that slipped.", "Galileo still mattered enough to fly.", "Delays send work to whoever can fly."], "explanation": "Even politically sensitive work moves to a reliable rocket when the home option is late."}, "proReasoning": "Investors follow work to the launcher that actually flies.", "commonMistake": "Assuming customers stay loyal through long delays.", "mentalModel": "Reliability wins the work."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup builds a European launcher.", "prompt": "What does the Galileo launch tell you?", "options": ["Europe pays a premium to fly its own way", "European customers will always wait for you", "Navigation work never goes abroad"], "correctIndex": 0, "consequences": ["It funds Ariane 6 to avoid more of this.", "Galileo did not wait.", "It went to Florida."], "explanation": "Europe dislikes depending on others, and pays to avoid it. An on-time launcher has buyers."}, "proReasoning": "Founders sell independence to customers who were burned by delays.", "commonMistake": "Promising dates you cannot keep to a customer who has been let down.", "mentalModel": "Sell independence that flies on time."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Europe launched its own satellites from Florida.", "prompt": "What's the reason?", "options": ["Europe had sold its rockets to the US", "Its new rocket was years late", "Florida is closer to the satellites' orbit"], "correctIndex": 1, "consequences": ["Europe did not sell its rockets.", "Ariane 6 slipped to mid-2024.", "Launch site was not the reason."], "explanation": "With Ariane 5 retired and Ariane 6 late, Europe had no rocket of its own for the job."}, "proReasoning": "Owning satellites is not enough; you also need a way up.", "commonMistake": "Thinking every country can launch its own satellites.", "mentalModel": "No rocket, no choice."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:6945b5128fe6$ml$]::text[]),
($ml$32397bee-a791-59c9-8444-8db482a10f24$ml$::uuid, $ml$spacetech$ml$, 6, 2, $ml${"id": "spacetech-d6-c2", "title": "When the ride owner holds the cards", "lessonTitle": "Europe's year without a rocket", "slot": 2, "type": "connect", "brief": {"headline": "Launches from Europe's Kourou spaceport fell from 15 in 2021 to six in 2022, and ESA put its Euclid telescope on a Falcon 9. Day 3 said power sits with whoever controls the ride.", "kicker": "Connect day 3 and day 6: losing your rocket means renting power.", "fullText": "On day 3 you saw that SpaceX controls the ride to orbit, so rivals plan around its schedule. On day 6 you saw Europe lose Ariane 5, Soyuz and Vega-C within about a year.\n\nWithout its own launcher, Europe became one of SpaceX's customers. Ariane 6 finally flew on July 9, 2024, four years after its original 2020 target, and Europe got its own ride back.", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}, {"url": "https://www.jalopnik.com/2067687/spacex-half-orbital-rocket-launches-2025/", "label": "Jalopnik, SpaceX over half of 2025 launches"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Kourou launches fell from 15 in 2021 to six in 2022.", "Ariane 6 first flew on July 9, 2024.", "Soyuz kept flying from Kourou through 2023."], "fakeIndex": 2, "explanation": "Russia pulled Soyuz from Kourou in 2022, one of the three losses that left Europe without a rocket."}, "numbers": {"kind": "numberSense", "prompt": "Kourou launches fell from 15 in 2021 to six in 2022. By what percent did they fall?", "min": 0, "max": 100, "value": 60, "unit": "%", "explanation": "Nine fewer launches out of 15 is a 60% drop."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked what Europe's launch gap teaches about space.", "prompt": "What's your answer?", "options": ["Telescopes should never be launched", "Europe should stop building rockets", "Controlling your own ride is power"], "correctIndex": 2, "consequences": ["Euclid flew, just on a rival rocket.", "Ariane 6 restored its access.", "That links day 3 and day 6."], "explanation": "Without its own rocket, Europe had to take a rival's schedule and terms."}, "proReasoning": "Strong answers connect a story to a rule about power.", "commonMistake": "Telling the story without the lesson.", "mentalModel": "Own the ride, own the plan."}, "invest": {"call": {"kind": "theCall", "situation": "A region loses its rockets for a year and rents a rival's.", "prompt": "Who gains?", "options": ["The launcher that still flies", "The region's own rocket maker", "Satellite insurers"], "correctIndex": 0, "consequences": ["It takes the work the gap creates.", "It lost launches during the gap.", "Insurers are not the winners here."], "explanation": "A gap in one supplier sends business to whoever can still fly."}, "proReasoning": "Investors watch rivals' delays as a source of new contracts.", "commonMistake": "Missing how one company's gap becomes another's revenue.", "mentalModel": "Gaps move revenue."}, "build_startup": {"call": {"kind": "theCall", "situation": "Europe now has Ariane 6 again, after a painful year.", "prompt": "Is there still room for new launchers?", "options": ["Only if they copy Ariane 6 exactly", "Yes, Europe wants more than one option", "No, Ariane 6 solves the problem for good"], "correctIndex": 1, "consequences": ["Copying does not add a real backup.", "One launcher is still a single point of failure.", "One rocket can slip again."], "explanation": "One rocket is still one point of failure. A second European option has a case."}, "proReasoning": "Founders pitch resilience to customers who lived through a gap.", "commonMistake": "Assuming one new rocket ends the problem.", "mentalModel": "Be the second option."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how Europe launched its telescope without a rocket.", "prompt": "What happened?", "options": ["It waited four years for Ariane 6", "It borrowed a Russian rocket", "It paid SpaceX to launch it"], "correctIndex": 2, "consequences": ["It did not wait.", "Soyuz had left Kourou.", "Euclid flew on a Falcon 9."], "explanation": "With no rocket of its own, ESA bought a ride from a competitor."}, "proReasoning": "In space, even agencies buy rides from rivals.", "commonMistake": "Thinking each agency always flies its own rockets.", "mentalModel": "It rented a ride."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e08779814426$ml$]::text[]),
($ml$381f683a-87f3-5d4f-a80f-1fb71166a1c2$ml$::uuid, $ml$spacetech$ml$, 6, 3, $ml${"id": "spacetech-d6-c3", "title": "Your launch slips a year", "lessonTitle": "Europe's year without a rocket", "slot": 3, "type": "decide", "brief": {"headline": "You run a European satellite company. Your Ariane 6 launch just slipped by a year. Ariane 6 flew first in July 2024, and six launches were planned for 2025.", "kicker": "Decide: wait for the home rocket or move to another?", "fullText": "Ariane 6's first flight came four years after its 2020 target. Six launches were planned for 2025 and eight for 2026, so seats are limited.\n\nYour satellite is built. Every month on the ground is a month with no revenue. ESA itself moved Euclid to a Falcon 9 rather than wait.", "sources": [{"url": "https://www.voanews.com/a/europe-s-ariane-6-rocket-successfully-launches-for-first-time-/7691622.html", "label": "VOA, Ariane 6 first launch"}, {"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each fact push you to switch rockets?", "buckets": ["Push to switch", "Push to wait"], "items": [{"text": "Every month grounded means no revenue", "bucket": 0}, {"text": "Only six Ariane 6 flights planned for 2025", "bucket": 0}, {"text": "ESA moved Euclid to a Falcon 9", "bucket": 0}, {"text": "A customer contract requires a European rocket", "bucket": 1}, {"text": "A deal pays you to stay on Ariane 6", "bucket": 1}], "explanation": "Lost months and few seats argue for switching; contract terms can argue for waiting."}, "numbers": {"kind": "numberSense", "prompt": "Ariane 6 flew in July 2024; its original target was 2020. How many years late?", "min": 0, "max": 10, "value": 4, "unit": "years", "explanation": "About four years late."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the program manager whose launch slipped a year.", "prompt": "What do you bring to leadership?", "options": ["The cost of waiting next to a backup offer", "An apology and a new launch date only", "A plan to cancel the satellite entirely"], "correctIndex": 0, "consequences": ["That turns a delay into a decision.", "A date alone hides the cost.", "You would waste a built satellite."], "explanation": "Leaders decide better when the cost of waiting sits beside a real alternative."}, "proReasoning": "Good managers bring options, not just bad news.", "commonMistake": "Reporting a slip without a choice.", "mentalModel": "Bring the options."}, "invest": {"call": {"kind": "theCall", "situation": "A satellite firm you own waits a year for a delayed rocket.", "prompt": "What do you ask management?", "options": ["If the satellite can be painted", "Why not a backup ride sooner", "Whether the rocket looks good"], "correctIndex": 1, "consequences": ["Paint is irrelevant.", "A year without revenue is costly.", "Looks do not move revenue."], "explanation": "A year on the ground is a year of lost revenue. Investors ask what it costs to wait."}, "proReasoning": "Investors push management to price the delay.", "commonMistake": "Accepting a long slip without asking why.", "mentalModel": "Price the wait."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your satellite is built; your European launch slipped a year.", "prompt": "What do you do?", "options": ["Wait for the European rocket, however long", "Cancel the satellite and refund customers", "Book a backup launch with another provider"], "correctIndex": 2, "consequences": ["A year grounded means no revenue.", "Cancelling wastes the satellite.", "ESA did the same with Euclid."], "explanation": "One launch option is a single point of failure. Europe learned that in 2023."}, "proReasoning": "Founders keep the business moving when a supplier slips.", "commonMistake": "Letting one supplier set your whole timeline.", "mentalModel": "Fly with whoever can."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a company wouldn't just wait for its rocket.", "prompt": "What's the downside?", "options": ["A satellite on the ground earns nothing", "Satellites expire if kept on the shelf", "Rockets get banned after long delays"], "correctIndex": 0, "consequences": ["No orbit, no service, no revenue.", "They do not expire on a shelf.", "Delays do not ban rockets."], "explanation": "A built satellite costs money every month it does not fly."}, "proReasoning": "In space, time on the ground is money lost.", "commonMistake": "Thinking waiting is free.", "mentalModel": "Grounded means unpaid."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:92175597547c$ml$]::text[]),
($ml$d576fb03-2db2-5679-8a1e-dd5cb33faedc$ml$::uuid, $ml$spacetech$ml$, 7, 1, $ml${"id": "spacetech-d7-c1", "title": "Two old orbits join forces", "lessonTitle": "Three orbits, three businesses", "slot": 1, "type": "apply", "brief": {"headline": "In July 2025, SES completed its purchase of Intelsat. The combined fleet has about 90 satellites in geostationary orbit and nearly 30 in medium orbit, with €3.7 billion in pro forma revenue.", "kicker": "Apply the lesson: orbits shape the business, so operators mix them.", "fullText": "SES and Intelsat were two of the oldest geostationary operators. Together they hold a contract backlog above €8 billion and expect about €370 million a year in savings.\n\nThe combined company sells what it calls multi-orbit service: geostationary satellites that each see a huge area, plus medium-orbit satellites closer to Earth, with access to low-orbit capacity. Different orbits suit different customers, so the merger puts more of them under one roof.", "sources": [{"url": "https://www.ses.com/press-release/ses-completes-acquisition-intelsat-creating-global-multi-orbit-connectivity", "label": "SES, completes acquisition of Intelsat, Jul 2025"}, {"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, "evidence": {"kind": "sortSignal", "prompt": "Match each fact to its orbit.", "buckets": ["Geostationary", "Medium"], "items": [{"text": "About 90 of the merged fleet", "bucket": 0}, {"text": "Nearly 30 of the merged fleet", "bucket": 1}, {"text": "One satellite sees a third of the planet", "bucket": 0}, {"text": "Home of GPS, near 20,000 km", "bucket": 1}, {"text": "Stays over one spot all day", "bucket": 0}], "explanation": "Most of the fleet is geostationary, at 35,786 km; the rest flies in medium orbit."}, "numbers": {"kind": "numberSense", "prompt": "About 90 geostationary and nearly 30 medium-orbit satellites. About how many in total?", "min": 0, "max": 200, "value": 120, "unit": "satellites", "explanation": "About 120 satellites across two orbits."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at the merged SES after the deal.", "prompt": "What do you show you understand?", "options": ["That bigger companies always pay more", "The share price on the closing day", "Why selling from two orbits helps customers"], "correctIndex": 2, "consequences": ["Pay is not the point of the deal.", "One day of trading says little.", "Each orbit suits different needs."], "explanation": "The deal joins two orbits so one company can serve more kinds of customers."}, "proReasoning": "Candidates who explain the orbit logic show real industry sense.", "commonMistake": "Seeing a merger as only about size.", "mentalModel": "Explain the orbit logic."}, "invest": {"call": {"kind": "theCall", "situation": "SES buys Intelsat and expects €370 million a year in savings.", "prompt": "What else do you weigh?", "options": ["How the mixed fleet competes for customers", "Only the yearly savings target in euros", "Only the total number of satellites"], "correctIndex": 0, "consequences": ["Revenue growth needs customers, not just cuts.", "Savings help, but growth decides value.", "Counts do not show demand."], "explanation": "Savings are one part. The other is whether two orbits win business a single orbit could not."}, "proReasoning": "Investors test both the cost case and the revenue case of a merger.", "commonMistake": "Valuing a merger on its savings alone.", "mentalModel": "Costs and customers."}, "build_startup": {"call": {"kind": "theCall", "situation": "Big operators now sell service from several orbits.", "prompt": "Where can a startup fit?", "options": ["Competing on fleet size", "Tools that route traffic across orbits", "Another single geostationary satellite"], "correctIndex": 1, "consequences": ["You cannot outbuild them.", "Multi-orbit service needs that software.", "One satellite cannot match their reach."], "explanation": "Mixing orbits creates a need to manage traffic across them. That is a niche to fill."}, "proReasoning": "Founders find gaps that big mergers create.", "commonMistake": "Trying to beat incumbents at their own scale.", "mentalModel": "Build what the giants need."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why two satellite companies merged.", "prompt": "What's one reason?", "options": ["Their satellites were in the same spot", "Merging lets satellites fly faster", "Different orbits suit different customers"], "correctIndex": 2, "consequences": ["Location was not the reason.", "Speed is set by the orbit.", "Together they cover more needs."], "explanation": "Geostationary and medium orbits serve different jobs. Together they offer more."}, "proReasoning": "Orbits are like neighborhoods, each suited to certain businesses.", "commonMistake": "Thinking all satellites do the same job.", "mentalModel": "More orbits, more customers."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5f6fd922d3ed$ml$]::text[]),
($ml$f62563f6-5387-597c-becb-67570dd7644f$ml$::uuid, $ml$spacetech$ml$, 7, 2, $ml${"id": "spacetech-d7-c2", "title": "Which orbits the five-year rule covers", "lessonTitle": "Three orbits, three businesses", "slot": 2, "type": "connect", "brief": {"headline": "Day 5's FCC rule says satellites in low Earth orbit must deorbit within five years after their mission. Day 7 showed where low orbit ends: about 2,000 km up.", "kicker": "Connect day 5 and day 7: the rule depends on the orbit.", "fullText": "On day 5 you saw the FCC cut the time a dead satellite may stay in low orbit from 25 years to 5. On day 7 you saw three orbits: low, from about 160 to 2,000 km; medium, where GPS flies near 20,000 km; and geostationary, at 35,786 km.\n\nThe five-year rule is written for low orbit, where traffic is densest and thin air can help bring satellites down. Satellites far higher face different end-of-life rules.", "sources": [{"url": "https://www.satellitetoday.com/government-military/2022/09/30/fcc-adopts-5-year-rule-for-deorbiting-satellites/", "label": "Via Satellite, FCC five-year deorbit rule"}, {"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does the low-orbit five-year rule describe each satellite?", "buckets": ["Low orbit", "Higher orbit"], "items": [{"text": "Iridium phone satellite at 780 km", "bucket": 0}, {"text": "Crew lab circling in 90 minutes", "bucket": 0}, {"text": "GPS satellite near 20,000 km", "bucket": 1}, {"text": "TV satellite at 35,786 km", "bucket": 1}, {"text": "Imaging satellite at 500 km", "bucket": 0}], "explanation": "Anything below about 2,000 km is low orbit, where the five-year rule applies."}, "numbers": {"kind": "numberSense", "prompt": "Low orbit ends near 2,000 km; geostationary orbit is at 35,786 km. About how many times higher is it?", "min": 0, "max": 30, "value": 18, "unit": "x", "explanation": "35,786 divided by 2,000 is about 18."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked which satellites must deorbit within five years.", "prompt": "What's your answer?", "options": ["Those in low Earth orbit, under the FCC rule", "Every single satellite at any height at all", "Only the satellites that carry people aboard"], "correctIndex": 0, "consequences": ["The rule is written for low orbit.", "Higher orbits have other rules.", "People are not the test."], "explanation": "The five-year rule covers low orbit; knowing the orbit tells you which rules apply."}, "proReasoning": "Knowing which rule fits which orbit sounds like real operations experience.", "commonMistake": "Applying one rule to every orbit.", "mentalModel": "Orbit first, then rule."}, "invest": {"call": {"kind": "theCall", "situation": "A company plans 1,000 satellites at 550 km.", "prompt": "Which cost do you add to its plan?", "options": ["Moving them all to 35,786 km", "Bringing each one down within five years", "No cost, since space is unregulated"], "correctIndex": 1, "consequences": ["That is a different business.", "At 550 km, the rule applies.", "The FCC enforces debris rules."], "explanation": "At that height, every satellite needs a plan to come down in five years."}, "proReasoning": "Investors add disposal to the cost of low-orbit fleets.", "commonMistake": "Leaving end-of-life costs out of the model.", "mentalModel": "Low orbit carries a disposal cost."}, "build_startup": {"call": {"kind": "theCall", "situation": "You're picking an altitude for your imaging satellites.", "prompt": "How does the rule affect it?", "options": ["Altitude has no link to the rule at all", "Flying higher is always the simpler path", "Lower orbits make the five-year rule easier"], "correctIndex": 2, "consequences": ["The rule depends on orbit.", "Higher satellites stay up longer.", "Thin air helps pull low satellites down."], "explanation": "The lower you fly, the more drag helps you meet the deadline."}, "proReasoning": "Founders pick orbits with the rules in mind.", "commonMistake": "Choosing an altitude without checking disposal.", "mentalModel": "Choose height with the rule in mind."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why rules differ by orbit.", "prompt": "What's the reason?", "options": ["Traffic and physics differ at each height", "Each orbit belongs to a single country", "Higher orbits have no satellites in them"], "correctIndex": 0, "consequences": ["Low orbit is crowded and has thin air.", "No country owns an orbit.", "Geostationary orbit is busy too."], "explanation": "Low orbit is crowded and air slowly drags satellites down. Higher orbits work differently."}, "proReasoning": "Rules follow the physics of each orbit.", "commonMistake": "Thinking space is one place with one rule.", "mentalModel": "Different heights, different rules."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7fa07bd2ea92$ml$]::text[]),
($ml$31758238-0e1e-5929-8343-1ce153603899$ml$::uuid, $ml$spacetech$ml$, 7, 3, $ml${"id": "spacetech-d7-c3", "title": "Pick the orbit for your service", "lessonTitle": "Three orbits, three businesses", "slot": 3, "type": "decide", "brief": {"headline": "You run a startup with two product ideas: TV broadcasting to one continent, or a global phone network. A geostationary satellite sees a third of Earth; Iridium covers the globe with 66 low satellites.", "kicker": "Decide: which orbit fits which product?", "fullText": "At 35,786 km, a satellite circles once a day and hangs over one spot, so a home dish can stay pointed at it. Low satellites, below 2,000 km, lap Earth in 90 minutes to 2 hours.\n\nIridium's phone network uses 66 satellites at about 780 km. GPS sits in medium orbit near 20,000 km. The orbit you pick decides what you can sell.", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which orbit fits TV broadcasting to fixed home dishes?", "options": ["Low orbit at about 780 km", "Medium orbit near 20,000 km", "Geostationary orbit at 35,786 km"], "correctIndex": 2, "explanation": "A geostationary satellite stays over one spot, so a fixed dish never has to move."}, "numbers": {"kind": "numberSense", "prompt": "A low satellite laps Earth in about 90 minutes. About how many laps does it make in a day?", "min": 0, "max": 30, "value": 16, "unit": "laps", "explanation": "24 hours is 1,440 minutes; 1,440 divided by 90 is 16."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks which orbit suits a global phone service.", "prompt": "What do you recommend?", "options": ["A single medium-orbit satellite", "Low orbit, with many satellites", "One geostationary satellite"], "correctIndex": 1, "consequences": ["One satellite cannot cover the globe.", "Iridium uses 66 low satellites.", "One satellite sees only a third of Earth."], "explanation": "Phones need close satellites everywhere, which means many low ones."}, "proReasoning": "Matching the job to the orbit is a core space skill.", "commonMistake": "Picking an orbit before defining the product.", "mentalModel": "Product first, then orbit."}, "invest": {"call": {"kind": "theCall", "situation": "One startup plans a few geostationary satellites; another, hundreds of low ones.", "prompt": "How do their capital needs differ?", "options": ["They need exactly the same capital", "Geostationary needs thousands", "Low orbit needs many more satellites"], "correctIndex": 2, "consequences": ["The models differ sharply.", "A few can cover continents.", "Coverage from low orbit takes numbers."], "explanation": "Geostationary covers continents with a few satellites; low orbit needs a fleet."}, "proReasoning": "Investors map the orbit to the size of the bill.", "commonMistake": "Comparing satellite plans without the orbit.", "mentalModel": "Orbit sets the capital."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your first product is TV for one continent.", "prompt": "Which orbit do you choose?", "options": ["Geostationary, over one spot", "Low orbit, close and fast", "Medium orbit, like GPS"], "correctIndex": 0, "consequences": ["Fixed dishes need a satellite that stays put.", "Low satellites race across the sky.", "Medium orbit suits navigation."], "explanation": "Broadcast to fixed dishes is what geostationary orbit was made for."}, "proReasoning": "Founders let the product pick the orbit.", "commonMistake": "Copying the trendy orbit for the wrong product.", "mentalModel": "Let the product choose."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a TV dish never needs to turn.", "prompt": "What's the reason?", "options": ["The dish has a hidden motor", "Its satellite circles once a day", "The satellite is very low"], "correctIndex": 1, "consequences": ["Most home dishes have no motor.", "It matches Earth's spin over one spot.", "Low satellites move across the sky."], "explanation": "At 35,786 km, the satellite keeps pace with Earth and seems to hang still."}, "proReasoning": "Height sets the orbit's timing.", "commonMistake": "Thinking satellites always move across the sky.", "mentalModel": "Once a day keeps it still."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0ce6a6fc2da0$ml$]::text[]),
($ml$21bfc0d1-64f6-54a4-9964-b2009c703581$ml$::uuid, $ml$spacetech$ml$, 8, 1, $ml${"id": "spacetech-d8-c1", "title": "Out of money at 74 satellites", "lessonTitle": "Why low orbit needs thousands of satellites", "slot": 1, "type": "apply", "brief": {"headline": "In March 2020, OneWeb filed for bankruptcy with 74 satellites in orbit. It planned a low-orbit network of 648 and had raised $3.4 billion.", "kicker": "Apply the lesson: a low-orbit network must reach scale first.", "fullText": "OneWeb launched its satellites in batches of more than 30 on Soyuz rockets. SoftBank, its largest backer, had invested $2 billion since 2016, and OneWeb was seeking up to $2 billion more.\n\nThose talks stalled. OneWeb said the financing did not progress because of market turbulence from COVID-19. With about 574 satellites still to go, a network that could not yet serve everyone could not raise the money to finish.", "sources": [{"url": "https://spaceflightnow.com/2020/03/30/oneweb-files-for-bankruptcy/", "label": "Spaceflight Now, OneWeb files for bankruptcy, Mar 2020"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the chain in order.", "steps": ["OneWeb plans 648 low-orbit satellites", "It launches 74 on three rockets", "It seeks about $2 billion more", "Funding talks stall in early 2020", "It files for bankruptcy"], "explanation": "A low-orbit network needs most of its satellites before it can sell full coverage, so the money must come first."}, "numbers": {"kind": "numberSense", "prompt": "OneWeb had 74 of 648 planned satellites in orbit. About what percent is that?", "min": 0, "max": 50, "value": 11, "unit": "%", "explanation": "74 of 648 is about 11%, far from full coverage."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked why OneWeb ran out of money.", "prompt": "What's the core reason?", "options": ["It needed most satellites up before selling", "Its satellites flew far too high to work", "It sold too much service far too early"], "correctIndex": 0, "consequences": ["Low orbit needs scale before revenue.", "They flew in low orbit.", "It had little service to sell yet."], "explanation": "A low-orbit network cannot serve everyone until most satellites are up, so cash runs out first."}, "proReasoning": "Strong answers link the failure to the orbit's economics.", "commonMistake": "Blaming only bad luck.", "mentalModel": "Scale before revenue."}, "invest": {"call": {"kind": "theCall", "situation": "A low-orbit network has 11% of its satellites up and needs more money.", "prompt": "What is the main risk?", "options": ["Its satellites will last too long", "Funding dries up before full coverage", "It will have too many customers"], "correctIndex": 1, "consequences": ["Lifetime is not the issue.", "OneWeb stalled at 74 satellites.", "Coverage comes first."], "explanation": "Until coverage is complete, revenue is thin, so every funding round is a risk."}, "proReasoning": "Investors ask how much money is needed to reach full coverage.", "commonMistake": "Valuing a network on its final size, not its funding path.", "mentalModel": "Fund the whole path."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your low-orbit network needs 600 satellites to serve everyone.", "prompt": "How do you plan funding?", "options": ["Raise a little at a time as you go", "Launch first, find money later", "Secure money for most of the fleet early"], "correctIndex": 2, "consequences": ["A stall mid-build can sink you.", "That is how OneWeb got stuck.", "OneWeb shows the risk of a gap."], "explanation": "With low orbit, you need the fleet before the revenue. Line up the money first."}, "proReasoning": "Founders fund the whole deployment, not just the first launch.", "commonMistake": "Starting a fleet you cannot finish.", "mentalModel": "Money for the fleet first."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why low-orbit internet needs so many satellites.", "prompt": "What's the reason?", "options": ["Each one sees a small area, briefly", "Satellites break down every week", "Laws require huge fleets"], "correctIndex": 0, "consequences": ["They pass over in minutes.", "They last for years.", "No law sets the size."], "explanation": "A low satellite passes over in minutes, so many are needed to keep a link up."}, "proReasoning": "Close and fast means you need a crowd.", "commonMistake": "Thinking one satellite can serve a country.", "mentalModel": "Small view, many satellites."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:56066301f7fa$ml$]::text[]),
($ml$98bfecd9-3a9e-5941-801c-7b1a961df035$ml$::uuid, $ml$spacetech$ml$, 8, 2, $ml${"id": "spacetech-d8-c2", "title": "Why SpaceX launches for itself", "lessonTitle": "Why low orbit needs thousands of satellites", "slot": 2, "type": "connect", "brief": {"headline": "Starlink had about 9,400 active satellites in early 2026, and 123 of SpaceX's 2025 launches carried them. Day 3 showed SpaceX filling its own rockets; day 8 showed why low orbit needs that many.", "kicker": "Connect day 3 and day 8: a huge fleet needs its own ride.", "fullText": "On day 3 you saw that three in four SpaceX launches carried Starlink. On day 8 you saw why: a low satellite sees a small patch and races past it in minutes, so a network needs thousands to keep customers connected.\n\nBuilding and replacing a fleet of about 9,400 takes a steady stream of launches. Owning the rocket lets SpaceX keep that stream going on its own schedule.", "sources": [{"url": "https://www.jalopnik.com/2067687/spacex-half-orbital-rocket-launches-2025/", "label": "Jalopnik, SpaceX over half of 2025 launches"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}, {"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why does owning the rocket matter so much for Starlink?", "options": ["Its huge fleet needs launches all year", "Starlink satellites are too heavy to share", "Other rockets refuse to fly them"], "correctIndex": 0, "explanation": "Thousands of satellites need a steady flow of launches, which SpaceX controls."}, "numbers": {"kind": "numberSense", "prompt": "SpaceX flew 123 Starlink launches in 2025. About how many is that per month?", "min": 0, "max": 30, "value": 10, "unit": "launches", "explanation": "123 divided by 12 is about 10 a month."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked why Starlink and Falcon 9 belong together.", "prompt": "What's your answer?", "options": ["Satellites cannot ride other rockets", "A big fleet needs a steady, owned ride", "Starlink makes the rocket fly faster"], "correctIndex": 1, "consequences": ["They could, but SpaceX controls its own.", "About 9,400 satellites need launches all year.", "The service does not change the rocket."], "explanation": "Low orbit needs thousands of satellites; an owned rocket keeps them coming."}, "proReasoning": "Linking a business model to its launch needs shows depth.", "commonMistake": "Seeing the rocket and network as separate businesses.", "mentalModel": "Fleet size needs launch control."}, "invest": {"call": {"kind": "theCall", "situation": "A rival plans thousands of low satellites but owns no rocket.", "prompt": "What do you probe?", "options": ["How shiny and new its satellites look", "Whether its logo is easy to remember", "How it secures enough launches each year"], "correctIndex": 2, "consequences": ["Looks do not reach orbit.", "Branding does not launch.", "Launch supply decides its pace."], "explanation": "Without its own rocket, a big fleet depends on renting enough rides."}, "proReasoning": "Investors check launch supply against fleet size.", "commonMistake": "Ignoring where a fleet's launches will come from.", "mentalModel": "Count the rides."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup plans 1,000 low satellites.", "prompt": "What must you secure early?", "options": ["Launches to build and refresh the fleet", "A famous spokesperson for the brand", "One single launch for the whole fleet"], "correctIndex": 0, "consequences": ["Fleets need launches year after year.", "Fame does not launch satellites.", "One rocket cannot carry 1,000."], "explanation": "A big low-orbit fleet needs a steady supply of launches. Plan it like a supply chain."}, "proReasoning": "Founders treat launch capacity as a supply chain.", "commonMistake": "Planning the satellites but not the rides.", "mentalModel": "Plan rides like supply."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why SpaceX launches about 10 Starlink rockets a month.", "prompt": "Why so many?", "options": ["Satellites only last a few weeks", "Low orbit needs thousands of satellites", "Each rocket carries one satellite"], "correctIndex": 1, "consequences": ["They last years.", "About 9,400 were active in early 2026.", "Each launch carries many."], "explanation": "Thousands of low satellites are needed for constant coverage, so launches never stop."}, "proReasoning": "Big constellations need a steady conveyor belt to orbit.", "commonMistake": "Thinking a network is built in one launch.", "mentalModel": "Thousands need a stream."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:13eb0feca3f5$ml$]::text[]),
($ml$7f954c74-0eaf-57af-91cd-4dd351fe1ac1$ml$::uuid, $ml$spacetech$ml$, 8, 3, $ml${"id": "spacetech-d8-c3", "title": "Defend a geostationary business", "lessonTitle": "Why low orbit needs thousands of satellites", "slot": 3, "type": "decide", "brief": {"headline": "You run a geostationary internet company. A signal to your satellites and back travels about 71,600 km, about a quarter of a second. Low-orbit rivals are dozens of times closer.", "kicker": "Decide: where does your far-away satellite still win?", "fullText": "A geostationary satellite sees about a third of the planet, so a handful can serve whole continents. But even at light speed, the round trip takes about 240 milliseconds before any processing.\n\nLow-orbit networks cut that delay but need thousands of satellites, like Starlink's roughly 9,400. Calls and gaming suffer from delay; TV broadcasting does not.", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["A round trip to geostationary orbit takes about 240 ms.", "One geostationary satellite sees about a third of Earth.", "Low orbit needs fewer satellites than geostationary."], "fakeIndex": 2, "explanation": "Low orbit needs far more satellites, because each sees a small patch."}, "numbers": {"kind": "numberSense", "prompt": "A signal goes 71,600 km up and down at 300,000 km per second. How many milliseconds is that?", "min": 0, "max": 1000, "value": 240, "unit": "ms", "explanation": "About 240 ms, before any processing."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a product manager at the geostationary company.", "prompt": "Which customers do you focus on?", "options": ["Online gamers who need fast replies", "Everyone, ignoring the delay", "Uses where delay matters less, like TV"], "correctIndex": 2, "consequences": ["Gamers feel every millisecond.", "Ignoring delay loses those users.", "Broadcast handles a quarter second fine."], "explanation": "Far satellites cover huge areas cheaply but add delay. Sell where delay does not hurt."}, "proReasoning": "Product managers match the product's limits to the right customers.", "commonMistake": "Selling a slow link to people who need speed.", "mentalModel": "Sell where delay is fine."}, "invest": {"call": {"kind": "theCall", "situation": "Low-orbit rivals grow fast against a geostationary operator.", "prompt": "Where can the operator hold value?", "options": ["Wide coverage for delay-tolerant uses", "Fast gaming connections", "Building thousands of satellites"], "correctIndex": 0, "consequences": ["A few satellites cover continents.", "Low orbit wins on speed.", "That is the rivals' model."], "explanation": "Geostationary keeps its edge in wide coverage where speed is not the main need."}, "proReasoning": "Investors look for the niche an older model still wins.", "commonMistake": "Assuming the older model has no place left.", "mentalModel": "Find the niche it still wins."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells to the geostationary company.", "prompt": "What could you offer it?", "options": ["A way to beat the speed of light", "Services that make its delay matter less", "Thousands of its own low satellites"], "correctIndex": 1, "consequences": ["Physics sets the delay.", "That helps it compete where it can.", "That is a rival model."], "explanation": "You cannot change the distance, but you can soften its effect for customers."}, "proReasoning": "Founders help incumbents defend the ground they still hold.", "commonMistake": "Promising to beat physics.", "mentalModel": "Soften the delay."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why calls through some satellites feel laggy.", "prompt": "What's the reason?", "options": ["The satellite is out of fuel", "Radio waves slow down in space", "The satellite is very far away"], "correctIndex": 2, "consequences": ["Fuel does not affect delay.", "They travel at light speed.", "A round trip takes about a quarter second."], "explanation": "Even at light speed, 71,600 km takes about a quarter of a second."}, "proReasoning": "Distance costs time, even for light.", "commonMistake": "Thinking the lag is a fault, not physics.", "mentalModel": "Far away means a pause."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c9eee3efd8fa$ml$]::text[]),
($ml$6bc9f858-f215-568b-b7f2-52e43c77ae34$ml$::uuid, $ml$spacetech$ml$, 9, 1, $ml${"id": "spacetech-d9-c1", "title": "A rideshare to a different orbit", "lessonTitle": "On a rideshare, the rocket picks your orbit", "slot": 1, "type": "apply", "brief": {"headline": "On April 7, 2024, SpaceX flew Bandwagon-1, its first rideshare to a mid-inclination orbit near 45 degrees. It carried 11 spacecraft for six customers.", "kicker": "Apply the lesson: a new route gives riders a new orbit.", "fullText": "SpaceX's Transporter rideshares go to sun-synchronous orbit, which passes over the poles. Satellites that want to spend their time over populated middle latitudes had few cheap options.\n\nBandwagon-1 went to about 45.4 degrees. Its main payload was South Korea's first radar satellite for its 425 Project, alongside satellites from Capella Space, iQPS, HawkEye 360 and others. The rocket still picked the orbit and the date; it just offered a second route.", "sources": [{"url": "https://www.nasaspaceflight.com/2024/04/bandwagon-1/", "label": "NASASpaceflight, Bandwagon-1, Apr 2024"}]}, "evidence": {"kind": "faceOff", "prompt": "A radar satellite wants to watch the middle latitudes. Which ride fits?", "left": {"name": "Transporter", "note": "Sun-synchronous orbit over the poles"}, "right": {"name": "Bandwagon", "note": "Mid-inclination orbit near 45 degrees"}, "correctIndex": 1, "explanation": "Bandwagon goes to a mid-inclination orbit, which keeps satellites over populated areas."}, "numbers": {"kind": "numberSense", "prompt": "Bandwagon-1 carried 11 spacecraft for six customers. About how many per customer, on average?", "min": 0, "max": 6, "value": 1.8, "unit": "spacecraft", "explanation": "11 divided by 6 is about 1.8."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a mission planner choosing a rideshare for a radar satellite.", "prompt": "What do you check first?", "options": ["Only the price per kilogram, nothing else", "Whether the ride's orbit fits the mission", "Which ride has the coolest mission name"], "correctIndex": 1, "consequences": ["A cheap wrong orbit costs more later.", "Orbit decides what the satellite can see.", "Names do not matter."], "explanation": "Rideshares go where the rocket goes. Check the orbit before the price."}, "proReasoning": "Planners match the ride's orbit to the mission first.", "commonMistake": "Booking the cheapest ride to the wrong orbit.", "mentalModel": "Orbit before price."}, "invest": {"call": {"kind": "theCall", "situation": "SpaceX adds a rideshare to a new orbit.", "prompt": "What does that do for SpaceX?", "options": ["It loses money on every single flight", "It shuts down its Transporter flights", "It wins riders who skipped polar flights"], "correctIndex": 2, "consequences": ["Nothing suggests losses.", "Transporter continues.", "A new route brings new customers."], "explanation": "A second route serves customers the first one could not, and keeps them on SpaceX rockets."}, "proReasoning": "Investors see new routes as new demand.", "commonMistake": "Missing how new routes add customers.", "mentalModel": "New route, new riders."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your satellite needs a 45-degree orbit, and polar rideshares do not go there.", "prompt": "What do you do?", "options": ["Book a mid-inclination rideshare", "Accept a polar orbit anyway", "Buy a whole rocket"], "correctIndex": 0, "consequences": ["Bandwagon goes near 45 degrees.", "You would watch the wrong places.", "Far more costly than a seat."], "explanation": "A rideshare to your orbit avoids both the wrong orbit and the cost of a full rocket."}, "proReasoning": "Founders look for the ride that already goes their way.", "commonMistake": "Settling for an orbit that hurts the product.", "mentalModel": "Find the ride that goes your way."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why satellites care about inclination.", "prompt": "What's the reason?", "options": ["It changes how bright the satellite looks", "It decides which parts of Earth they pass over", "It sets how fast the rocket has to climb"], "correctIndex": 1, "consequences": ["Color is unrelated.", "45 degrees keeps them over busy latitudes.", "Inclination is about the orbit's tilt."], "explanation": "The tilt of an orbit decides which latitudes a satellite flies over."}, "proReasoning": "An orbit's tilt is a choice about where to look.", "commonMistake": "Thinking every orbit sees the same places.", "mentalModel": "Tilt decides the view."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4b260226bda0$ml$]::text[]),
($ml$741bc3db-7bf3-504c-aa38-4bb768d8668c$ml$::uuid, $ml$spacetech$ml$, 9, 2, $ml${"id": "spacetech-d9-c2", "title": "Cheaper seat, higher price per kilogram", "lessonTitle": "On a rideshare, the rocket picks your orbit", "slot": 2, "type": "connect", "brief": {"headline": "A Transporter rideshare costs about $7,000 per kg; a whole Falcon 9 works out to about $3,400. Day 4 taught cost per kilogram; day 9 showed what a rideshare seat really buys.", "kicker": "Connect day 4 and day 9: per kg is not the whole story.", "fullText": "On day 4 you divided Falcon 9's $74 million by about 22 tons and got roughly $3,400 per kilogram. On day 9 you saw SpaceX's rideshare at $350,000 for 50 kg, about $7,000 per kilogram.\n\nPer kilogram, the seat costs about twice as much as filling a whole rocket. But a small satellite cannot fill 22 tons, so the seat is far cheaper in total. The trade: the rocket picks the orbit and the date.", "sources": [{"url": "https://www.fool.com/investing/2026/04/12/spacex-launches-more-rockets-than-anyone-else/", "label": "Motley Fool, SpaceX launches more than anyone"}, {"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Rideshare costs more per kg than a full Falcon 9.", "A 50 kg rideshare seat costs about $350,000.", "Rideshare riders choose their own orbit and date."], "fakeIndex": 2, "explanation": "The rocket sets the orbit and date; riders go along."}, "numbers": {"kind": "numberSense", "prompt": "Rideshare is about $7,000 per kg; a full Falcon 9 about $3,400. About how many times more per kg is rideshare?", "min": 0, "max": 5, "value": 2.1, "unit": "x", "explanation": "About 2.1 times more per kg, but far less in total for a small satellite."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer says rideshare is the cheapest way to orbit.", "prompt": "How do you refine that?", "options": ["Agree, it is cheapest in every way", "Say rideshare is the most expensive", "Cheapest in total, not per kilogram"], "correctIndex": 2, "consequences": ["Not per kg.", "Not in total for small satellites.", "Per kg it costs about twice a full rocket."], "explanation": "Rideshare wins on total cost for small satellites, not on cost per kilogram."}, "proReasoning": "Precise answers separate total cost from unit cost.", "commonMistake": "Repeating that rideshare is cheapest without saying how.", "mentalModel": "Total versus per kg."}, "invest": {"call": {"kind": "theCall", "situation": "Rideshare prices rose from $5,500 to about $7,000 per kg.", "prompt": "What does that suggest?", "options": ["Demand for seats stays strong", "Small satellites are out of fashion", "SpaceX is leaving rideshare"], "correctIndex": 0, "consequences": ["Prices rose and seats still fill.", "The market kept growing.", "It still sells seats."], "explanation": "Rising prices with steady demand point to pricing power in the rideshare market."}, "proReasoning": "Investors read price rises against demand.", "commonMistake": "Treating a price rise as a weakness.", "mentalModel": "Rising price, steady seats."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your 40 kg satellite could take a rideshare seat or a dedicated small rocket.", "prompt": "What decides it?", "options": ["Which of the rockets is more famous", "Whether the shared orbit and date work", "Only the price per kilogram you pay"], "correctIndex": 1, "consequences": ["Fame does not reach your orbit.", "If they work, the seat is far cheaper.", "Per kg ignores what you need."], "explanation": "If the rideshare goes where and when you need, take the seat. If not, pay for control."}, "proReasoning": "Founders choose rides by orbit and date first.", "commonMistake": "Choosing a ride on price per kg alone.", "mentalModel": "Orbit and date first."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why sharing a rocket costs more per kilogram.", "prompt": "Why would it?", "options": ["Shared rockets fly farther", "Rideshare uses more fuel per satellite", "You pay for convenience and a small slot"], "correctIndex": 2, "consequences": ["They fly to normal orbits.", "Fuel is shared.", "Small buyers pay a premium per kg."], "explanation": "Selling small slots costs more to arrange, but buyers save by not paying for a whole rocket."}, "proReasoning": "Small portions cost more per unit, like buying a single slice.", "commonMistake": "Assuming shared always means cheaper per unit.", "mentalModel": "Small slots, higher unit price."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:14efd4fe5a6a$ml$]::text[]),
($ml$f5831055-f681-5eb3-979b-d958099b550a$ml$::uuid, $ml$spacetech$ml$, 9, 3, $ml${"id": "spacetech-d9-c3", "title": "Close the gap to your orbit", "lessonTitle": "On a rideshare, the rocket picks your orbit", "slot": 3, "type": "decide", "brief": {"headline": "You run an imaging startup. A Transporter seat drops your 100 kg satellite in a sun-synchronous orbit higher than you want. A seat costs $350,000 for 50 kg plus $7,000 per extra kg.", "kicker": "Decide: how do you get from the drop-off to your working orbit?", "fullText": "The lesson showed that on a rideshare, the rocket picks the orbit and the date. Space tugs, like D-Orbit's ION carriers, ride up as one payload and then move satellites where they need to go. D-Orbit has flown 21 of them.\n\nYour options: accept the drop-off and lose image quality, buy a whole rocket, or add a tug or onboard thrust.", "sources": [{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}, {"url": "https://newspaceeconomy.ca/2026/02/27/spacex-rideshare-pricing-as-of-february-2026-what-it-costs-whats-included-and-how-buyers-budget-a-mission/", "label": "New Space Economy, SpaceX rideshare pricing, Feb 2026"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each option fix the orbit gap?", "buckets": ["Fixes the gap", "Doesn't"], "items": [{"text": "Booking a space tug", "bucket": 0}, {"text": "Adding onboard thrusters", "bucket": 0}, {"text": "Buying a dedicated rocket", "bucket": 0}, {"text": "Accepting the drop-off orbit", "bucket": 1}, {"text": "Booking a later Transporter seat", "bucket": 1}], "explanation": "Tugs, thrusters or a dedicated rocket close the gap; another seat to the same orbit does not."}, "numbers": {"kind": "numberSense", "prompt": "A seat costs $350,000 for 50 kg plus $7,000 per extra kg. What does 100 kg cost, in thousands?", "min": 0, "max": 1000, "value": 700, "unit": "K", "explanation": "$350,000 plus 50 times $7,000 is $700,000."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the mission engineer comparing the options.", "prompt": "What do you present?", "options": ["Total cost and image quality for each path", "Only the cheapest seat price available", "Only the earliest launch date on offer"], "correctIndex": 0, "consequences": ["That lets leadership weigh the trade.", "Cheap may hurt the product.", "Speed alone ignores quality."], "explanation": "Each path trades money against the orbit you get. Show both."}, "proReasoning": "Engineers frame choices as trade-offs with numbers.", "commonMistake": "Presenting one option as obvious.", "mentalModel": "Show cost and quality."}, "invest": {"call": {"kind": "theCall", "situation": "Space tugs sell the move from drop-off to final orbit.", "prompt": "Why is there demand?", "options": ["Tugs are replacing rockets for launch", "Rideshares drop everyone in the same orbit", "Satellites cannot move on their own"], "correctIndex": 1, "consequences": ["They ride on rockets.", "Riders need to spread out from there.", "Some can, but many lack thrust."], "explanation": "Rideshare is cheap but uniform. Tugs sell the last mile."}, "proReasoning": "Investors look for services that fill gaps in a cheap model.", "commonMistake": "Missing the business in the last mile.", "mentalModel": "The last mile sells."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your satellite needs a lower orbit than the rideshare drop-off.", "prompt": "How do you get there?", "options": ["Accept the drop-off and lose quality", "Buy a whole rocket for one satellite", "Add a space tug or onboard thrust"], "correctIndex": 2, "consequences": ["Your product would be worse for life.", "A dedicated launch costs many times more.", "Tugs exist to close that gap."], "explanation": "Tugs and thrusters close the gap between where the ride goes and where you need to be."}, "proReasoning": "Founders combine a cheap ride with a short last leg.", "commonMistake": "Accepting a worse product to save a little.", "mentalModel": "Cheap ride, short last leg."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what a space tug does.", "prompt": "What's the answer?", "options": ["Moves satellites from drop-off to their orbit", "Pulls broken satellites back down to Earth", "Tows rockets out to the launch pad"], "correctIndex": 0, "consequences": ["It carries riders the last stretch.", "That is a different job.", "That happens on the ground."], "explanation": "A tug rides up with others, then delivers each satellite to its own orbit."}, "proReasoning": "Tugs are the delivery van after the shared ride.", "commonMistake": "Thinking every satellite gets its own rocket.", "mentalModel": "The last stretch to orbit."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:899c6d4461d9$ml$]::text[]),
($ml$24b3436c-fae6-5dde-99e5-64a354b25362$ml$::uuid, $ml$spacetech$ml$, 10, 1, $ml${"id": "spacetech-d10-c1", "title": "Sharper pictures, every day", "lessonTitle": "How often you can see the same spot", "slot": 1, "type": "apply", "brief": {"headline": "BlackSky's Gen-3 satellites take 35 cm images, and the company commissioned its fourth one in less than a week after launch. Its Gen-3 fleet offers daily collections; its older Gen-2 fleet, hourly monitoring.", "kicker": "Apply the lesson: imaging firms sell detail and frequency together.", "fullText": "BlackSky calls 35 cm best in class. Its newer Gen-3 satellites add sharper detail, while its Gen-2 fleet watches sites as often as hourly.\n\nThat is the trade from the lesson. Planet images all land daily at about 3.7 m; Maxar's six Legion satellites see 30 cm detail up to 15 times a day at some places. Each company sells a different mix of how sharp and how often.", "sources": [{"url": "https://www.satnow.com/news/details/4846-blacksky-activates-gen-3-satellite-in-under-a-week-expanding-global-35-cm-imagery-access", "label": "SatNow, BlackSky activates Gen-3 satellite in under a week"}, {"url": "https://learn.planet.com/rs/997-CHH-265/images/Planet Overview Datasheet.pdf", "label": "Planet overview datasheet"}, {"url": "https://www.businesswire.com/news/home/20250204832232/en", "label": "Maxar, fifth and sixth WorldView Legion satellites"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each fact about detail or about frequency?", "buckets": ["Detail", "Frequency"], "items": [{"text": "35 cm images from Gen-3", "bucket": 0}, {"text": "Hourly monitoring from Gen-2", "bucket": 1}, {"text": "Daily Gen-3 collections", "bucket": 1}, {"text": "3.7 m pixels from Planet", "bucket": 0}, {"text": "Up to 15 visits a day from Maxar", "bucket": 1}], "explanation": "Resolution is detail; revisit is frequency. Imaging firms sell both."}, "numbers": {"kind": "numberSense", "prompt": "How many centimeters per pixel do BlackSky's Gen-3 images show?", "min": 0, "max": 100, "value": 35, "unit": "cm", "explanation": "35 cm, close to Maxar's 30 cm."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at an imaging company.", "prompt": "How do you describe its product?", "options": ["Only how sharp its images are", "Only how many satellites it has", "Both how sharp and how often it sees"], "correctIndex": 2, "consequences": ["Detail alone misses timing.", "Counts do not say what it sells.", "Customers buy both."], "explanation": "In imaging, resolution and revisit together define the product."}, "proReasoning": "People who quote both numbers sound like insiders.", "commonMistake": "Quoting resolution without revisit.", "mentalModel": "Sharp and often."}, "invest": {"call": {"kind": "theCall", "situation": "BlackSky adds sharper satellites to a fleet that already revisits hourly.", "prompt": "Why might it matter?", "options": ["Customers pay for fresh, detailed views", "Sharper images always cost less to make", "Revisit no longer matters to buyers"], "correctIndex": 0, "consequences": ["Freshness plus detail is what sells.", "Sharper often costs more.", "Revisit still drives value."], "explanation": "Adding detail to frequent visits gives customers more to buy from the same sites."}, "proReasoning": "Investors look at how a fleet improves its mix of detail and freshness.", "commonMistake": "Judging a fleet on one number.", "mentalModel": "Freshness plus detail."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup analyzes satellite images for ports.", "prompt": "Which data do you buy?", "options": ["Only the cheapest images on sale", "Frequent, sharp views of the ports", "One global image a year, at most"], "correctIndex": 1, "consequences": ["Cheap and stale is useless here.", "Ports change by the hour.", "A yearly image misses everything."], "explanation": "Ports change often and in detail. Buy data that matches how fast they change."}, "proReasoning": "Founders match the data to how fast their subject changes.", "commonMistake": "Buying data that is too old or too blurry.", "mentalModel": "Match data to change."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what 35 cm resolution means.", "prompt": "What's the answer?", "options": ["The satellite is 35 cm wide", "The photo is 35 cm across", "Each pixel covers 35 cm of ground"], "correctIndex": 2, "consequences": ["Size is not resolution.", "Resolution is per pixel.", "That is enough to see cars."], "explanation": "Each pixel shows a square of ground 35 cm across."}, "proReasoning": "Smaller pixels mean more detail.", "commonMistake": "Mixing up satellite size with image detail.", "mentalModel": "Pixel size is detail."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3e88a8283039$ml$]::text[]),
($ml$7265e28b-ff7a-5a8f-86c5-4b9a503f0c10$ml$::uuid, $ml$spacetech$ml$, 10, 2, $ml${"id": "spacetech-d10-c2", "title": "Low orbit makes revisit possible", "lessonTitle": "How often you can see the same spot", "slot": 2, "type": "connect", "brief": {"headline": "Planet's 200-plus satellites image all of Earth's land every day. Day 7 showed low satellites lapping Earth every 90 minutes to 2 hours; day 10 showed what that speed buys.", "kicker": "Connect day 7 and day 10: fast laps plus many satellites mean daily views.", "fullText": "On day 7 you saw that a low satellite circles Earth in 90 minutes to 2 hours. On day 10 you saw revisit: how often a fleet sees the same place.\n\nOne low satellite passes a spot only now and then. Add many, and passes add up. Planet's 200-plus satellites cover all land daily at about 3.7 m, and Maxar's six Legion satellites can return to some places up to 15 times a day.", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}, {"url": "https://learn.planet.com/rs/997-CHH-265/images/Planet Overview Datasheet.pdf", "label": "Planet overview datasheet"}, {"url": "https://www.businesswire.com/news/home/20250204832232/en", "label": "Maxar, fifth and sixth WorldView Legion satellites"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the logic in order.", "steps": ["Low satellites lap Earth in about 90 minutes", "Each lap passes over a different strip", "More satellites cover more strips", "The same spot gets passed more often", "Customers can watch places change daily"], "explanation": "Speed and numbers together turn single passes into daily coverage."}, "numbers": {"kind": "numberSense", "prompt": "Maxar's six Legion satellites revisit some places up to 15 times a day. About how many visits per satellite is that?", "min": 0, "max": 6, "value": 2.5, "unit": "visits", "explanation": "15 divided by 6 is 2.5 visits per satellite."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked why imaging fleets fly low.", "prompt": "What's your answer?", "options": ["Close and fast means more passes and detail", "Low orbit is the only orbit that is legal", "High orbits are much too cold for cameras"], "correctIndex": 0, "consequences": ["Speed and distance both help.", "Many orbits are legal.", "Cold is not the reason."], "explanation": "Low orbit gives detail from closeness and frequent passes from speed."}, "proReasoning": "Linking orbit physics to the product is a strong signal.", "commonMistake": "Explaining imaging without the orbit.", "mentalModel": "Low means close and frequent."}, "invest": {"call": {"kind": "theCall", "situation": "An imaging startup plans 10 satellites; a rival has 200.", "prompt": "Where does the small fleet struggle?", "options": ["Getting into orbit", "Seeing the same place often", "Taking any images at all"], "correctIndex": 1, "consequences": ["Rideshares are available.", "Fewer satellites, fewer passes.", "It can still image."], "explanation": "Revisit grows with fleet size. A small fleet must win on something else, like detail."}, "proReasoning": "Investors check whether a fleet is big enough for its promise.", "commonMistake": "Expecting a small fleet to match daily coverage.", "mentalModel": "Fleet size sets revisit."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your customers want daily views of farms worldwide.", "prompt": "What fleet does that need?", "options": ["One sharp geostationary satellite", "A few satellites aimed at chosen farms", "Many low satellites covering all land"], "correctIndex": 2, "consequences": ["Too far for detail.", "Misses most farms.", "Planet does this with 200-plus."], "explanation": "Daily global coverage takes a large low fleet, not a few sharp satellites."}, "proReasoning": "Founders size the fleet to the promise.", "commonMistake": "Promising daily coverage with too few satellites.", "mentalModel": "Size the fleet to the promise."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how every piece of land gets photographed daily.", "prompt": "What's the trick?", "options": ["Hundreds of fast, low satellites", "One giant satellite far away", "Planes flying all day"], "correctIndex": 0, "consequences": ["Planet flies more than 200.", "One satellite cannot see it all daily.", "This is done from space."], "explanation": "Many low satellites, each lapping Earth quickly, together pass over all land each day."}, "proReasoning": "Many small eyes beat one big one for coverage.", "commonMistake": "Picturing one camera doing it all.", "mentalModel": "Many low satellites."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:87202d75349e$ml$]::text[]),
($ml$4847893a-494b-5484-9ee4-fa27bb5ac12f$ml$::uuid, $ml$spacetech$ml$, 10, 3, $ml${"id": "spacetech-d10-c3", "title": "Daily coverage or sharp detail", "lessonTitle": "How often you can see the same spot", "slot": 3, "type": "decide", "brief": {"headline": "You run an analytics startup for crop insurers. Planet images all land daily at 3.7 m; Maxar's fleet sees 30 cm detail, up to 15 times a day at some places.", "kicker": "Decide: which data fits a customer covering farms everywhere?", "fullText": "Crop insurers need to see many farms, often, to spot damage after storms or droughts. They do not usually need to count individual plants.\n\nThe lesson's rule: how often you see a place matters as much as how sharply. Planet trades detail for daily global coverage; Maxar trades coverage for detail and frequent visits to chosen sites.", "sources": [{"url": "https://learn.planet.com/rs/997-CHH-265/images/Planet Overview Datasheet.pdf", "label": "Planet overview datasheet"}, {"url": "https://www.businesswire.com/news/home/20250204832232/en", "label": "Maxar, fifth and sixth WorldView Legion satellites"}]}, "evidence": {"kind": "faceOff", "prompt": "A crop insurer wants every farm, every day. Which data fits better?", "left": {"name": "Planet", "note": "All land daily, 3.7 m pixels"}, "right": {"name": "Maxar Legion", "note": "30 cm detail on chosen sites"}, "correctIndex": 0, "explanation": "Daily coverage of all farms matters more here than 30 cm detail on a few."}, "numbers": {"kind": "numberSense", "prompt": "Planet pixels are about 3.7 m; Maxar's are 30 cm. About how many times sharper is Maxar?", "min": 0, "max": 20, "value": 12, "unit": "x", "explanation": "3.7 m divided by 0.3 m is about 12 times sharper."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the data lead choosing imagery for the insurer.", "prompt": "What do you pick?", "options": ["The sharpest images, whatever the cost", "Daily global coverage at 3.7 m", "30 cm images of a few farms"], "correctIndex": 1, "consequences": ["Detail is not their main need.", "Insurers need breadth and freshness.", "Most farms would be missed."], "explanation": "Match the data to the job: many farms, seen often."}, "proReasoning": "Data leads start from the customer's question.", "commonMistake": "Buying the sharpest data by default.", "mentalModel": "Start from the question."}, "invest": {"call": {"kind": "theCall", "situation": "Two imaging firms: one sells breadth, one sells detail.", "prompt": "Which wins crop insurers?", "options": ["The one with the sharpest pixels", "Neither, insurers skip imagery", "The one with daily global coverage"], "correctIndex": 2, "consequences": ["Detail matters less for them.", "Imagery fits their need.", "Insurers watch many farms."], "explanation": "Different customers value different trade-offs. Insurers value breadth."}, "proReasoning": "Investors map each product to the customers it fits.", "commonMistake": "Assuming one imaging firm wins every customer.", "mentalModel": "Map product to customer."}, "build_startup": {"call": {"kind": "theCall", "situation": "A new customer wants to count cars in parking lots.", "prompt": "Does your data choice change?", "options": ["Yes, cars need sharp detail", "No, 3.7 m is always enough", "No, coverage is all that matters"], "correctIndex": 0, "consequences": ["30 cm can show cars.", "3.7 m cannot show single cars.", "This job needs detail."], "explanation": "Counting cars needs detail. The job, not habit, picks the data."}, "proReasoning": "Founders switch data sources when the question changes.", "commonMistake": "Using one dataset for every job.", "mentalModel": "Each job picks its data."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why insurers don't buy the sharpest images.", "prompt": "What's the reason?", "options": ["Sharp satellites are unable to see farms", "They need many farms often, not tiny detail", "Sharp images of farms are against the law"], "correctIndex": 1, "consequences": ["They can see farms.", "Breadth and freshness matter more.", "They are legal."], "explanation": "Insurers care about seeing damage across many farms quickly, not counting plants."}, "proReasoning": "The best data is the one that fits the question.", "commonMistake": "Thinking sharper is always better.", "mentalModel": "Fit beats sharpness."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:31dc5b82941d$ml$]::text[]),
($ml$55262a26-fd93-59e7-b36d-8e6c5a0f5b34$ml$::uuid, $ml$spacetech$ml$, 11, 1, $ml${"id": "spacetech-d11-c1", "title": "The storm that moved half of low orbit", "lessonTitle": "The storm that sank 38 satellites", "slot": 1, "type": "apply", "brief": {"headline": "From May 7 to 10, 2024, the strongest solar storm since 2003 hit Earth. Nearly half of all active satellites in low orbit maneuvered at once to make up for the extra drag.", "kicker": "Apply the lesson: space weather moves whole fleets.", "fullText": "The storm reached G5, the top of NOAA's five-step scale. Researchers at MIT found that most of the moves were automated station-keeping by Starlink satellites, out of about 10,000 active low-orbit payloads.\n\nDuring the storm, satellites and debris sank about 180 meters a day. Forecasts missed how long and how strong it would be, which made it very hard to predict close passes while so many objects were moving at once.", "sources": [{"url": "https://space.com/may-solar-storm-largest-mass-migration-satellites", "label": "Space.com, May 2024 storm caused largest 'mass migration' of satellites"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the storm's effects in order.", "steps": ["A G5 solar storm hits Earth", "The upper atmosphere heats and swells", "Drag on low satellites rises", "Thousands of satellites fire thrusters at once", "Predicting close passes gets much harder"], "explanation": "Heat swells the air, drag rises, satellites push back, and the traffic picture blurs."}, "numbers": {"kind": "numberSense", "prompt": "Satellites and debris sank about 180 meters a day. Over four days, about how many meters is that?", "min": 0, "max": 1000, "value": 720, "unit": "m", "explanation": "About 720 meters over the four-day storm."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're on a satellite operations shift when a G5 storm hits.", "prompt": "What do you watch most closely?", "options": ["Drag on your satellites and close passes", "Your company social media follower count", "The price of your company next launch"], "correctIndex": 0, "consequences": ["Both change fast in a storm.", "Not part of operations.", "Not the urgent question."], "explanation": "Storms raise drag and blur the traffic picture. Both need eyes on them."}, "proReasoning": "Operators treat space weather as a live operating event.", "commonMistake": "Assuming automation handles everything in a storm.", "mentalModel": "Watch drag and traffic."}, "invest": {"call": {"kind": "theCall", "situation": "A storm forces half of low orbit to maneuver at once.", "prompt": "Which hidden cost do you note?", "options": ["Fewer launches next year", "Fuel and staff time spent fighting drag", "Satellites getting cheaper to build"], "correctIndex": 1, "consequences": ["Storms do not cancel launches.", "Station-keeping uses fuel.", "Storms do not cut build costs."], "explanation": "Every maneuver burns fuel that shortens a satellite's working life."}, "proReasoning": "Investors count space weather in operating costs.", "commonMistake": "Treating storms as rare events with no cost.", "mentalModel": "Storms cost fuel."}, "build_startup": {"call": {"kind": "theCall", "situation": "Forecasts missed how long and how strong the storm would be.", "prompt": "Where is the opening?", "options": ["Satellites that ignore drag", "Insurance against sunshine", "Better drag and storm forecasts"], "correctIndex": 2, "consequences": ["Drag affects every low satellite.", "Not a real product.", "Operators need forecasts they can trust."], "explanation": "Operators made decisions on forecasts that missed. Better ones have buyers."}, "proReasoning": "Founders build where existing tools failed in a real event.", "commonMistake": "Building something no one needed during the storm.", "mentalModel": "Fix what failed in the storm."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how the Sun can move satellites.", "prompt": "What's the answer?", "options": ["It heats the air, and drag pulls them down", "It pushes them along with sunlight alone", "It melts their solar panels in minutes"], "correctIndex": 0, "consequences": ["Heated air swells into their orbit.", "Light pressure is tiny here.", "Panels survived."], "explanation": "Solar storms heat the upper atmosphere, which swells and drags on low satellites."}, "proReasoning": "Low orbit is not empty; it still has thin air.", "commonMistake": "Thinking space has no air at all.", "mentalModel": "Hot air, more drag."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:fbd637204c54$ml$]::text[]),
($ml$19b9bb9d-6950-5f31-b4c3-18a821a5d19c$ml$::uuid, $ml$spacetech$ml$, 11, 2, $ml${"id": "spacetech-d11-c2", "title": "A fleet big enough to absorb a loss", "lessonTitle": "The storm that sank 38 satellites", "slot": 2, "type": "connect", "brief": {"headline": "A minor storm in February 2022 brought down 38 of 49 new Starlink satellites. Day 8 showed why low-orbit networks need thousands; day 11 showed one reason they need spares.", "kicker": "Connect day 8 and day 11: big fleets can absorb what small ones cannot.", "fullText": "On day 8 you saw that a low-orbit network needs thousands of satellites, like Starlink's roughly 9,400 in early 2026. On day 11 you saw a storm swell the upper atmosphere and drag 38 freshly launched satellites back to Earth within days.\n\nFor a fleet of thousands with frequent launches, losing 38 is painful but survivable. For a company with a few dozen satellites, the same storm could wipe out its whole service.", "sources": [{"url": "https://svs.gsfc.nasa.gov/hyperwall/index/data/a000000/a005100/a005193/cap5193.txt.html", "label": "NASA, geomagnetic storm causes Starlink loss"}, {"url": "https://cires.colorado.edu/news/minor-geomagnetic-storm-big-impact-february-2022-starlink-satellite-loss", "label": "CIRES, minor storm, big impact"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]}, "evidence": {"kind": "faceOff", "prompt": "Which company is hurt more by losing 38 satellites?", "left": {"name": "A fleet of about 9,400", "note": "Launches about 10 times a month"}, "right": {"name": "A fleet of 50", "note": "Launches a few times a year"}, "correctIndex": 1, "explanation": "For the small fleet, 38 satellites is most of its network."}, "numbers": {"kind": "numberSense", "prompt": "The storm brought down 38 of 49 new satellites. What percent was lost?", "min": 0, "max": 100, "value": 78, "unit": "%", "explanation": "38 of 49 is about 78% of that launch."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked how Starlink survived losing 38 satellites at once.", "prompt": "What's your answer?", "options": ["The loss was hidden from customers", "Its fleet and launch rate are huge", "The satellites were insured twice"], "correctIndex": 1, "consequences": ["Nothing suggests that.", "Thousands of satellites cushion a loss.", "Insurance is not the main cushion."], "explanation": "Scale and frequent launches let a big fleet replace losses quickly."}, "proReasoning": "Strong answers link resilience to fleet size.", "commonMistake": "Thinking every operator could shrug off that loss.", "mentalModel": "Scale absorbs losses."}, "invest": {"call": {"kind": "theCall", "situation": "A 50-satellite startup faces the same storm risk as Starlink.", "prompt": "How do you rate its exposure?", "options": ["About the same as Starlink's", "Lower, since small fleets are safer", "Much higher, one bad day could end it"], "correctIndex": 2, "consequences": ["Scale changes the impact.", "Smaller means less cushion.", "A few dozen losses could be fatal."], "explanation": "The same event hits a small fleet far harder."}, "proReasoning": "Investors ask how many losses a fleet can take.", "commonMistake": "Ignoring fleet size when judging risk.", "mentalModel": "Small fleets, big exposure."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your first launch will carry 20 satellites into low orbit.", "prompt": "How do you reduce storm risk?", "options": ["Check space weather before deploying", "Launch anyway, whatever the forecast", "Fly higher than your mission needs"], "correctIndex": 0, "consequences": ["A quiet window protects the batch.", "A storm could take most of them.", "Your product needs its orbit."], "explanation": "New satellites are most exposed right after release. Timing the deploy matters."}, "proReasoning": "Founders treat the first days after launch as the riskiest.", "commonMistake": "Ignoring forecasts on the most fragile day.", "mentalModel": "Time the deploy."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why losing 38 satellites didn't break Starlink.", "prompt": "What's the reason?", "options": ["Storms cannot harm real satellites", "It has thousands and launches often", "Those satellites were just test models"], "correctIndex": 1, "consequences": ["This storm did.", "About 9,400 active in early 2026.", "They were working satellites."], "explanation": "A huge fleet with frequent launches can replace losses quickly."}, "proReasoning": "Size is a kind of safety net.", "commonMistake": "Thinking one bad day ruins any network.", "mentalModel": "Size is a safety net."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c39b3ee503d7$ml$]::text[]),
($ml$4e35e092-7595-555b-8238-a2d478572a8d$ml$::uuid, $ml$spacetech$ml$, 11, 3, $ml${"id": "spacetech-d11-c3", "title": "Launch into a minor storm", "lessonTitle": "The storm that sank 38 satellites", "slot": 3, "type": "decide", "brief": {"headline": "You run launch operations for a low-orbit network. The forecast calls for minor storming on release day. In 2022, a minor storm cost Starlink 38 of 49 new satellites.", "kicker": "Decide: deploy as planned, or change the plan?", "fullText": "Freshly released satellites sit low and cannot always push back against extra drag. In February 2022, forecasters expected only minor storming; denser air rose into the satellites' orbit and most of the batch reentered within days.\n\nDrag cuts both ways: it cleans up dead satellites, and it pulls down working ones that cannot fight it.", "sources": [{"url": "https://svs.gsfc.nasa.gov/hyperwall/index/data/a000000/a005100/a005193/cap5193.txt.html", "label": "NASA, geomagnetic storm causes Starlink loss"}, {"url": "https://cires.colorado.edu/news/minor-geomagnetic-storm-big-impact-february-2022-starlink-satellite-loss", "label": "CIRES, minor storm, big impact"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["New satellites are most exposed right after release.", "Forecasters expected only minor storming in 2022.", "A minor forecast means drag cannot rise."], "fakeIndex": 2, "explanation": "A minor forecast still brought down 38 satellites in 2022."}, "numbers": {"kind": "numberSense", "prompt": "If 38 of 49 satellites were lost, how many survived?", "min": 0, "max": 49, "value": 11, "unit": "satellites", "explanation": "49 minus 38 leaves 11 survivors."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the launch director; the forecast says minor storming.", "prompt": "What do you recommend?", "options": ["Deploy at the planned low altitude anyway", "Ignore the forecast completely this time", "Release higher, or wait for calmer weather"], "correctIndex": 2, "consequences": ["2022 shows what can happen.", "Forecasts are part of the decision.", "Either reduces drag risk."], "explanation": "Minor storms have sunk batches before. Release higher or wait."}, "proReasoning": "Launch directors weigh space weather like airline crews weigh storms.", "commonMistake": "Trusting the word minor too much.", "mentalModel": "Respect the minor storm."}, "invest": {"call": {"kind": "theCall", "situation": "A company you own launches its batches at very low release altitudes.", "prompt": "What do you ask?", "options": ["How it handles storm risk on release", "How many logos are on the rocket", "Whether it can launch at night"], "correctIndex": 0, "consequences": ["Low release raises drag exposure.", "Logos are not risk.", "Night launches are not the issue."], "explanation": "Low release saves fuel but exposes a batch to storms."}, "proReasoning": "Investors ask about the riskiest moment of a mission.", "commonMistake": "Skipping the deployment risk.", "mentalModel": "Ask about release day."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup's whole first batch launches next week; a minor storm is forecast.", "prompt": "What do you do?", "options": ["Cancel all of the launch plans", "Ask for a later or higher release", "Proceed and hope it stays minor"], "correctIndex": 1, "consequences": ["Overreaction.", "Protecting the batch protects the company.", "Hope is not a plan."], "explanation": "One storm can take a whole small batch. Ask for a safer release."}, "proReasoning": "Founders protect their first batch above all.", "commonMistake": "Risking the whole company on one release window.", "mentalModel": "Protect the first batch."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a minor storm could be dangerous.", "prompt": "What's the answer?", "options": ["Minor storms make loud noises in space", "Storms throw rocks at satellites", "Even small heating can swell the air"], "correctIndex": 2, "consequences": ["Space carries no sound.", "Storms are about heat and particles.", "Swollen air raises drag."], "explanation": "A little heating can push denser air up into a low satellite's path."}, "proReasoning": "Small causes can have big effects in low orbit.", "commonMistake": "Judging risk by the forecast's label alone.", "mentalModel": "Small storm, big drag."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:bf54fbb0e6df$ml$]::text[]),
($ml$a3642f0f-c48a-5a4f-96f4-847b80be1052$ml$::uuid, $ml$spacetech$ml$, 12, 1, $ml${"id": "spacetech-d12-c1", "title": "A space station dodges a constellation", "lessonTitle": "300,000 swerves in a year", "slot": 1, "type": "apply", "brief": {"headline": "China's Tiangong space station made two evasive maneuvers to avoid Starlink satellites, on July 1 and October 21, 2021. China complained to a UN space committee on December 6.", "kicker": "Apply the lesson: crowded orbits turn into disputes.", "fullText": "The station had a three-member crew. China's foreign ministry said the United States had failed its obligations under the 1967 space treaty to protect astronauts' safety, and urged it to prevent such incidents.\n\nThe complaint went to the UN Committee on the Peaceful Uses of Outer Space. As low orbit fills with large fleets, close passes stop being rare events and start becoming diplomatic ones.", "sources": [{"url": "https://www.pbs.org/newshour/world/china-says-spacex-satellites-nearly-collided-with-its-three-member-crew-space-station", "label": "PBS NewsHour, China says SpaceX satellites nearly collided with its station, Dec 2021"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why did China take the complaint to the UN?", "options": ["The UN tracks every satellite for operators", "Countries answer for their satellites in space", "The UN operates Starlink satellites"], "correctIndex": 1, "explanation": "Under the 1967 treaty, countries are responsible for activities in space, including their companies'."}, "numbers": {"kind": "numberSense", "prompt": "The two maneuvers came on July 1 and October 21, 2021. About how many days apart?", "min": 0, "max": 200, "value": 112, "unit": "days", "explanation": "About 112 days, less than four months."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked what the Tiangong incidents show.", "prompt": "What's your answer?", "options": ["Satellites cannot be tracked", "Crowding now reaches crewed stations", "Space stations should be retired"], "correctIndex": 1, "consequences": ["These passes were tracked.", "Fleets share space with crews.", "Stations remain in use."], "explanation": "As fleets grow, close passes affect everyone, crews included."}, "proReasoning": "Strong answers connect traffic to safety and policy.", "commonMistake": "Treating close passes as purely technical.", "mentalModel": "Traffic touches everyone."}, "invest": {"call": {"kind": "theCall", "situation": "A crewed station dodges a commercial constellation twice in a year.", "prompt": "Which risk grows for operators?", "options": ["Lower demand for satellite internet", "Launch prices falling sharply", "Political and regulatory pressure"], "correctIndex": 2, "consequences": ["Demand is not the issue.", "Prices are unrelated.", "Complaints can lead to rules."], "explanation": "Incidents with crews can bring new rules and scrutiny for big fleets."}, "proReasoning": "Investors watch how traffic incidents shape regulation.", "commonMistake": "Ignoring policy risk from crowding.", "mentalModel": "Incidents invite rules."}, "build_startup": {"call": {"kind": "theCall", "situation": "Close passes now cause UN complaints.", "prompt": "What service has a market?", "options": ["Shared tracking and coordination", "Satellites designed so no one can see them", "Faster rockets for supplying space stations"], "correctIndex": 0, "consequences": ["Coordination prevents both moves and disputes.", "Hiding makes risk worse.", "Speed is not the issue."], "explanation": "When operators do not coordinate, everyone takes the risk. Coordination tools fill that gap."}, "proReasoning": "Founders build the shared tools crowded systems lack.", "commonMistake": "Building tools that make tracking harder.", "mentalModel": "Help operators coordinate."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a space station had to move for satellites.", "prompt": "What's the answer?", "options": ["Satellites pushed it with magnets", "Satellites passed too close for safety", "The station wanted a new view"], "correctIndex": 1, "consequences": ["No such force.", "Moving avoided a possible collision.", "It was for safety."], "explanation": "When a close pass looks risky, the station moves out of the way."}, "proReasoning": "Even crewed stations now share crowded lanes.", "commonMistake": "Thinking stations have orbits to themselves.", "mentalModel": "Move when it is too close."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f4e9c01d9d83$ml$]::text[]),
($ml$82b4fe6c-4cc4-5174-b940-e21c3764c84d$ml$::uuid, $ml$spacetech$ml$, 12, 2, $ml${"id": "spacetech-d12-c2", "title": "More debris, more swerves", "lessonTitle": "300,000 swerves in a year", "slot": 2, "type": "connect", "brief": {"headline": "Starlink satellites made about 300,000 collision-avoidance maneuvers in 2025. Day 5 showed debris growing faster than it falls; day 12 showed what that costs in daily work.", "kicker": "Connect day 5 and day 12: growing debris means growing swerves.", "fullText": "On day 5 you saw ESA count more than 1.2 million debris pieces larger than 1 cm, with collisions making new debris faster than old debris falls back. On day 12 you saw Starlink dodge about 300,000 possible collisions in 2025, nearly 40 per satellite.\n\nIn the six months to May 2023 the count was about 25,000. Each swerve uses fuel and needs a decision, so crowding becomes a daily operating cost.", "sources": [{"url": "https://www.esa.int/Space_Safety/Space_Debris/ESA_Space_Environment_Report_2025", "label": "ESA Space Environment Report 2025"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}, {"url": "https://space.com/spacex-starlink-50000-collision-avoidance-maneuvers-space-safety", "label": "Space.com, 50,000 maneuvers in six months"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each fact add to the swerve count?", "buckets": ["Adds swerves", "Doesn't"], "items": [{"text": "Debris growing faster than it falls", "bucket": 0}, {"text": "More satellites in the same orbits", "bucket": 0}, {"text": "A very cautious risk threshold", "bucket": 0}, {"text": "Satellites retired at the end of life", "bucket": 1}, {"text": "A five-year deorbit rule", "bucket": 1}], "explanation": "Debris, crowding and caution add swerves. Cleanup rules work the other way."}, "numbers": {"kind": "numberSense", "prompt": "300,000 maneuvers in a year is about how many per day?", "min": 0, "max": 2000, "value": 822, "unit": "moves", "explanation": "300,000 divided by 365 is about 822 a day."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked why satellite operators hire more traffic staff.", "prompt": "What's your answer?", "options": ["Satellites have become harder to build", "Launch prices doubled", "Swerves rose from 25,000 to 300,000 a year"], "correctIndex": 2, "consequences": ["Building is not the driver.", "Prices are unrelated.", "Every swerve needs screening and a decision."], "explanation": "More debris and more satellites mean more close passes to handle."}, "proReasoning": "Quoting the trend shows you track the real workload.", "commonMistake": "Treating traffic as an occasional problem.", "mentalModel": "Swerves are the job now."}, "invest": {"call": {"kind": "theCall", "situation": "A constellation's swerves double in half a year.", "prompt": "What do you expect to rise?", "options": ["Fuel use and operating costs", "Revenue earned per customer", "How long satellites last"], "correctIndex": 0, "consequences": ["Each swerve burns fuel.", "Customers pay the same.", "Fuel spent shortens life."], "explanation": "Crowding shows up as fuel burned and shorter satellite lives."}, "proReasoning": "Investors model crowding as a rising cost.", "commonMistake": "Leaving traffic out of operating costs.", "mentalModel": "Crowding raises costs."}, "build_startup": {"call": {"kind": "theCall", "situation": "Swerves could near one million a year by 2027.", "prompt": "What would operators buy?", "options": ["Paint that makes satellites harder to see", "Automation that screens and plans moves", "More staff to count every pass by hand"], "correctIndex": 1, "consequences": ["Hiding raises risk.", "Scale needs software.", "Hand counting cannot keep up."], "explanation": "A workload heading toward a million moves a year needs automation."}, "proReasoning": "Founders sell software where workloads explode.", "commonMistake": "Offering manual help for an exploding workload.", "mentalModel": "Automate the swerves."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend hears satellites swerve about 800 times a day.", "prompt": "Why so many?", "options": ["Satellites are built to change lanes often", "Each swerve earns the operator money", "Orbits are crowded and debris keeps growing"], "correctIndex": 2, "consequences": ["They move only for safety.", "Swerves cost money.", "Close passes keep rising."], "explanation": "Growing debris and growing fleets mean constant close passes."}, "proReasoning": "Space traffic now looks like a busy highway.", "commonMistake": "Picturing orbit as wide open.", "mentalModel": "Crowded lanes, constant swerves."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:faff7498f19d$ml$]::text[]),
($ml$8e67c487-7ecf-56e5-bfa6-c69028523cac$ml$::uuid, $ml$spacetech$ml$, 12, 3, $ml${"id": "spacetech-d12-c3", "title": "Set your own risk threshold", "lessonTitle": "300,000 swerves in a year", "slot": 3, "type": "decide", "brief": {"headline": "You run a 300-satellite network. SpaceX moves when collision risk reaches about three in ten million; the common threshold is one in 10,000.", "kicker": "Decide: how cautious should your network be?", "fullText": "Each operator sets its own threshold for when a close pass is worth a move. A lower threshold means more moves: more fuel, more staff time, but less risk.\n\nStarlink's cautious setting helped push its maneuvers to about 300,000 in 2025. The common one-in-10,000 standard moves far less often.", "sources": [{"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]}, "evidence": {"kind": "faceOff", "prompt": "Which threshold leads to more maneuvers?", "left": {"name": "Three in ten million", "note": "SpaceX's setting"}, "right": {"name": "One in 10,000", "note": "The common standard"}, "correctIndex": 0, "explanation": "Moving at a much smaller risk means moving far more often."}, "numbers": {"kind": "numberSense", "prompt": "One in 10,000 against three in ten million: about how many times more cautious is SpaceX?", "min": 0, "max": 1000, "value": 333, "unit": "x", "explanation": "0.0001 divided by 0.0000003 is about 333."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the flight dynamics lead setting the threshold.", "prompt": "What do you weigh?", "options": ["Collision risk against fuel and workload", "Only what rival operators have chosen", "Only the option that costs the least"], "correctIndex": 0, "consequences": ["That is the real trade.", "Rivals have different fleets.", "Cheapest may be unsafe."], "explanation": "A threshold balances safety against the cost of moving."}, "proReasoning": "Leads explain their threshold as a trade-off, not a number.", "commonMistake": "Copying a threshold without the reasoning.", "mentalModel": "Balance risk and cost."}, "invest": {"call": {"kind": "theCall", "situation": "Two operators pick very different thresholds.", "prompt": "What does a cautious one cost?", "options": ["Fewer customers signing up for service", "More fuel spent and shorter satellite lives", "Nothing at all, since caution is free"], "correctIndex": 1, "consequences": ["Customers do not see it.", "Every move uses fuel.", "Moves cost fuel and time."], "explanation": "Caution buys safety with fuel, which shortens satellite life."}, "proReasoning": "Investors see thresholds as a cost choice.", "commonMistake": "Assuming safety has no price.", "mentalModel": "Caution costs fuel."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your 300 satellites will meet Starlink's often.", "prompt": "What do you do besides set a threshold?", "options": ["Assume their satellite will always move", "Never move your own satellites at all", "Coordinate with SpaceX on who moves"], "correctIndex": 2, "consequences": ["Then nobody may move.", "Unsafe.", "Agreeing avoids double moves or none."], "explanation": "Close passes are routine now. Talking to the other operator avoids both of you moving, or neither."}, "proReasoning": "Founders set up coordination before the first close pass.", "commonMistake": "Relying on the other operator to act.", "mentalModel": "Agree who moves."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why operators choose different thresholds.", "prompt": "What's the reason?", "options": ["Each weighs safety against cost differently", "The law sets one fixed number for everyone", "Bigger satellites are never asked to move"], "correctIndex": 0, "consequences": ["There is no single rule.", "No single legal number.", "Size does not exempt them."], "explanation": "Each operator decides how much risk is worth a move."}, "proReasoning": "Even safety in space involves trade-offs.", "commonMistake": "Thinking there is one official threshold.", "mentalModel": "Everyone draws their own line."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7257b7fd75b8$ml$]::text[]),
($ml$a91fda1e-e117-5e59-bcf9-907bc716135c$ml$::uuid, $ml$spacetech$ml$, 13, 1, $ml${"id": "spacetech-d13-c1", "title": "A second booster comes home", "lessonTitle": "What reuse really reuses", "slot": 1, "type": "apply", "brief": {"headline": "On November 13, 2025, Blue Origin's New Glenn launched NASA's twin ESCAPADE spacecraft and landed its first stage on the ship Jacklyn, on the rocket's second mission.", "kicker": "Apply the lesson: reuse starts with bringing the booster back.", "fullText": "Blue Origin describes New Glenn's first stage as fully reusable. Its chief executive said no booster that large had ever landed on its second try. ESCAPADE will head to Mars when the planets line up again in fall 2026.\n\nAs with Falcon 9, the reuse story is about the first stage. Blue Origin made no claim that New Glenn's second stage comes back.", "sources": [{"url": "https://www.blueorigin.com/news/new-glenn-launches-nasa-escapade-lands-fully-reusable-booster", "label": "Blue Origin, New Glenn launches ESCAPADE and lands booster, Nov 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "On New Glenn's second flight, reused or not?", "buckets": ["Lands for reuse", "Not claimed"], "items": [{"text": "The first-stage booster", "bucket": 0}, {"text": "The stage that landed on Jacklyn", "bucket": 0}, {"text": "The second stage", "bucket": 1}, {"text": "The stage that reached orbit", "bucket": 1}], "explanation": "Only the booster landed. The second stage reached orbit and was not described as reusable."}, "numbers": {"kind": "numberSense", "prompt": "Falcon 9 flew reused boosters on 157 of 165 flights in 2025. What percent is that?", "min": 0, "max": 100, "value": 95, "unit": "%", "explanation": "157 of 165 is about 95%. New Glenn is at the very start of that path."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you are asked what New Glenn's landing means.", "prompt": "What's your answer?", "options": ["New Glenn is now fully reusable, top to bottom", "Booster landings no longer matter to cost", "A second big rocket can now reuse its booster"], "correctIndex": 2, "consequences": ["Only the first stage landed.", "They lower costs.", "That is the real milestone."], "explanation": "The landing proves booster reuse on a second heavy rocket, not full reuse."}, "proReasoning": "Precise answers say which part of the rocket is reused.", "commonMistake": "Calling a booster landing full reuse.", "mentalModel": "Say which stage."}, "invest": {"call": {"kind": "theCall", "situation": "Blue Origin lands a New Glenn booster for the first time.", "prompt": "What does it mean for launch competition?", "options": ["SpaceX may face a reusable heavy rival", "Launch prices will triple within a year", "Regulators will soon ban booster reuse"], "correctIndex": 0, "consequences": ["Reuse is what keeps Falcon 9 cheap.", "Reuse pushes prices the other way.", "No sign of that."], "explanation": "Booster reuse is a key cost advantage. A second heavy rocket with it raises competition."}, "proReasoning": "Investors track when rivals match a leader's cost advantage.", "commonMistake": "Assuming one landing changes prices overnight.", "mentalModel": "Watch the cost advantage."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells to launch companies.", "prompt": "What could New Glenn's landing create demand for?", "options": ["Special paint for satellites in orbit", "Fast booster inspection and refurbishment", "Parts made only for one-use boosters"], "correctIndex": 1, "consequences": ["Unrelated.", "Reused boosters need checks between flights.", "Demand shifts toward reuse."], "explanation": "More reusable boosters mean more work turning them around between flights."}, "proReasoning": "Founders follow the work that reuse creates.", "commonMistake": "Selling to a model the industry is leaving.", "mentalModel": "Serve the reuse cycle."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend saw a rocket land on a ship.", "prompt": "What part was it?", "options": ["The whole rocket at once", "The satellite it carried", "The first stage, or booster"], "correctIndex": 2, "consequences": ["The second stage stays up.", "The satellite went on to space.", "That is the part that returns."], "explanation": "The booster lands; the upper stage and the payload go on to space."}, "proReasoning": "Only part of a rocket comes home.", "commonMistake": "Thinking the whole rocket lands.", "mentalModel": "The booster comes back."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1397d986c159$ml$]::text[]),
($ml$1ac5c570-729e-565c-8182-3d3e78fd3844$ml$::uuid, $ml$spacetech$ml$, 13, 2, $ml${"id": "spacetech-d13-c2", "title": "Reuse behind the price per kilogram", "lessonTitle": "What reuse really reuses", "slot": 2, "type": "connect", "brief": {"headline": "In 2025, 157 of 165 Falcon 9 launches flew on boosters that had flown before. Day 4 showed Falcon 9 at about $3,400 per kilogram; day 13 showed part of why it is so low.", "kicker": "Connect day 4 and day 13: reuse helps set the price per kilogram.", "fullText": "On day 4 you saw Falcon 9 carry about 22 tons for $74 million. On day 13 you saw what reuse covers: the booster lands and flies again, the fairing halves are often recovered, and the second stage is thrown away every time.\n\nThe lesson's rule: whatever you throw away sets your cost floor. Reusing the biggest part of the rocket keeps the price low; the second stage is the part that still has to be paid for on every flight.", "sources": [{"url": "https://www.fool.com/investing/2026/04/12/spacex-launches-more-rockets-than-anyone-else/", "label": "Motley Fool, SpaceX launches more than anyone"}, {"url": "https://spacedaily.com/t-we-tend-to-think-reusable-rockets-are-still-experimental-but-in-2025-spacex-s-partly-reusable-falcon-9-flew-165-missions-one-every-2-2-days-and-successfully-delivered-its-payload-on-every-flight/", "label": "Space Daily, Falcon 9 in 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the logic in order.", "steps": ["The booster lands after launch", "It flies again on a later mission", "Each flight needs a new second stage", "The second stage sets the cost floor", "Falcon 9 sells near $3,400 per kg"], "explanation": "Reusing the booster lowers costs; the thrown-away second stage sets the floor."}, "numbers": {"kind": "numberSense", "prompt": "Falcon 9 had flown about 620 times by March 2026 with over 99% success. About how many failures at most is that?", "min": 0, "max": 20, "value": 6, "unit": "failures", "explanation": "1% of 620 is about 6, so fewer than that."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked why Falcon 9 is so cheap per kilogram.", "prompt": "What do you mention?", "options": ["Booster reuse, with the second stage as the floor", "It burns much less fuel than any rival rocket", "It flies only short trips to very low orbits"], "correctIndex": 0, "consequences": ["That is the core cost story.", "Fuel is a small share of cost.", "It flies to many orbits."], "explanation": "Reuse removes most hardware cost; the expendable second stage remains."}, "proReasoning": "Explaining the cost floor shows you understand launch economics.", "commonMistake": "Crediting fuel savings for the price.", "mentalModel": "Reuse, then the floor."}, "invest": {"call": {"kind": "theCall", "situation": "A rival plans a rocket that throws away both stages.", "prompt": "How does it compare on cost?", "options": ["Launch cost has nothing to do with reuse", "It must pay for a whole rocket each flight", "It will end up cheaper than Falcon 9 per kg"], "correctIndex": 1, "consequences": ["Reuse is central to cost.", "Throwing both stages away raises the floor.", "Unlikely without reuse."], "explanation": "Whatever is thrown away must be rebuilt for every flight."}, "proReasoning": "Investors ask what each launch throws away.", "commonMistake": "Ignoring reuse when comparing costs.", "mentalModel": "What is thrown away, is paid for."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup could make second stages cheaper to build.", "prompt": "Why might launchers care?", "options": ["Second stages land and fly again", "Launchers never buy parts", "The second stage is the cost floor"], "correctIndex": 2, "consequences": ["On Falcon 9 they do not.", "They buy many parts.", "It is the part paid for every flight."], "explanation": "With the booster reused, the second stage is where savings matter most."}, "proReasoning": "Founders attack the cost that remains after reuse.", "commonMistake": "Working on parts that are already reused.", "mentalModel": "Cut the floor."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if reused rockets are fully reused.", "prompt": "What's the answer?", "options": ["No, the second stage is thrown away", "Yes, every single part flies again", "No, only the leftover fuel is reused"], "correctIndex": 0, "consequences": ["It is lost on every flight.", "Not on Falcon 9.", "Fuel is burned, not reused."], "explanation": "Falcon 9 reuses its booster and often its fairings; the second stage is lost."}, "proReasoning": "\"Reusable\" usually means partly reusable.", "commonMistake": "Assuming reusable means every part.", "mentalModel": "Partly reusable."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d6b22d9df34d$ml$]::text[]),
($ml$3a37b43e-a0b9-5660-a9ff-7e9daa568133$ml$::uuid, $ml$spacetech$ml$, 13, 3, $ml${"id": "spacetech-d13-c3", "title": "Design the next rocket", "lessonTitle": "What reuse really reuses", "slot": 3, "type": "decide", "brief": {"headline": "You lead a team designing a new rocket. Falcon 9 reuses its booster and fairings but throws away its second stage, and in 2025 all 165 of its launches delivered their payloads.", "kicker": "Decide: what do you make reusable first?", "fullText": "The booster is the biggest part of the rocket, and it turns back before reaching orbit. The second stage ends up in orbit, far from the pad and moving fast, so it has no easy way home.\n\nFalcon 9 had flown about 620 times by March 2026 with a success rate above 99%. Reuse is now routine for the first stage.", "sources": [{"url": "https://spacedaily.com/t-we-tend-to-think-reusable-rockets-are-still-experimental-but-in-2025-spacex-s-partly-reusable-falcon-9-flew-165-missions-one-every-2-2-days-and-successfully-delivered-its-payload-on-every-flight/", "label": "Space Daily, Falcon 9 in 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which part gives the biggest saving to reuse first?", "options": ["The second stage, the part in orbit", "The paint and decals", "The booster, the largest part"], "correctIndex": 2, "explanation": "The booster is the biggest piece and the easiest to bring back before orbit."}, "numbers": {"kind": "numberSense", "prompt": "In 2025, boosters came back on all but three of 165 flights. How many came back?", "min": 0, "max": 165, "value": 162, "unit": "boosters", "explanation": "165 minus 3 is 162. Two of the three were expended on purpose."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're a propulsion engineer on the new rocket.", "prompt": "Where do you push for reuse first?", "options": ["The launch tower", "The booster and its engines", "The second stage engine first"], "correctIndex": 1, "consequences": ["Towers are already reused.", "Biggest saving, easiest return.", "Hardest to bring home from orbit."], "explanation": "Start where reuse saves the most and is most proven: the booster."}, "proReasoning": "Engineers sequence reuse from easiest to hardest.", "commonMistake": "Starting with the hardest part to recover.", "mentalModel": "Booster first."}, "invest": {"call": {"kind": "theCall", "situation": "A startup promises a fully reusable rocket on day one.", "prompt": "How do you judge it?", "options": ["Assume it will work as promised on day one", "Ignore reuse entirely when judging the plan", "Ask for proof on the upper stage"], "correctIndex": 2, "consequences": ["Bold claims need proof.", "Reuse drives cost.", "Upper-stage reuse is unproven at scale."], "explanation": "Booster reuse is proven; full reuse is the harder promise."}, "proReasoning": "Investors test the boldest part of a plan first.", "commonMistake": "Taking full reuse claims at face value.", "mentalModel": "Test the hardest claim."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your rocket can launch soon with an expendable booster, or later with a reusable one.", "prompt": "What do you do?", "options": ["Fly soon, design for booster reuse next", "Wait years until full reuse is ready", "Never plan for reuse of any part"], "correctIndex": 0, "consequences": ["Flying earns money while you add reuse.", "Waiting burns cash.", "Rivals reuse boosters."], "explanation": "Getting flying matters, but booster reuse is the cost path you must follow."}, "proReasoning": "Founders ship, then iterate toward reuse.", "commonMistake": "Betting everything on full reuse at the start.", "mentalModel": "Fly, then reuse."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the second stage is not brought back.", "prompt": "What's the reason?", "options": ["Laws forbid landing it back on Earth", "It ends up in orbit, fast and far away", "It is too small and cheap to matter"], "correctIndex": 1, "consequences": ["No such law.", "Coming home from orbit is very hard.", "It is a big cost."], "explanation": "The second stage reaches orbit, so returning it is much harder than turning a booster around."}, "proReasoning": "Getting back from orbit is the hard part.", "commonMistake": "Thinking engineers just forgot about it.", "mentalModel": "Orbit is hard to come back from."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7b6d56537b07$ml$]::text[]),
($ml$ec9b5a84-9023-5cc4-a516-2a47025dc524$ml$::uuid, $ml$spacetech$ml$, 14, 1, $ml${"id": "spacetech-d14-c1", "title": "A $500 million satellite with no cover", "lessonTitle": "When satellites fail, insurers pay", "slot": 1, "type": "apply", "brief": {"headline": "On October 19, 2024, Intelsat-33e broke into at least 20 pieces in geostationary orbit. The satellite, worth about $500 million, was not insured.", "kicker": "Apply the lesson: when cover gets pricey, some operators go without.", "fullText": "Only about 300 of 12,787 active satellites carry in-orbit insurance, according to an underwriter quoted by Space.com. After large losses, insurers including Swiss Re, AIG and Allianz left the space market.\n\nA geostationary satellite typically needs $200 million to $300 million of cover. SpaceX insures almost none of its Starlink satellites, preferring to carry the risk itself across its large fleet.", "sources": [{"url": "https://www.space.com/space-exploration/satellites/satellites-keep-breaking-up-in-space-insurance-wont-cover-them", "label": "Space.com, satellites keep breaking up and insurance won't cover them, Jun 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Intelsat-33e was insured for its full value.", "About 300 of 12,787 active satellites are insured.", "SpaceX insures almost none of its Starlink fleet."], "fakeIndex": 0, "explanation": "Intelsat-33e was uninsured, so the loss fell on Intelsat."}, "numbers": {"kind": "numberSense", "prompt": "About 300 of 12,787 active satellites are insured. About what percent is that?", "min": 0, "max": 10, "value": 2.3, "unit": "%", "explanation": "About 2.3%. Most satellites fly without in-orbit cover."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're in finance at a satellite operator weighing cover for a new satellite.", "prompt": "What do you compare?", "options": ["The premium against the loss you could absorb", "Only what Intelsat chose for its own fleet", "Only how bright the satellite's paint is"], "correctIndex": 0, "consequences": ["That is the core insurance decision.", "Their situation may differ.", "Unrelated."], "explanation": "Insure when a loss would hurt more than the premium. Self-insure when you can absorb it."}, "proReasoning": "Finance teams decide cover by asking what they can survive.", "commonMistake": "Skipping cover without checking the downside.", "mentalModel": "Premium versus survival."}, "invest": {"call": {"kind": "theCall", "situation": "An operator you own flies a $500 million satellite without insurance.", "prompt": "What do you ask?", "options": ["Whether space insurance is even legal", "Could it survive losing that satellite", "Why the satellite is so big and heavy"], "correctIndex": 1, "consequences": ["It is legal.", "An uninsured loss hits earnings directly.", "Size is not the question."], "explanation": "Without cover, a loss lands on the company. The question is whether it can absorb it."}, "proReasoning": "Investors check which assets are uninsured.", "commonMistake": "Assuming every satellite is insured.", "mentalModel": "Know what is uninsured."}, "build_startup": {"call": {"kind": "theCall", "situation": "Insurers are leaving space, and most satellites fly uninsured.", "prompt": "Where is the opening?", "options": ["Satellites that never fail", "Insuring only rockets", "Better risk data to price cover"], "correctIndex": 2, "consequences": ["No one can promise that.", "In-orbit risk is the gap.", "Insurers left after mispricing losses."], "explanation": "Insurers pulled out after losses they could not price. Better data helps them return."}, "proReasoning": "Founders build where a market lacks information.", "commonMistake": "Promising zero failures.", "mentalModel": "Help price the risk."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a company would not insure a $500 million satellite.", "prompt": "What's one reason?", "options": ["Premiums are high and few insurers remain", "Satellites cannot be insured at all", "Insurance only covers cars and homes"], "correctIndex": 0, "consequences": ["Cover got expensive after big losses.", "Some are insured.", "Space insurance exists."], "explanation": "After big losses, cover became costly and scarce, so some operators carry the risk."}, "proReasoning": "When insurance gets expensive, some choose to go without.", "commonMistake": "Assuming everything valuable is insured.", "mentalModel": "Costly cover, some go without."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c80660c15a4f$ml$]::text[]),
($ml$01e48512-f2e8-5e99-864d-81f5b57cdffd$ml$::uuid, $ml$spacetech$ml$, 14, 2, $ml${"id": "spacetech-d14-c2", "title": "A reliable rocket, pricier cover", "lessonTitle": "When satellites fail, insurers pay", "slot": 2, "type": "connect", "brief": {"headline": "In 2025, all 165 Falcon 9 launches delivered their payloads. Yet after 2023, premiums for a geostationary satellite on Falcon 9 rose from under 6% to about 10% of its value.", "kicker": "Connect day 13 and day 14: a safe ride does not make the satellite safe.", "fullText": "On day 13 you saw Falcon 9's record: more than 99% mission success. On day 14 you saw insurers pay $995 million in 2023 claims against about $557 million in premiums.\n\nThe biggest 2023 claims came from satellites that failed after launch: ViaSat-3 Americas at $445 million and Inmarsat-6 F2 at $348 million. Insurers price the whole mission, so a reliable rocket did not stop rates from rising.", "sources": [{"url": "https://spacedaily.com/t-we-tend-to-think-reusable-rockets-are-still-experimental-but-in-2025-spacex-s-partly-reusable-falcon-9-flew-165-missions-one-every-2-2-days-and-successfully-delivered-its-payload-on-every-flight/", "label": "Space Daily, Falcon 9 in 2025"}, {"url": "https://www.satellitetoday.com/sustainability/2024/05/01/slingshot-aerospace-reveals-record-insurance-losses-in-2023-in-new-satellite-deployments-report", "label": "Via Satellite, record insurance losses in 2023"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why did premiums rise even on a very reliable rocket?", "options": ["Satellites failed after reaching orbit", "Falcon 9 lost many payloads", "Insurers stopped covering launches"], "correctIndex": 0, "explanation": "2023's biggest claims came from satellite failures in orbit, not rocket failures."}, "numbers": {"kind": "numberSense", "prompt": "The ViaSat-3 claim was $445 million and Inmarsat-6 F2 $348 million. Together, in millions?", "min": 0, "max": 1200, "value": 793, "unit": "M", "explanation": "$793 million, most of 2023's $995 million in claims."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked why satellite insurance rose when rockets got safer.", "prompt": "What's your answer?", "options": ["Insurers wanted more customers", "Big satellites failed after launch", "Rockets became less reliable"], "correctIndex": 1, "consequences": ["Higher prices drive customers off.", "ViaSat-3 and Inmarsat-6 F2 drove the losses.", "Falcon 9 delivered every payload."], "explanation": "Insurers price the whole mission, and 2023 losses came from satellites in orbit."}, "proReasoning": "Good answers separate launch risk from in-orbit risk.", "commonMistake": "Assuming launch risk is the only risk.", "mentalModel": "Separate launch and orbit risk."}, "invest": {"call": {"kind": "theCall", "situation": "Two big satellite failures make 2023 a record loss for insurers.", "prompt": "What happens next year?", "options": ["Premiums fall to win customers", "Insurers pay back operators", "Premiums rise for everyone"], "correctIndex": 2, "consequences": ["Losses push prices up.", "Claims already paid.", "One bad year resets prices."], "explanation": "One bad year resets the price for everyone, as the lesson's rule says."}, "proReasoning": "Investors watch loss years to predict premiums.", "commonMistake": "Expecting prices to fall after record losses.", "mentalModel": "Bad years raise prices."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your satellite will fly on Falcon 9.", "prompt": "What still drives your premium?", "options": ["Your satellite's own design and record", "Only the rocket's long flight record", "Nothing, since launch is now safe"], "correctIndex": 0, "consequences": ["In-orbit failures drove 2023 losses.", "The rocket is only part of it.", "Satellites still fail in orbit."], "explanation": "A safe ride helps, but insurers also price your satellite."}, "proReasoning": "Founders show insurers why their satellite is reliable.", "commonMistake": "Thinking the rocket alone sets the premium.", "mentalModel": "Your satellite is priced too."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why insurance costs more if rockets almost never fail.", "prompt": "What's the answer?", "options": ["Insurance only covers the launch itself", "Satellites can fail after they reach orbit", "Rockets crash nearly every single week"], "correctIndex": 1, "consequences": ["Cover includes time in orbit.", "Two satellite failures cost about $793 million.", "Falcon 9 delivered all 165."], "explanation": "Insurance covers the satellite in orbit too, and some big ones failed there."}, "proReasoning": "The ride is only part of a satellite's risk.", "commonMistake": "Thinking reaching orbit ends the risk.", "mentalModel": "Orbit has risks too."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:bb01297e7250$ml$]::text[]),
($ml$c6828dea-a1c0-5cff-9d51-cdfd86f12ba5$ml$::uuid, $ml$spacetech$ml$, 14, 3, $ml${"id": "spacetech-d14-c3", "title": "Insure a $300 million satellite", "lessonTitle": "When satellites fail, insurers pay", "slot": 3, "type": "decide", "brief": {"headline": "You run an operator launching a $300 million geostationary satellite on Falcon 9. Premiums for that ride rose to about 10% of insured value after 2023.", "kicker": "Decide: buy cover or carry the risk yourself?", "fullText": "In 2023 insurers paid $995 million in claims and collected about $557 million, a record $438 million loss. Some insurers left the market, cutting capacity and raising prices.\n\nYour company owns only a few satellites. Losing this one would wipe out a large share of your revenue.", "sources": [{"url": "https://www.satellitetoday.com/sustainability/2024/05/01/slingshot-aerospace-reveals-record-insurance-losses-in-2023-in-new-satellite-deployments-report", "label": "Via Satellite, record insurance losses in 2023"}]}, "evidence": {"kind": "faceOff", "prompt": "Who can more easily skip in-orbit insurance?", "left": {"name": "A few big satellites", "note": "Each one is a large share of revenue"}, "right": {"name": "Thousands of small ones", "note": "Losing one barely shows"}, "correctIndex": 1, "explanation": "A large fleet spreads the risk; a few big satellites concentrate it."}, "numbers": {"kind": "numberSense", "prompt": "At about 10% of value, what does cover for a $300 million satellite cost, in millions?", "min": 0, "max": 100, "value": 30, "unit": "M", "explanation": "About $30 million, up from under $18 million at 6%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're the risk manager at the operator.", "prompt": "What do you recommend?", "options": ["Skip cover to save the $30 million now", "Insure only the launch day and no more", "Buy cover; one loss could sink the company"], "correctIndex": 2, "consequences": ["The saving is small next to the risk.", "Satellites also fail in orbit.", "Few operators survive losing a $300 million satellite."], "explanation": "The premium is the price of surviving a failure."}, "proReasoning": "Risk managers insure what the company cannot afford to lose.", "commonMistake": "Saving the premium and betting the company.", "mentalModel": "Insure what you cannot lose."}, "invest": {"call": {"kind": "theCall", "situation": "An operator with three satellites skips insurance to boost profits.", "prompt": "How do you see it?", "options": ["A big hidden risk to the company", "Smart cost control by the team", "Not relevant to what it is worth"], "correctIndex": 0, "consequences": ["One failure could erase years of profit.", "Savings hide exposure.", "It matters a lot."], "explanation": "Skipping cover with few satellites trades a small saving for a large risk."}, "proReasoning": "Investors adjust for uninsured concentration.", "commonMistake": "Praising profit gains that come from dropping cover.", "mentalModel": "Small saving, big exposure."}, "build_startup": {"call": {"kind": "theCall", "situation": "Premiums rose and capacity shrank after 2023.", "prompt": "How do you get better terms?", "options": ["Wait for space insurance prices to collapse", "Share test data that shows your reliability", "Hide any past test failures from insurers"], "correctIndex": 1, "consequences": ["Prices rose for a reason.", "Insurers price what they can see.", "That can void a policy."], "explanation": "Insurers price uncertainty. Reliable data lowers it."}, "proReasoning": "Founders treat insurers as partners who need evidence.", "commonMistake": "Expecting good terms without evidence.", "mentalModel": "Evidence lowers premiums."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks $30 million for insurance is a waste.", "prompt": "What do you say?", "options": ["Space insurance is required by law", "Insurers always refund the premium", "It protects against losing $300 million"], "correctIndex": 2, "consequences": ["Not always required.", "Premiums are kept.", "That is the trade."], "explanation": "Paying 10% protects against losing the whole satellite."}, "proReasoning": "Insurance buys survival, not profit.", "commonMistake": "Judging a premium only by its size.", "mentalModel": "Pay a little to survive a lot."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:880be667150a$ml$]::text[]),
($ml$3ed630a6-0c06-5593-87ae-d389314ad88f$ml$::uuid, $ml$spacetech$ml$, 15, 1, $ml${"id": "spacetech-d15-c1", "title": "Two newcomers join the buyer's list", "lessonTitle": "The customer that decides who survives", "slot": 1, "type": "apply", "brief": {"headline": "In March 2025, the Space Force added Rocket Lab and Stoke Space to Lane 1 of its national security launch program. That made five providers, alongside Blue Origin, SpaceX and ULA.", "kicker": "Apply the lesson: the anchor customer decides who gets a shot.", "fullText": "Lane 1 covers missions that the Space Force can award to newer providers. Being on the list is not the same as flying: Rocket Lab and Stoke must complete a first successful launch before they can compete for Lane 1 task orders.\n\nFor a new rocket, a place on the list is a path to steady government work. The buyer sets the rules of entry, and the providers race to meet them.", "sources": [{"url": "https://www.ssc.spaceforce.mil/Newsroom/Article-Display/Article/4137680/", "label": "Space Systems Command, two new providers on NSSL Phase 3 Lane 1"}, {"url": "https://www.satellitetoday.com/government-military/2025/03/28/rocket-lab-stoke-space-nab-spots-on-national-security-space-launch-program", "label": "Via Satellite, Rocket Lab and Stoke Space join NSSL, Mar 2025"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the path to national security work in order.", "steps": ["A company builds a new rocket", "The Space Force adds it to Lane 1", "It completes a first successful launch", "It competes for Lane 1 task orders", "It wins missions and steady work"], "explanation": "The buyer sets each gate: the list, a first flight, then competition for orders."}, "numbers": {"kind": "numberSense", "prompt": "Lane 1 had three providers before March 2025 and added two. What share of the five are the newcomers, in percent?", "min": 0, "max": 100, "value": 40, "unit": "%", "explanation": "Two of five is 40%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at Rocket Lab after the Lane 1 news.", "prompt": "What do you show you understand?", "options": ["Lane 1 is closed to newcomers for good", "It must fly before it can compete for orders", "It has already won its first missions"], "correctIndex": 1, "consequences": ["It just joined.", "A first successful launch is the gate.", "It still needs to fly first."], "explanation": "Joining the list opens the door; flying is what lets you compete."}, "proReasoning": "Candidates who know the buyer's rules show real awareness.", "commonMistake": "Treating a list spot as a contract win.", "mentalModel": "List first, flight next."}, "invest": {"call": {"kind": "theCall", "situation": "Rocket Lab joins Lane 1 before its new rocket has flown.", "prompt": "How do you read it?", "options": ["Revenue that is guaranteed this year", "Meaningless news for the company", "An option on future work, not revenue yet"], "correctIndex": 2, "consequences": ["No orders are awarded yet.", "It opens a big customer.", "It must fly and win orders first."], "explanation": "The list spot is valuable only once the rocket flies and wins orders."}, "proReasoning": "Investors separate eligibility from revenue.", "commonMistake": "Booking a list spot as income.", "mentalModel": "Eligibility is not revenue."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your launch startup wants national security work.", "prompt": "What do you prioritize?", "options": ["A successful first flight", "A bigger marketing budget", "Lobbying to skip the rules"], "correctIndex": 0, "consequences": ["It is the gate to competing.", "Ads do not fly rockets.", "The buyer sets the rules."], "explanation": "The buyer wants proof. A successful flight comes before any orders."}, "proReasoning": "Founders meet the anchor customer's gates in order.", "commonMistake": "Trying to win work before proving the rocket.", "mentalModel": "Fly first."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the Space Force adds more launch companies.", "prompt": "What's one reason?", "options": ["Each company must fly every mission", "More options mean less dependence on one", "It wants to spend more money"], "correctIndex": 1, "consequences": ["Missions are shared out.", "A backup keeps missions flying.", "Spending is not the goal."], "explanation": "Having several providers protects the buyer if one is grounded."}, "proReasoning": "Big buyers keep more than one supplier.", "commonMistake": "Thinking the government picks one favorite.", "mentalModel": "Options protect the buyer."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a73601ccd1ae$ml$]::text[]),
($ml$4c471073-7802-54d5-939b-d9a29d6a1f0e$ml$::uuid, $ml$spacetech$ml$, 15, 2, $ml${"id": "spacetech-d15-c2", "title": "Two rockets, by law", "lessonTitle": "The customer that decides who survives", "slot": 2, "type": "connect", "brief": {"headline": "US law requires keeping at least two launch vehicles that can carry any national security payload. Day 6 showed Europe stuck without a rocket; day 15 showed how the US guards against that.", "kicker": "Connect day 6 and day 15: a buyer can design out a single point of failure.", "fullText": "On day 6 you saw Europe lose Ariane 5, Soyuz and Vega-C and launch its science on a Falcon 9. On day 15 you saw the Space Force split 54 hard missions: 28 to SpaceX, 19 to ULA and 7 to Blue Origin.\n\nThe split is not only about price. If one rocket is grounded, another can still fly. Europe learned the cost of having one option; the US wrote two into policy.", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://www.satellitetoday.com/launch/2025/04/06/spacex-ula-blue-origin-receive-nssl-contracts-worth-up-to-nearly-14b/", "label": "Via Satellite, NSSL Phase 3 Lane 2 awards"}, {"url": "https://www.everycrsreport.com/files/2026-01-14_IF12900_e1a9a9283349423491e151fac8e59426a6fa6708.html", "label": "Congressional Research Service, National Security Space Launch"}]}, "evidence": {"kind": "faceOff", "prompt": "Which setup kept flying when one rocket was unavailable?", "left": {"name": "Europe, 2023", "note": "One heavy rocket, then none"}, "right": {"name": "US national security", "note": "At least two rockets by policy"}, "correctIndex": 1, "explanation": "Policy requiring two vehicles means a grounding does not stop missions."}, "numbers": {"kind": "numberSense", "prompt": "Of 54 missions, SpaceX got 28. What percent is that?", "min": 0, "max": 80, "value": 52, "unit": "%", "explanation": "28 of 54 is about 52%, about half, with the rest split between two others."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked why the Space Force does not give all missions to the cheapest rocket.", "prompt": "What's your answer?", "options": ["The cheapest rocket company refused the work", "Missions are handed out at random each year", "Policy requires two vehicles for resilience"], "correctIndex": 2, "consequences": ["Nothing suggests that.", "They are awarded by competition.", "A backup keeps national security flying."], "explanation": "The US keeps two capable rockets so one grounding cannot stop national security launches."}, "proReasoning": "Strong answers link the split to resilience, not just price.", "commonMistake": "Assuming the buyer only cares about price.", "mentalModel": "Resilience beats price."}, "invest": {"call": {"kind": "theCall", "situation": "ULA wins 19 missions though SpaceX could likely fly them all.", "prompt": "Why is ULA's share protected?", "options": ["Policy wants a second capable rocket", "ULA is always the cheaper of the two", "SpaceX turned down those 19 missions"], "correctIndex": 0, "consequences": ["Two vehicles are required.", "Not necessarily.", "Not the reason."], "explanation": "The two-vehicle policy gives a second provider a protected share."}, "proReasoning": "Investors look for policies that protect market share.", "commonMistake": "Missing policy as a source of revenue.", "mentalModel": "Policy protects shares."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your launch startup sees Europe and the US both value a second option.", "prompt": "How do you pitch?", "options": ["As the only rocket anyone needs", "As the backup that keeps missions flying", "As cheaper than SpaceX at everything"], "correctIndex": 1, "consequences": ["Buyers want options.", "Buyers pay for resilience.", "Hard to prove."], "explanation": "Buyers who fear a single point of failure will pay for a credible backup."}, "proReasoning": "Founders sell resilience to buyers who have been burned.", "commonMistake": "Pitching to replace the leader instead of backing it up.", "mentalModel": "Sell the backup."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the US wants two kinds of rockets.", "prompt": "What's the reason?", "options": ["To make every launch twice as fast", "Because extra rockets are cheap to keep", "So a grounding cannot stop key launches"], "correctIndex": 2, "consequences": ["Speed is not the reason.", "They are not cheap.", "A backup keeps missions going."], "explanation": "If one rocket is grounded, the other can still fly important missions."}, "proReasoning": "Two options are a safety net.", "commonMistake": "Thinking one great rocket is enough.", "mentalModel": "Two is a safety net."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:909c1fafff86$ml$]::text[]),
($ml$32329814-ea41-5f52-8d85-7c77616e6316$ml$::uuid, $ml$spacetech$ml$, 15, 3, $ml${"id": "spacetech-d15-c3", "title": "Chase the anchor customer", "lessonTitle": "The customer that decides who survives", "slot": 3, "type": "decide", "brief": {"headline": "You run a launch company. The Space Force split 54 hard missions between three providers, with ceilings of more than $5.9 billion for SpaceX and nearly $2.4 billion for Blue Origin.", "kicker": "Decide: how much do you bet on winning national security work?", "fullText": "The Phase 3 plan covers 84 missions from fiscal 2025 through 2029. National security launch is a small market with a big say: winning it keeps a launcher busy for years.\n\nBut the buyer holds the power. It chooses among providers, and each provider needs the buyer more than the buyer needs any one of them.", "sources": [{"url": "https://www.satellitetoday.com/launch/2025/04/06/spacex-ula-blue-origin-receive-nssl-contracts-worth-up-to-nearly-14b/", "label": "Via Satellite, NSSL Phase 3 Lane 2 awards"}, {"url": "https://www.everycrsreport.com/files/2026-01-14_IF12900_e1a9a9283349423491e151fac8e59426a6fa6708.html", "label": "Congressional Research Service, National Security Space Launch"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each fact favor betting on national security work?", "buckets": ["Favors the bet", "Argues caution"], "items": [{"text": "Work runs for years once won", "bucket": 0}, {"text": "84 missions planned through 2029", "bucket": 0}, {"text": "The buyer chooses among providers", "bucket": 1}, {"text": "You must fly before you can compete", "bucket": 1}, {"text": "Only a few missions per provider", "bucket": 1}], "explanation": "Long, steady work is the prize; buyer power and entry gates are the caution."}, "numbers": {"kind": "numberSense", "prompt": "84 missions over fiscal 2025 to 2029 is about how many per year?", "min": 0, "max": 40, "value": 17, "unit": "missions", "explanation": "About 17 a year across all providers."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You lead business development at the launch company.", "prompt": "How do you plan the pipeline?", "options": ["National security plus commercial customers", "National security work only, nothing else", "Commercial only, and ignore the military"], "correctIndex": 0, "consequences": ["A mix spreads the risk.", "One buyer holds all the power.", "You miss years of steady work."], "explanation": "An anchor customer is valuable, but relying on it alone gives it all the bargaining power."}, "proReasoning": "BD leads balance a powerful buyer with others.", "commonMistake": "Building the whole plan around one buyer.", "mentalModel": "Anchor plus market."}, "invest": {"call": {"kind": "theCall", "situation": "A launcher gets 80% of its revenue from national security missions.", "prompt": "What do you weigh?", "options": ["Only its launch count", "Its dependence on one powerful buyer", "Nothing, the government always pays"], "correctIndex": 1, "consequences": ["Count hides concentration.", "The buyer can shift work.", "Budgets and awards change."], "explanation": "Revenue tied to one buyer that chooses among rivals is a concentration risk."}, "proReasoning": "Investors check customer concentration.", "commonMistake": "Treating government revenue as guaranteed.", "mentalModel": "Check concentration."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your new rocket has not flown yet.", "prompt": "Where do you focus first?", "options": ["A national security contract today", "A second rocket design", "A successful first flight"], "correctIndex": 2, "consequences": ["Not possible before flying.", "Too early.", "The buyer requires flight first."], "explanation": "National security work comes after proof. Flying is the first gate."}, "proReasoning": "Founders earn the anchor customer's trust in steps.", "commonMistake": "Chasing the biggest buyer before proving the rocket.", "mentalModel": "Prove, then pitch."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a few military launches matter so much to rocket firms.", "prompt": "What's the reason?", "options": ["They bring years of steady, paid work", "They are the only launches that exist", "They come with free rockets"], "correctIndex": 0, "consequences": ["84 missions over five years.", "Commercial launches exist too.", "Firms build their own."], "explanation": "A few high-value missions a year can keep a launcher busy and funded."}, "proReasoning": "A big, steady buyer can make or break a company.", "commonMistake": "Thinking only launch counts matter.", "mentalModel": "Steady work keeps rockets flying."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:feefab6bc29c$ml$]::text[]),
($ml$34fd5788-7f1e-50f5-8536-35e91215fa6d$ml$::uuid, $ml$spacetech$ml$, 16, 1, $ml${"id": "spacetech-d16-c1", "title": "Half the launches, most of the satellites", "lessonTitle": "Six of every seven kilograms", "slot": 1, "type": "apply", "brief": {"headline": "BryceTech counted 325 orbital launches in 2025. SpaceX flew 165 of them, about half, but launched 85% of all satellites.", "kicker": "Apply the lesson: launch counts undersell who carries the load.", "fullText": "BryceTech's report found 4,544 spacecraft deployed in 2025 and about 2.7 million kilograms of spacecraft mass launched worldwide. China's main launch provider, CASC, came second with 68 orbital launches.\n\nBy launch count, SpaceX looks like half the market. By satellites carried, it is closer to six in every seven. The gap is the lesson of this day: each launch counts once, but rockets carry very different loads.", "sources": [{"url": "https://satellitetoday.com/launch/2026/04/10/brycetech-report-shows-spacex-accounted-for-50-of-launches-in-2025/", "label": "Via Satellite, BryceTech: SpaceX made about half of 2025 launches"}]}, "evidence": {"kind": "multipleChoice", "prompt": "SpaceX flew about half of 2025 launches but 85% of satellites. What does the gap show?", "options": ["Its rockets carry far more per flight", "Other rockets carried no satellites", "Satellites all got heavier in 2025"], "correctIndex": 0, "explanation": "Each launch counts once, but a Falcon 9 often carries dozens of satellites."}, "numbers": {"kind": "numberSense", "prompt": "4,544 spacecraft were deployed in 2025 and SpaceX launched 85%. About how many is that, in thousands?", "min": 0, "max": 5, "value": 3.9, "unit": "K", "explanation": "85% of 4,544 is about 3,860 spacecraft."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A manager asks you to sum up the 2025 launch market in one line.", "prompt": "Which figure do you lead with?", "options": ["There were 325 launches worldwide", "CASC made 68 orbital launches", "SpaceX launched 85% of all satellites"], "correctIndex": 2, "consequences": ["True, but it hides who flew them.", "True, but it is the runner-up.", "It shows who actually carries the load."], "explanation": "A share of what was carried shows market power better than a launch count."}, "proReasoning": "Analysts pair the launch count with the share of payloads carried.", "commonMistake": "Quoting launch counts as if every launch were equal.", "mentalModel": "Lead with what was carried."}, "invest": {"call": {"kind": "theCall", "situation": "A rival launcher says it flew 10% of launches last year.", "prompt": "What do you ask next?", "options": ["What share of satellites it carried", "How many press releases it put out", "Whether its rockets look modern"], "correctIndex": 0, "consequences": ["Launch share can overstate a small rocket.", "Not a measure of business.", "Looks say nothing about load."], "explanation": "Launch share can look strong while the share of cargo stays small."}, "proReasoning": "Investors check the cargo, not just the count.", "commonMistake": "Taking launch share as market share.", "mentalModel": "Ask what it carried."}, "build_startup": {"call": {"kind": "theCall", "situation": "One company launched 85% of satellites in 2025.", "prompt": "What does that mean for your launch plan?", "options": ["Wait for a rival to catch up first", "Plan a backup ride in case it slips", "Assume rides will always be cheap"], "correctIndex": 1, "consequences": ["Waiting can cost you years.", "A backup protects your date.", "One provider sets the price."], "explanation": "When one provider carries most satellites, its schedule and prices become your risk."}, "proReasoning": "Founders plan around a dominant supplier, not just with it.", "commonMistake": "Betting the whole plan on one ride.", "mentalModel": "Keep a backup ride."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says SpaceX flew half the world launches in 2025.", "prompt": "What can you add?", "options": ["It built every satellite it flew", "The other half were all Chinese", "It carried about 85% of the satellites"], "correctIndex": 2, "consequences": ["Many belong to other companies.", "CASC flew 68, not 160.", "Its rockets carry big batches."], "explanation": "Half the launches but most of the satellites, because each flight carries so many."}, "proReasoning": "Counting cargo tells a different story than counting rockets.", "commonMistake": "Thinking every launch carries the same amount.", "mentalModel": "Half the flights, most of the cargo."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d3698e680e76$ml$]::text[]),
($ml$cd8d5f64-debd-5a51-8a7d-514d742078b7$ml$::uuid, $ml$spacetech$ml$, 16, 2, $ml${"id": "spacetech-d16-c2", "title": "Reuse turns into cadence", "lessonTitle": "Six of every seven kilograms", "slot": 2, "type": "connect", "brief": {"headline": "Day 13 showed Falcon 9 boosters flying again and again. Day 16 showed what that buys: 165 flights in 2025, one about every 2.2 days.", "kicker": "Connect day 13 and day 16: reuse is what makes the cadence.", "fullText": "On day 13 you saw that reuse made Falcon 9 routine: about 620 flights by March 2026, and every one of its 165 launches in 2025 delivered its payload.\n\nOn day 16 you saw the result in mass. In the third quarter of 2024 SpaceX carried 85.7% of all mass launched, 362 metric tons. A rocket that can fly again in days can fly often, and a rocket that flies often carries most of the cargo.", "sources": [{"url": "https://spacedaily.com/t-we-tend-to-think-reusable-rockets-are-still-experimental-but-in-2025-spacex-s-partly-reusable-falcon-9-flew-165-missions-one-every-2-2-days-and-successfully-delivered-its-payload-on-every-flight/", "label": "Space Daily, Falcon 9 in 2025"}, {"url": "https://www.newsminimalist.com/articles/spacex-launches-86percent-of-global-payload-to-space-in-third-quarter-of-2024-452b896c", "label": "SpaceX share of global upmass, Q3 2024"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the chain from reuse to market share in order.", "steps": ["Boosters land and fly again", "Each flight costs less to supply", "The rocket flies more often", "It carries most of the mass to orbit"], "explanation": "Reuse lowers the cost of each flight, cheaper flights mean more of them, and frequent flights win the cargo."}, "numbers": {"kind": "numberSense", "prompt": "Falcon 9 flew 165 times in 2025. About how many flights a month is that?", "min": 0, "max": 40, "value": 14, "unit": "flights", "explanation": "165 flights over 12 months is about 14 a month."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks why reuse matters beyond saving hardware.", "prompt": "What's your answer?", "options": ["It lets the rocket fly far more often", "It makes rockets look more advanced", "It removes the need for any testing"], "correctIndex": 0, "consequences": ["Cadence is what wins the cargo.", "Looks are not the point.", "Reused boosters are still checked."], "explanation": "Reuse matters because it raises cadence, and cadence decides who carries the mass."}, "proReasoning": "Strong answers connect reuse to flights per year.", "commonMistake": "Treating reuse as only a cost trick.", "mentalModel": "Reuse buys cadence."}, "invest": {"call": {"kind": "theCall", "situation": "A launcher plans reuse but expects six flights a year.", "prompt": "What do you question?", "options": ["Whether it uses enough engines", "Whether six flights can pay for reuse", "Whether its logo is memorable to buyers"], "correctIndex": 1, "consequences": ["Engine count is not the test.", "Reuse pays off with high cadence.", "Branding is not the issue."], "explanation": "Reusable hardware costs more to build. It pays back only if the rocket flies often."}, "proReasoning": "Investors tie the reuse case to the flight rate.", "commonMistake": "Assuming reuse saves money at any cadence.", "mentalModel": "Reuse needs cadence."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your satellite company needs ten launches over two years.", "prompt": "Which provider fits best?", "options": ["The one with the newest rocket design", "The one with the fewest past flights", "One that flies often enough to book soon"], "correctIndex": 2, "consequences": ["New designs can slip.", "Few flights means few slots.", "Cadence means open slots."], "explanation": "A provider flying every few days has more slots and more spare capacity."}, "proReasoning": "Founders match their launch plan to providers with real cadence.", "commonMistake": "Choosing on design instead of flight rate.", "mentalModel": "Book where they fly often."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how one rocket can fly every 2.2 days.", "prompt": "What's the trick?", "options": ["Boosters land and fly again soon", "Thousands of rockets are built", "Each flight is a short test hop"], "correctIndex": 0, "consequences": ["Reuse frees the factory.", "Not thousands, a reused fleet.", "These are real orbital missions."], "explanation": "Landing and reflying boosters means the factory does not build a new one each time."}, "proReasoning": "Reuse turns a rocket into something more like an airliner.", "commonMistake": "Thinking every flight needs a new rocket.", "mentalModel": "Land, refly, repeat."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:990cabe77907$ml$]::text[]),
($ml$e8b2c61d-9182-54bc-a26c-ec6b4fe6617b$ml$::uuid, $ml$spacetech$ml$, 16, 3, $ml${"id": "spacetech-d16-c3", "title": "Pick the market signal", "lessonTitle": "Six of every seven kilograms", "slot": 3, "type": "decide", "brief": {"headline": "You're writing a market note on launch. In one quarter of 2024, SpaceX carried 85.7% of all mass launched, 362 metric tons.", "kicker": "You decide which numbers tell the real story.", "fullText": "Launch counts treat a small rocket and a heavy rocket the same. Mass shows who carries the cargo, and cadence shows who can carry it again soon.\n\nFalcon 9 flew about once every 2.2 days in 2025. A note that only counts launches would miss how concentrated the market is.", "sources": [{"url": "https://www.newsminimalist.com/articles/spacex-launches-86percent-of-global-payload-to-space-in-third-quarter-of-2024-452b896c", "label": "SpaceX share of global upmass, Q3 2024"}, {"url": "https://spacedaily.com/t-we-tend-to-think-reusable-rockets-are-still-experimental-but-in-2025-spacex-s-partly-reusable-falcon-9-flew-165-missions-one-every-2-2-days-and-successfully-delivered-its-payload-on-every-flight/", "label": "Space Daily, Falcon 9 in 2025"}]}, "evidence": {"kind": "faceOff", "prompt": "Which provider shapes launch prices for everyone more?", "left": {"name": "Carries 86% of mass to orbit", "note": "Flies every couple of days"}, "right": {"name": "Flies many small rockets", "note": "Each carries a few hundred kilograms"}, "correctIndex": 0, "explanation": "The provider carrying most of the mass sets the market price and schedule."}, "numbers": {"kind": "numberSense", "prompt": "SpaceX launched 362 metric tons in one quarter. About how many tons a month is that?", "min": 0, "max": 300, "value": 121, "unit": "t", "explanation": "362 tons over three months is about 121 tons a month."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your note must open with one chart.", "prompt": "What does it show?", "options": ["Launches by day of the week", "Share of mass launched by company", "Number of rocket companies founded"], "correctIndex": 1, "consequences": ["Not a market signal.", "Mass shows who carries the market.", "Founding counts miss scale."], "explanation": "Mass by company shows concentration that launch counts hide."}, "proReasoning": "Good notes lead with the metric that reveals power.", "commonMistake": "Opening with a chart that hides concentration.", "mentalModel": "Show mass by company."}, "invest": {"call": {"kind": "theCall", "situation": "One company carries about 86% of mass to orbit.", "prompt": "Which risk do you flag?", "options": ["Rockets might stop flying forever", "Satellites could get too light", "Its prices and schedule shape everyone"], "correctIndex": 2, "consequences": ["Not a realistic risk.", "Not the issue.", "Concentration is the real exposure."], "explanation": "When one supplier carries most mass, its decisions ripple through every customer."}, "proReasoning": "Investors flag supplier concentration for whole sectors.", "commonMistake": "Ignoring dependence on one provider.", "mentalModel": "Flag the concentration."}, "build_startup": {"call": {"kind": "theCall", "situation": "You pitch a launch startup to investors.", "prompt": "How do you frame the market?", "options": ["Show who carries the mass and where you fit", "Count launches and claim an equal share", "Skip the competition slide entirely"], "correctIndex": 0, "consequences": ["Honest framing earns trust.", "Equal shares mislead.", "Investors will ask anyway."], "explanation": "Investors know mass tells the real story. Show where your rocket fits in it."}, "proReasoning": "Founders win trust by using the metric investors use.", "commonMistake": "Pitching with numbers that flatter you.", "mentalModel": "Frame by mass."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why mass matters more than launches.", "prompt": "What's the answer?", "options": ["Launches are kept secret by law", "A heavy rocket carries far more per launch", "Mass is easier to count than launches"], "correctIndex": 1, "consequences": ["Launches are public.", "One launch is not one launch.", "Both are counted."], "explanation": "A small rocket and a heavy one each count as one launch, but carry very different loads."}, "proReasoning": "Counting kilograms shows who carries the cargo.", "commonMistake": "Thinking all launches are equal.", "mentalModel": "Count kilograms."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:09de408d2116$ml$]::text[]),
($ml$ef3d76ce-f4d2-5bda-8613-f725e383a375$ml$::uuid, $ml$spacetech$ml$, 17, 1, $ml${"id": "spacetech-d17-c1", "title": "Grounded by a landing", "lessonTitle": "Grounded after one failure", "slot": 1, "type": "apply", "brief": {"headline": "On August 28, 2024, a Falcon 9 booster crashed while landing at the end of its record 23rd flight. The FAA grounded Falcon 9 and required an investigation.", "kicker": "Apply the lesson: even a landing failure stops the rocket.", "fullText": "The booster, B1062, made a hard landing and was lost on the drone ship A Shortfall of Gravitas. It was the first booster landing failure since February 2021.\n\nThe failure happened after the rocket had done its main job, yet the FAA still grounded the fleet while the cause was investigated. The Polaris Dawn crewed mission was already waiting that week.", "sources": [{"url": "https://spaceflightnow.com/2024/08/28/faa-grounds-spacexs-falcon-9-rocket-following-landing-mishap/", "label": "Spaceflight Now, FAA grounds Falcon 9 after landing mishap, Aug 2024"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The booster was on its 23rd flight.", "It was the first landing failure since February 2021.", "The FAA let flights continue during the review."], "fakeIndex": 2, "explanation": "The FAA grounded Falcon 9 and required an investigation first."}, "numbers": {"kind": "numberSense", "prompt": "From February 2021 to August 2024, about how many months passed without a booster landing failure?", "min": 0, "max": 60, "value": 42, "unit": "months", "explanation": "About 42 months, three and a half years."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your launch is set for next week when a booster crashes on landing.", "prompt": "What do you check first?", "options": ["Whether the FAA has grounded the rocket", "Whether your satellite reached orbit", "Whether the drone ship was insured"], "correctIndex": 0, "consequences": ["A grounding moves every launch.", "Yours has not flown yet.", "Not your question."], "explanation": "Any mishap can trigger a grounding, even one after the payload is delivered."}, "proReasoning": "Launch teams watch the FAA status after any anomaly.", "commonMistake": "Assuming a landing failure cannot affect the schedule.", "mentalModel": "Check the grounding."}, "invest": {"call": {"kind": "theCall", "situation": "A launcher with a long success streak loses a booster.", "prompt": "How do you read it?", "options": ["Nothing changes, so ignore it", "A delay; watch how fast it recovers", "The company is finished for good"], "correctIndex": 1, "consequences": ["Groundings move manifests.", "Recovery speed is the signal.", "One loss rarely ends a launcher."], "explanation": "A grounding shifts schedules. How quickly the company finds the cause matters most."}, "proReasoning": "Investors track failures and recovery time together.", "commonMistake": "Overreacting or ignoring it entirely.", "mentalModel": "Watch the recovery."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your reusable rocket will try landings from its first flight.", "prompt": "How do you plan for a landing failure?", "options": ["Assume landings never ground a rocket", "Skip landings until the tenth flight", "Budget time for an investigation after one"], "correctIndex": 2, "consequences": ["The FAA requires a review.", "You lose the reuse data.", "Even landings can stop the fleet."], "explanation": "A failed landing can ground the rocket while the cause is found."}, "proReasoning": "Founders build investigation time into the plan.", "commonMistake": "Treating landings as outside the rules.", "mentalModel": "Plan for the review."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a crash at sea stopped all Falcon 9 flights.", "prompt": "What's the reason?", "options": ["Regulators want the cause found first", "The ship was the only one in use", "All boosters were recalled for good"], "correctIndex": 0, "consequences": ["Safety comes before the next flight.", "SpaceX has more ships.", "It was a pause, not a recall."], "explanation": "The FAA needs to know what went wrong before the rocket flies again."}, "proReasoning": "One failure pauses the fleet until the cause is clear.", "commonMistake": "Thinking only mission failures count.", "mentalModel": "Find the cause first."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f813c2a63eb5$ml$]::text[]),
($ml$c5aa88f8-7f44-591a-acbb-0237a6dfa02a$ml$::uuid, $ml$spacetech$ml$, 17, 2, $ml${"id": "spacetech-d17-c2", "title": "Two rockets, by design", "lessonTitle": "Grounded after one failure", "slot": 2, "type": "connect", "brief": {"headline": "Day 15 showed US policy keeps at least two rockets for national security launches. Day 17 showed why: Falcon 9 was grounded for 16 days in July 2024.", "kicker": "Connect day 15 and day 17: a second rocket covers a grounding.", "fullText": "On day 15 you saw Congress require at least two launch vehicles able to carry any national security payload, and the Space Force split launches between SpaceX, ULA and Blue Origin in April 2025.\n\nOn day 17 you saw a near-perfect rocket stop after one failure. Falcon 9 had flown 364 times successfully since 2010, yet it stayed down until the FAA cleared it. A buyer with only one rocket would have been stuck.", "sources": [{"url": "https://www.everycrsreport.com/files/2026-01-14_IF12900_e1a9a9283349423491e151fac8e59426a6fa6708.html", "label": "Congressional Research Service, National Security Space Launch"}, {"url": "https://www.satellitetoday.com/launch/2025/04/06/spacex-ula-blue-origin-receive-nssl-contracts-worth-up-to-nearly-14b/", "label": "Via Satellite, NSSL Phase 3 Lane 2 awards"}, {"url": "https://spacepolicyonline.com/news/rare-spacex-failure-leaves-launch-schedules-in-flux/", "label": "SpacePolicyOnline, rare SpaceX failure"}, {"url": "https://cosmiclog.com/2024/07/27/spacex-resumes-falcon-9-launches-after-faa-go-ahead/", "label": "Cosmic Log, Falcon 9 returns after FAA go-ahead"}]}, "evidence": {"kind": "faceOff", "prompt": "Which buyer copes better with a 16-day grounding?", "left": {"name": "A buyer with one rocket", "note": "Every mission waits"}, "right": {"name": "A buyer with two rockets", "note": "Urgent missions can move"}, "correctIndex": 1, "explanation": "A second qualified rocket keeps critical missions moving when one is grounded."}, "numbers": {"kind": "numberSense", "prompt": "How many days after the July 2024 failure did Falcon 9 fly again?", "min": 0, "max": 45, "value": 16, "unit": "days", "explanation": "It failed on July 11 and launched again on July 27, 16 days later."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You are asked why the Space Force pays more than one launcher.", "prompt": "What's your answer?", "options": ["To give each company equal revenue", "So one grounding never stops its missions", "Because the law bans single contracts"], "correctIndex": 1, "consequences": ["Shares are not equal.", "Redundancy is the purpose.", "The rule is about vehicles, not contracts."], "explanation": "Policy keeps two rockets so national security does not depend on one."}, "proReasoning": "Strong answers link the two-rocket rule to groundings.", "commonMistake": "Calling it a subsidy with no purpose.", "mentalModel": "Two rockets for resilience."}, "invest": {"call": {"kind": "theCall", "situation": "A launcher is one of only two that can fly a key payload.", "prompt": "How do you value that position?", "options": ["As worthless, since the other rocket wins", "As temporary, since rules change yearly", "As durable, since the buyer needs a backup"], "correctIndex": 2, "consequences": ["The buyer keeps both by design.", "The rule is long-standing policy.", "Policy protects the second slot."], "explanation": "When policy requires two suppliers, being one of them is a strong position."}, "proReasoning": "Investors look for positions protected by rules.", "commonMistake": "Ignoring the policy behind the contract.", "mentalModel": "Policy backs the second slot."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your satellite is critical and the main rocket might ground.", "prompt": "What do you design for?", "options": ["Fitting more than one rocket", "Fitting only the cheapest rocket", "Fitting a rocket still on paper"], "correctIndex": 0, "consequences": ["Two options cut your risk.", "One option is one point of failure.", "Too uncertain."], "explanation": "Designing for two rockets lets you switch if one is grounded."}, "proReasoning": "Founders copy the buyer's two-rocket logic.", "commonMistake": "Locking into one ride with no plan B.", "mentalModel": "Fit two rockets."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the military keeps two rocket companies busy.", "prompt": "What's the reason?", "options": ["To test which rocket is faster", "So a failure never grounds every mission", "Because one company refused the work"], "correctIndex": 1, "consequences": ["Speed is not the point.", "A backup keeps missions flying.", "Not the reason."], "explanation": "Even the best rocket stops after a failure. A second one keeps missions going."}, "proReasoning": "Redundancy is planned, not wasteful.", "commonMistake": "Thinking one great rocket is enough.", "mentalModel": "Always have a backup."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a7be2b4e6fe7$ml$]::text[]),
($ml$94d56a09-9d1c-5ed7-878e-6a20c63621af$ml$::uuid, $ml$spacetech$ml$, 17, 3, $ml${"id": "spacetech-d17-c3", "title": "Run the return to flight", "lessonTitle": "Grounded after one failure", "slot": 3, "type": "decide", "brief": {"headline": "You run launch operations. A cracked oxygen sense line just caused an upper stage failure and 20 satellites were lost.", "kicker": "You decide how to get back to flight safely.", "fullText": "The FAA requires a mishap investigation before your rocket can fly again. It must be satisfied that public safety is not at risk.\n\nIn July 2024, SpaceX traced a similar failure to a sense line worn by engine vibration, and the FAA cleared a return to flight 14 days later. Crewed flights and science missions were waiting behind it.", "sources": [{"url": "https://spacepolicyonline.com/news/rare-spacex-failure-leaves-launch-schedules-in-flux/", "label": "SpacePolicyOnline, rare SpaceX failure"}, {"url": "https://cosmiclog.com/2024/07/27/spacex-resumes-falcon-9-launches-after-faa-go-ahead/", "label": "Cosmic Log, Falcon 9 returns after FAA go-ahead"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each step speed a safe return to flight?", "buckets": ["Speeds return", "Doesn't"], "items": [{"text": "Find the root cause quickly", "bucket": 0}, {"text": "Share test data with the FAA", "bucket": 0}, {"text": "Fix the part on every rocket", "bucket": 0}, {"text": "Launch before the FAA clears it", "bucket": 1}, {"text": "Blame the weather and move on", "bucket": 1}], "explanation": "A clear cause and a fleet-wide fix are what earn the FAA's approval."}, "numbers": {"kind": "numberSense", "prompt": "How many Starlink satellites were lost in the July 2024 failure?", "min": 0, "max": 60, "value": 20, "unit": "satellites", "explanation": "The failed upper stage left 20 satellites too low to survive."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks what to tell waiting customers.", "prompt": "What's your advice?", "options": ["Promise to fly tomorrow regardless", "Say nothing until the FAA decides", "Share the cause and a realistic date"], "correctIndex": 2, "consequences": ["You cannot fly without clearance.", "Silence worries them more.", "Honesty keeps their trust."], "explanation": "Customers plan around your schedule. A clear cause and date help them most."}, "proReasoning": "Ops leads keep customers informed through a grounding.", "commonMistake": "Overpromising a date the FAA controls.", "mentalModel": "Share cause and timing."}, "invest": {"call": {"kind": "theCall", "situation": "The failure cost 20 satellites but the cause is found fast.", "prompt": "What matters most for the company?", "options": ["How fast it flies again safely", "Whether the stock dips that day", "How many tweets mention it"], "correctIndex": 0, "consequences": ["Return speed protects the manifest.", "Short-term noise.", "Not a business measure."], "explanation": "A quick, safe return limits the damage to the launch schedule."}, "proReasoning": "Investors judge launchers on recovery, not perfection.", "commonMistake": "Focusing on headlines instead of recovery.", "mentalModel": "Fast, safe return."}, "build_startup": {"call": {"kind": "theCall", "situation": "A worn part caused the failure.", "prompt": "What do you change for the long run?", "options": ["Stop reusing any hardware at all", "Inspect that part on every flight", "Skip the fix to save launch time"], "correctIndex": 1, "consequences": ["Overreacts to one part.", "Catches wear before it fails.", "The same failure could repeat."], "explanation": "A targeted inspection fixes the real cause without abandoning reuse."}, "proReasoning": "Founders fix the cause, not the whole design.", "commonMistake": "Ignoring a known wear problem.", "mentalModel": "Inspect the weak part."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks who lets a rocket fly again after a failure.", "prompt": "Who decides?", "options": ["The rocket company on its own", "The customer whose satellite was lost", "The FAA, once safety is shown"], "correctIndex": 2, "consequences": ["The company cannot clear itself.", "Customers do not decide.", "It must be satisfied first."], "explanation": "In the US, the FAA must be satisfied public safety is protected before a return to flight."}, "proReasoning": "A regulator stands between a failure and the next launch.", "commonMistake": "Thinking companies clear their own rockets.", "mentalModel": "The FAA decides."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:58b978435d1a$ml$]::text[]),
($ml$65c4493b-a570-516a-a422-9d4c2448d60b$ml$::uuid, $ml$spacetech$ml$, 18, 1, $ml${"id": "spacetech-d18-c1", "title": "A rocket startup quits launch", "lessonTitle": "The launch company that ran out of money", "slot": 1, "type": "apply", "brief": {"headline": "In November 2024, ABL Space Systems ended its orbital launch plans and pivoted to missile defense. Its RS1 rocket never reached orbit.", "kicker": "Apply the lesson: a small launcher that cannot fly runs out of road.", "fullText": "ABL's first RS1 fell back onto its pad in Alaska and exploded in January 2023. Its second RS1 was destroyed during preflight testing in July 2024.\n\nOn November 14, 2024, co-founder Dan Piemont said ABL would focus on national defense, specifically missile defense. It planned to reuse its RS1 rocket, GS0 ground system and E2 engine for that work instead of selling launches.", "sources": [{"url": "https://www.space.com/space-exploration/launches-spacecraft/rocket-startup-abl-space-systems-ends-orbital-launch-plans-pivots-to-missile-defense", "label": "Space.com, ABL Space Systems ends orbital launch plans, Nov 2024"}]}, "evidence": {"kind": "buildChain", "prompt": "Put ABL's path out of launch in order.", "steps": ["First RS1 falls back onto the pad", "Second RS1 is lost in preflight testing", "ABL ends its orbital launch plans", "Its rocket tech turns to missile defense"], "explanation": "Two lost rockets and no orbit pushed ABL out of the launch market."}, "numbers": {"kind": "numberSense", "prompt": "About how many months passed from the January 2023 failure to the November 2024 pivot?", "min": 0, "max": 36, "value": 22, "unit": "months", "explanation": "January 2023 to November 2024 is about 22 months."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You have an offer from a small launcher with no successful flight yet.", "prompt": "What do you ask?", "options": ["How big its office is", "How long its cash will last", "What color the rocket will be"], "correctIndex": 1, "consequences": ["Offices do not fly rockets.", "Runway decides if you have a job.", "Not a real question."], "explanation": "A launcher with no flights burns cash. Runway tells you how many tries it has left."}, "proReasoning": "Candidates ask about runway at pre-revenue launchers.", "commonMistake": "Joining without asking how long the money lasts.", "mentalModel": "Ask about runway."}, "invest": {"call": {"kind": "theCall", "situation": "A launcher lost its first two rockets and has no orbit yet.", "prompt": "What do you weigh?", "options": ["Only how good the founders sound", "The size of its total market", "Whether it can fund another try at all"], "correctIndex": 2, "consequences": ["Talk does not reach orbit.", "Market size is not the problem.", "Each try costs a rocket."], "explanation": "Without a working rocket and cash for another attempt, the market size does not matter."}, "proReasoning": "Investors count how many attempts the cash allows.", "commonMistake": "Backing a big market without checking survival.", "mentalModel": "Count the attempts left."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your rocket keeps failing and money is tight.", "prompt": "What could keep your team alive?", "options": ["Selling the tech to a buyer who needs it", "One more launch with no cash left", "Raising prices for future launches"], "correctIndex": 0, "consequences": ["ABL turned to missile defense.", "Too risky with no runway.", "You have no launches to sell."], "explanation": "Rocket hardware and know-how can have buyers outside launch."}, "proReasoning": "Founders look for a second use for hard-won tech.", "commonMistake": "Betting the company on one more try.", "mentalModel": "Find a second buyer."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what happens to a rocket company that never reaches orbit.", "prompt": "What's one path?", "options": ["The government takes its rockets", "It reuses its tech for another market", "It keeps launching for free forever"], "correctIndex": 1, "consequences": ["Not what happened.", "ABL moved to missile defense.", "Not possible without money."], "explanation": "Some launchers pivot their engines and ground systems to defense work."}, "proReasoning": "Rocket tech can outlive a launch business.", "commonMistake": "Thinking failed launchers just vanish.", "mentalModel": "The tech finds new work."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2e512ac8749d$ml$]::text[]),
($ml$c1679884-7aaa-53c0-90f1-4fe451ffa17e$ml$::uuid, $ml$spacetech$ml$, 18, 2, $ml${"id": "spacetech-d18-c2", "title": "Competing with a $350,000 seat", "lessonTitle": "The launch company that ran out of money", "slot": 2, "type": "connect", "brief": {"headline": "Day 9 showed a rideshare seat costs about $7,000 per kg, but the rocket picks your orbit. Day 18 showed what that price does to small rockets.", "kicker": "Connect day 9 and day 18: rideshare sets the bar small rockets must beat.", "fullText": "On day 9 you saw that a 50 kg seat on SpaceX's Transporter cost $350,000 for 2026 flights, in exchange for flying where and when the big rocket goes.\n\nOn day 18 you saw Virgin Orbit raise more than $1 billion yet fly only six times. A small rocket cannot beat rideshare on price, so it has to sell the orbit and the date a customer cannot get on a shared ride.", "sources": [{"url": "https://newspaceeconomy.ca/2026/02/27/satellite-ridesharing-market-analysis-2026/", "label": "New Space Economy, rideshare market 2026"}, {"url": "https://thespacereview.com/article/4593/1", "label": "The Space Review, death of a launch company"}]}, "evidence": {"kind": "multipleChoice", "prompt": "A small launcher competes with a $7,000-per-kg rideshare. What can it sell?", "options": ["A lower price per kilogram than rideshare", "Room for bigger satellites than Falcon 9", "The exact orbit and date a customer needs"], "correctIndex": 2, "explanation": "Rideshare wins on price. Small rockets win on control of orbit and timing."}, "numbers": {"kind": "numberSense", "prompt": "At about $7,000 per kg, what would a 100 kg rideshare seat cost, in millions of dollars?", "min": 0, "max": 2, "value": 0.7, "unit": "M", "explanation": "100 kg at $7,000 per kg is about $700,000."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join sales at a small launcher.", "prompt": "What do you lead with to customers?", "options": ["The lowest price per kilogram", "The biggest payload in the market", "Your own orbit and launch date"], "correctIndex": 2, "consequences": ["Rideshare is cheaper.", "Small rockets are small.", "Rideshare cannot offer that."], "explanation": "Small launchers sell control that a shared ride cannot give."}, "proReasoning": "Good sellers lead with what rivals cannot match.", "commonMistake": "Competing on price against rideshare.", "mentalModel": "Sell orbit and date."}, "invest": {"call": {"kind": "theCall", "situation": "A small launcher plans to undercut rideshare prices.", "prompt": "How do you react?", "options": ["Skeptical, rideshare splits the cost", "Excited, price always wins in launch", "Neutral, price does not matter"], "correctIndex": 0, "consequences": ["Shared rides are hard to undercut.", "Not against a shared heavy rocket.", "Price matters a lot here."], "explanation": "A heavy rocket split among dozens of satellites is very hard to beat on price."}, "proReasoning": "Investors test a launcher's plan against rideshare.", "commonMistake": "Believing a small rocket can win on price.", "mentalModel": "Doubt price-led plans."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your satellite needs a 450 km orbit at 37 degrees.", "prompt": "Which ride do you consider first?", "options": ["Any rocket leaving next month", "A dedicated launch or a space tug", "A standard rideshare drop as is"], "correctIndex": 1, "consequences": ["Timing alone is not enough.", "Rideshare will not go there.", "Wrong orbit for your mission."], "explanation": "A standard rideshare will not drop you there. You need your own ride or a tug."}, "proReasoning": "Founders choose the ride by orbit first, then price.", "commonMistake": "Picking the cheapest ride for the wrong orbit.", "mentalModel": "Orbit first, price second."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why tiny rockets exist if rideshare is cheaper.", "prompt": "What's the reason?", "options": ["Small rockets are always cheaper per kg", "Rideshare is banned for small satellites", "Some satellites need their own orbit or date"], "correctIndex": 2, "consequences": ["They usually cost more per kg.", "Rideshare carries many small ones.", "That is their market."], "explanation": "A small rocket goes where and when you choose. A shared ride does not."}, "proReasoning": "Control of orbit and timing has a price.", "commonMistake": "Thinking price is the only factor.", "mentalModel": "You pay for control."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4dcd5c891e42$ml$]::text[]),
($ml$11765695-3ac0-521d-900d-db5fe3ceab6a$ml$::uuid, $ml$spacetech$ml$, 18, 3, $ml${"id": "spacetech-d18-c3", "title": "Six flights, $1 billion raised", "lessonTitle": "The launch company that ran out of money", "slot": 3, "type": "decide", "brief": {"headline": "You're advising a small launcher's board. Virgin Orbit raised more than $1 billion, flew six times and lost $191.1 million in 2022.", "kicker": "You decide which signs say a launcher can survive.", "fullText": "Virgin Orbit lost about $50 million a quarter. After a failed launch from the UK in January 2023, it cut all but 100 of nearly 800 staff and filed for bankruptcy in April.\n\nIts assets sold for about $36.5 million at auction. Small launchers face hard math: few flights against high fixed costs.", "sources": [{"url": "https://thespacereview.com/article/4593/1", "label": "The Space Review, death of a launch company"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each sign help or hurt a small launcher's survival?", "buckets": ["Helps", "Hurts"], "items": [{"text": "A backlog of paying flights", "bucket": 0}, {"text": "Launching every month", "bucket": 0}, {"text": "Six flights in several years", "bucket": 1}, {"text": "Losing about $50 million a quarter", "bucket": 1}, {"text": "Selling what rideshare cannot", "bucket": 0}], "explanation": "Paying flights and cadence keep a launcher alive. Rare flights and big losses sink it."}, "numbers": {"kind": "numberSense", "prompt": "Virgin Orbit lost $191.1 million in 2022. About how much per quarter, in millions?", "min": 0, "max": 150, "value": 48, "unit": "M", "explanation": "$191.1 million over four quarters is about $48 million each."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "The board asks for the one number to watch.", "prompt": "Which do you pick?", "options": ["Flights per year against fixed costs", "Total money raised since founding", "Number of press mentions this year"], "correctIndex": 0, "consequences": ["That decides break-even.", "Raising is not earning.", "Not a survival measure."], "explanation": "A launcher survives when enough flights cover its fixed costs."}, "proReasoning": "Advisers focus the board on break-even cadence.", "commonMistake": "Pointing to money raised as proof of health.", "mentalModel": "Watch cadence vs costs."}, "invest": {"call": {"kind": "theCall", "situation": "A launcher has raised a lot but flies twice a year.", "prompt": "How do you judge it?", "options": ["Fine, flight count does not matter", "Risky, the cash burns between flights", "Safe, the raise proves its value"], "correctIndex": 1, "consequences": ["It matters most.", "Rare flights cannot cover costs.", "Raising is not proof."], "explanation": "Money raised buys time, but only flights pay the bills."}, "proReasoning": "Investors compare burn rate with flight rate.", "commonMistake": "Treating a big raise as safety.", "mentalModel": "Flights pay, raises buy time."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your launcher burns $50 million a quarter.", "prompt": "What is the first move?", "options": ["Build a bigger rocket right away", "Spend more on marketing", "Cut costs and book paying flights"], "correctIndex": 2, "consequences": ["Raises costs further.", "Does not fix the math.", "Buys runway and revenue."], "explanation": "Survival means cutting burn and filling the manifest with paying flights."}, "proReasoning": "Founders fix the math before expanding.", "commonMistake": "Growing costs when flights are rare.", "mentalModel": "Cut burn, add flights."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a company with $1 billion went bankrupt.", "prompt": "What's the reason?", "options": ["It flew too rarely to cover costs", "It forgot how to build rockets", "A law banned its launches"], "correctIndex": 0, "consequences": ["Six flights, high costs.", "It built working rockets.", "No such law."], "explanation": "Six flights could not pay for a company losing about $50 million a quarter."}, "proReasoning": "In launch, flying often is how you pay the bills.", "commonMistake": "Thinking money raised guarantees survival.", "mentalModel": "Too few flights."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5e94554afa91$ml$]::text[]),
($ml$11e07ac5-fd80-56e6-92c9-4704e0165df1$ml$::uuid, $ml$spacetech$ml$, 19, 1, $ml${"id": "spacetech-d19-c1", "title": "Five rockets, one customer", "lessonTitle": "What a space agency actually does", "slot": 1, "type": "apply", "brief": {"headline": "In July 2025, ESA picked five rocket companies for its European Launcher Challenge. Each became eligible for up to 169 million euros.", "kicker": "Apply the lesson: an agency acts as a customer, not a builder.", "fullText": "The five were Isar Aerospace and Rocket Factory Augsburg of Germany, MaiaSpace of France, PLD Space of Spain and Orbex of the UK.\n\nThe challenge has two parts: launch services for ESA from 2026 to 2030, and development of larger, upgraded launchers. ESA does not build these rockets. It buys launches and pays companies to grow them, with final funding set at its November ministerial council.", "sources": [{"url": "https://www.space.com/astronomy/earth/esa-selects-5-rocket-companies-for-european-launcher-challenge", "label": "Space.com, ESA selects five companies for the European Launcher Challenge, Jul 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each selected company based in Germany?", "buckets": ["Germany", "Elsewhere"], "items": [{"text": "Isar Aerospace", "bucket": 0}, {"text": "Rocket Factory Augsburg", "bucket": 0}, {"text": "MaiaSpace", "bucket": 1}, {"text": "PLD Space", "bucket": 1}, {"text": "Orbex", "bucket": 1}], "explanation": "Two German companies, plus one each from France, Spain and the UK."}, "numbers": {"kind": "numberSense", "prompt": "Five companies, each eligible for up to 169 million euros. What is the most in total, in millions?", "min": 0, "max": 1500, "value": 845, "unit": "M", "explanation": "5 times 169 million is about 845 million euros."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join one of the five selected rocket companies.", "prompt": "Who is your most important customer?", "options": ["Tourists buying rides to space", "A rival launcher buying parts", "ESA, buying launches through 2030"], "correctIndex": 2, "consequences": ["Not this rocket's market.", "Not the business.", "ESA pays for launches and growth."], "explanation": "ESA is buying launch services and paying for upgrades. It is the anchor customer."}, "proReasoning": "Staff know who pays for the next five years.", "commonMistake": "Forgetting the agency is a customer.", "mentalModel": "ESA is the customer."}, "invest": {"call": {"kind": "theCall", "situation": "A European launch startup was selected by ESA.", "prompt": "What does selection give it?", "options": ["A path to paid launches and funding", "A guarantee it will never fail", "Ownership of an ESA rocket"], "correctIndex": 0, "consequences": ["Up to 169 million euros each.", "Selection is not success.", "ESA buys, it does not hand over rockets."], "explanation": "Selection opens contracts worth up to 169 million euros. Delivery still decides."}, "proReasoning": "Investors treat agency selection as demand, not proof.", "commonMistake": "Reading selection as guaranteed success.", "mentalModel": "Demand, not a guarantee."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a launch startup outside the five.", "prompt": "What is your best move?", "options": ["Build a rocket factory for ESA", "Fly and prove it for the next round", "Complain that ESA picked wrong"], "correctIndex": 1, "consequences": ["ESA buys rides, not factories.", "Proof wins future contracts.", "Does not win work."], "explanation": "Agencies buy from companies that show they can deliver."}, "proReasoning": "Founders earn the next selection by flying.", "commonMistake": "Expecting contracts without proof.", "mentalModel": "Prove, then bid."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend thinks ESA builds its own rockets.", "prompt": "What's the truth?", "options": ["It builds every rocket in-house", "It borrows rockets from NASA", "It buys launches from companies"], "correctIndex": 2, "consequences": ["Companies build them.", "Not how it works.", "ESA acts as a customer."], "explanation": "ESA picks companies and pays them for launches and development."}, "proReasoning": "Space agencies are mostly customers.", "commonMistake": "Thinking agencies build everything.", "mentalModel": "Agencies buy."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5cbb31745457$ml$]::text[]),
($ml$114a94bc-9123-535d-a73c-dec335d9a963$ml$::uuid, $ml$spacetech$ml$, 19, 2, $ml${"id": "spacetech-d19-c2", "title": "After a year without a rocket", "lessonTitle": "What a space agency actually does", "slot": 2, "type": "connect", "brief": {"headline": "Day 6 showed Europe without its own big rocket from July 2023 to July 2024. Day 19 showed how ESA answers: as a customer with a 7.7 billion euro budget.", "kicker": "Connect day 6 and day 19: a customer can fix a single point of failure.", "fullText": "On day 6 you saw Ariane 5 retire, Soyuz leave Europe's spaceport and Vega-C fail, so ESA flew its Euclid telescope on a SpaceX Falcon 9. Launches from Kourou fell from 15 in 2021 to six in 2022.\n\nOn day 19 you saw that ESA spends its money as a customer, placing contracts with companies across its member states. Buying from several suppliers is one way a customer avoids being stuck again.", "sources": [{"url": "https://www.voanews.com/a/ariane-5-blasts-off-for-final-time-amid-europe-s-rocketing-challenges/7169231.html", "label": "VOA, final Ariane 5 launch"}, {"url": "https://aviationweek.com/space/budget-policy-regulation/esa-council-oks-initial-eu77b-2025-budget-readies-launcher-challenge", "label": "Aviation Week, ESA 2025 budget of 7.7 billion euros"}, {"url": "https://www.esa.int/About_Us/Business_with_ESA/Business_Opportunities/ESA_an_intergovernmental_customer", "label": "ESA, an intergovernmental customer"}]}, "evidence": {"kind": "faceOff", "prompt": "After the gap year, which plan cuts ESA's risk more?", "left": {"name": "Buy launches from several companies", "note": "More than one European ride"}, "right": {"name": "Rely on one new rocket again", "note": "One ride for every big mission"}, "correctIndex": 0, "explanation": "Several suppliers mean one failure no longer grounds Europe."}, "numbers": {"kind": "numberSense", "prompt": "Kourou launches fell from 15 in 2021 to six in 2022. By what percent?", "min": 0, "max": 100, "value": 60, "unit": "%", "explanation": "Going from 15 to 6 is a 60% drop."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked what Europe learned from its year without a rocket.", "prompt": "What's your answer?", "options": ["Do not depend on one launcher", "Never buy launches from others", "Stop launching science missions"], "correctIndex": 0, "consequences": ["One rocket was a single point of failure.", "ESA bought a Falcon 9 ride.", "Science continued."], "explanation": "Losing three rockets at once showed the cost of depending on one."}, "proReasoning": "Strong answers turn the gap year into a lesson on suppliers.", "commonMistake": "Blaming bad luck instead of the setup.", "mentalModel": "More than one ride."}, "invest": {"call": {"kind": "theCall", "situation": "ESA now buys launches from several new companies.", "prompt": "What does that mean for them?", "options": ["No customer, ESA flies its own", "A customer that wants more than one ride", "A customer that will pick only one"], "correctIndex": 1, "consequences": ["ESA buys rides.", "Room for several winners.", "The lesson was the opposite."], "explanation": "A buyer burned by one-rocket dependence wants multiple suppliers."}, "proReasoning": "Investors read customer history to predict demand.", "commonMistake": "Assuming a winner-take-all market.", "mentalModel": "Room for several."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your launch startup pitches ESA after the gap year.", "prompt": "What do you stress?", "options": ["You will replace every other rocket", "You are cheaper than SpaceX", "You add a second European option"], "correctIndex": 2, "consequences": ["Overclaims and alarms them.", "Price is not the main worry.", "That is what ESA wants now."], "explanation": "After depending on one rocket, ESA values another European ride."}, "proReasoning": "Founders pitch to the buyer's fresh pain.", "commonMistake": "Pitching dominance to a buyer who fears it.", "mentalModel": "Be the second option."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why ESA flew a telescope on a SpaceX rocket.", "prompt": "What's the reason?", "options": ["Europe had no big rocket of its own", "SpaceX owns the Euclid telescope", "Ariane 6 was too large for it"], "correctIndex": 0, "consequences": ["Ariane 5 had retired.", "ESA owns Euclid.", "Ariane 6 was not flying yet."], "explanation": "With Ariane 5 retired and Ariane 6 late, ESA bought a ride from SpaceX."}, "proReasoning": "Even agencies buy from rivals when stuck.", "commonMistake": "Thinking agencies always have their own rocket.", "mentalModel": "Europe had no ride."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0b7ccc925afd$ml$]::text[]),
($ml$a8c8134b-bc72-5c8d-b8b9-50804f2aca91$ml$::uuid, $ml$spacetech$ml$, 19, 3, $ml${"id": "spacetech-d19-c3", "title": "Where the 7.7 billion euros goes", "lessonTitle": "What a space agency actually does", "slot": 3, "type": "decide", "brief": {"headline": "You're briefing a new ESA delegate. ESA's 2025 budget was 7.7 billion euros: 4.8 billion from members, 1.7 billion from the EU, 1.2 billion from others.", "kicker": "You decide how to explain what an agency really does.", "fullText": "ESA describes itself as an intergovernmental customer. It plans programs and places contracts with companies across its member states, which turn into multi-year work for industry.\n\nNASA works the same way at a larger scale. Congress passed $24.4 billion for it in fiscal 2026.", "sources": [{"url": "https://aviationweek.com/space/budget-policy-regulation/esa-council-oks-initial-eu77b-2025-budget-readies-launcher-challenge", "label": "Aviation Week, ESA 2025 budget of 7.7 billion euros"}, {"url": "https://www.esa.int/About_Us/Business_with_ESA/Business_Opportunities/ESA_an_intergovernmental_customer", "label": "ESA, an intergovernmental customer"}, {"url": "https://space.com/space-exploration/in-rejection-of-trumps-deep-cuts-congress-passes-usd24-4-billion-budget-for-nasa", "label": "Space.com, NASA fiscal 2026 budget"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["ESA builds most of its spacecraft in-house.", "Member states gave 4.8 billion euros in 2025.", "Congress passed $24.4 billion for NASA in fiscal 2026."], "fakeIndex": 0, "explanation": "ESA is mostly a customer. Companies build what it plans."}, "numbers": {"kind": "numberSense", "prompt": "Members gave 4.8 billion of the 7.7 billion euros. About what percent is that?", "min": 0, "max": 100, "value": 62, "unit": "%", "explanation": "4.8 divided by 7.7 is about 62%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "The delegate asks what ESA does with its budget.", "prompt": "What's your one-line answer?", "options": ["Gives grants with no deliverables", "Pays companies to build what it plans", "Builds rockets in its own factories"], "correctIndex": 1, "consequences": ["Contracts have deliverables.", "It is a customer.", "Industry builds them."], "explanation": "Agencies plan missions and pay industry to build them."}, "proReasoning": "Good briefings start with how the money flows.", "commonMistake": "Describing ESA as a factory.", "mentalModel": "Plans, then pays."}, "invest": {"call": {"kind": "theCall", "situation": "ESA starts a big new program.", "prompt": "Who benefits most?", "options": ["Only ESA staff at its Paris HQ", "Nobody at all until launch day", "Companies that win its contracts"], "correctIndex": 2, "consequences": ["Most money goes out.", "Contracts pay along the way.", "Money becomes industry work."], "explanation": "A new program turns into multi-year contracts for companies."}, "proReasoning": "Investors follow agency programs to find future revenue.", "commonMistake": "Ignoring where the program money goes.", "mentalModel": "Follow the contracts."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want ESA as a customer.", "prompt": "What do you learn first?", "options": ["What it funds and how it buys", "How to build a rocket alone", "Who works in its cafeteria"], "correctIndex": 0, "consequences": ["That is where contracts come from.", "Not the first step.", "Not useful."], "explanation": "Knowing ESA's programs and buying rules is how startups win contracts."}, "proReasoning": "Founders study the buyer before the pitch.", "commonMistake": "Pitching without knowing how ESA buys.", "mentalModel": "Learn how it buys."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how ESA compares with NASA.", "prompt": "What's a fair answer?", "options": ["They have the same budget", "NASA is about three times bigger", "ESA is far bigger than NASA"], "correctIndex": 1, "consequences": ["Not close.", "$24.4 billion vs 7.7 billion euros.", "NASA is larger."], "explanation": "NASA had $24.4 billion for fiscal 2026, about three times ESA's 2025 budget."}, "proReasoning": "Both work mainly by buying from companies.", "commonMistake": "Assuming the two are the same size.", "mentalModel": "NASA, about three times."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:db3079e241d9$ml$]::text[]),
($ml$fe5f4d9d-26a4-5182-9c14-7686ab2222a9$ml$::uuid, $ml$spacetech$ml$, 20, 1, $ml${"id": "spacetech-d20-c1", "title": "Germany pays 23 percent", "lessonTitle": "Every euro comes home", "slot": 1, "type": "apply", "brief": {"headline": "At ESA's November 2025 ministerial, Germany pledged about 5.4 billion euros, roughly 23% of all subscriptions. France and Italy each gave about 16%.", "kicker": "Apply the lesson: who pays the most expects the most work.", "fullText": "DLR said Germany remained ESA's largest contributor, out of a total of about 22 billion euros. ESA's own calculation put Germany's pledge at about 5.1 billion euros.\n\nUnder geo-return, contracts flow back to each country's industry roughly in proportion to what it pays. A 23% share is a claim on about 23% of the work, program by program.", "sources": [{"url": "https://www.dlr.de/en/latest/news/2025/germany-invests-5-4-billion-euros-in-the-future-of-european-space", "label": "DLR, Germany invests 5.4 billion euros in European space, Nov 2025"}, {"url": "https://www.esa.int/About_Us/Business_with_ESA/Business_Opportunities/ESA_an_intergovernmental_customer", "label": "ESA, an intergovernmental customer"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Germany pays about 23% of ESA subscriptions. Under geo-return, what should German firms expect?", "options": ["Every launcher contract, whatever it pays", "Contracts set only by the lowest bid", "About 23% of the contracts, program by program"], "correctIndex": 2, "explanation": "Geo-return aims to match each country's share of contracts to its share of funding."}, "numbers": {"kind": "numberSense", "prompt": "France gave about 16% of 22 billion euros. About how much is that, in billions?", "min": 0, "max": 8, "value": 3.5, "unit": "B", "explanation": "16% of 22 billion is about 3.5 billion euros."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a German space supplier after the 2025 ministerial.", "prompt": "Why is the outlook good?", "options": ["Germany pays most, so work comes home", "ESA must buy from Germany first", "German rockets are the only option"], "correctIndex": 0, "consequences": ["Geo-return follows the money.", "No such rule.", "Not true."], "explanation": "The biggest contributor can expect the biggest share of contracts."}, "proReasoning": "Staff link their country's pledge to their pipeline.", "commonMistake": "Thinking contracts ignore who paid.", "mentalModel": "Money brings work home."}, "invest": {"call": {"kind": "theCall", "situation": "A country raises its ESA pledge sharply.", "prompt": "What do you expect for its suppliers?", "options": ["Fewer contracts, money goes abroad", "More ESA contracts over the next years", "No change, pledges are symbolic"], "correctIndex": 1, "consequences": ["The opposite of the rule.", "Geo-return sends work back.", "Pledges drive contracts."], "explanation": "Under geo-return, a bigger pledge means more contracts for that country's industry."}, "proReasoning": "Investors read pledges as a forecast of contracts.", "commonMistake": "Ignoring how geo-return works.", "mentalModel": "Bigger pledge, more work."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are deciding where to base a space startup in Europe.", "prompt": "What do you weigh?", "options": ["Only how sunny the city is", "Whether ESA has an office nearby", "How much that country pays into ESA"], "correctIndex": 2, "consequences": ["Not a business factor.", "Offices do not set work shares.", "Pledges shape local contracts."], "explanation": "A country's ESA contribution shapes how much ESA work its firms can win."}, "proReasoning": "Founders factor geo-return into location.", "commonMistake": "Ignoring the funding behind contracts.", "mentalModel": "Follow the pledge."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why countries compete to pay ESA more.", "prompt": "What's the reason?", "options": ["The money returns as work at home", "ESA ranks countries by generosity", "Bigger payers get to name rockets"], "correctIndex": 0, "consequences": ["Geo-return brings it home.", "Not a ranking.", "Not a rule."], "explanation": "Contracts flow back roughly in proportion to what a country pays."}, "proReasoning": "Paying in is also an industrial policy.", "commonMistake": "Thinking pledges are pure charity.", "mentalModel": "Money comes home as work."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:434f4d879ad9$ml$]::text[]),
($ml$9e768997-8188-5a63-baf3-cd9b95fbfbb5$ml$::uuid, $ml$spacetech$ml$, 20, 2, $ml${"id": "spacetech-d20-c2", "title": "The program that skips geo-return", "lessonTitle": "Every euro comes home", "slot": 2, "type": "connect", "brief": {"headline": "Day 19 showed ESA buying launches as a customer. Day 20 showed geo-return, which critics call a brake on launch. ESA's Launcher Challenge skips it.", "kicker": "Connect day 19 and day 20: speed can mean dropping fair shares.", "fullText": "On day 19 you saw ESA spend its budget as a customer through contracts with companies.\n\nOn day 20 you saw geo-return aim for a ratio of 1, with real ratios between 0.9 and 0.95 over five years. Mario Draghi's report for the EU called it a major obstacle for launch, and ESA's new Launcher Challenge does not use it. Winners there are picked on merit, not by who paid.", "sources": [{"url": "https://www.esa.int/About_Us/Business_with_ESA/Business_Opportunities/ESA_an_intergovernmental_customer", "label": "ESA, an intergovernmental customer"}, {"url": "https://europeanspaceflight.com/esa-director-general-reaffirms-geo-return-policy-as-fundamental/", "label": "European Spaceflight, geo-return policy reaffirmed"}]}, "evidence": {"kind": "faceOff", "prompt": "Which program picks companies on merit rather than funding shares?", "left": {"name": "The Launcher Challenge", "note": "Skips geo-return"}, "right": {"name": "A standard ESA program", "note": "Work follows who paid"}, "correctIndex": 0, "explanation": "The Launcher Challenge drops geo-return to move faster and pick on merit."}, "numbers": {"kind": "numberSense", "prompt": "With a return ratio of 0.9, a country paying 100 million euros gets about how much work, in millions?", "min": 0, "max": 150, "value": 90, "unit": "M", "explanation": "A ratio of 0.9 means about 90 million euros of contracts."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked why ESA skipped geo-return for launchers.", "prompt": "What's your answer?", "options": ["To give all work to one country", "To pick the strongest rockets faster", "Because geo-return became illegal"], "correctIndex": 1, "consequences": ["Not the intent.", "Merit and speed were the goals.", "It is still ESA policy."], "explanation": "Critics said geo-return slowed launch. Dropping it lets ESA pick on merit."}, "proReasoning": "Strong answers explain the trade-off, not just the rule.", "commonMistake": "Thinking geo-return was abolished.", "mentalModel": "Merit over shares."}, "invest": {"call": {"kind": "theCall", "situation": "A launcher wins in a program without geo-return.", "prompt": "What does that tell you?", "options": ["Its country paid the most into ESA", "Nothing about its rocket or team", "It won on merit, not on its country"], "correctIndex": 2, "consequences": ["Shares did not decide it.", "It says a lot.", "No funding shares applied."], "explanation": "Without geo-return, a win reflects the company, not its country's pledge."}, "proReasoning": "Investors note how a contract was awarded.", "commonMistake": "Treating every ESA win the same.", "mentalModel": "A merit win."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup is in a country that pays little into ESA.", "prompt": "Which ESA program suits you?", "options": ["One that picks on merit, not shares", "One where work follows pledges", "None, small countries cannot win"], "correctIndex": 0, "consequences": ["Your country share will not limit you.", "Your small share caps your work.", "Merit programs exist."], "explanation": "Programs without geo-return let strong firms from small payers compete."}, "proReasoning": "Founders target programs where their country size does not cap them.", "commonMistake": "Assuming small countries never win.", "mentalModel": "Compete on merit."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what geo-return is in one line.", "prompt": "What's the answer?", "options": ["Satellites return to their home country", "Work goes back where the money came from", "ESA returns unused money each year"], "correctIndex": 1, "consequences": ["Not about satellites.", "That is the rule.", "Not what it means."], "explanation": "Geo-return sends contracts back to each country in proportion to what it pays."}, "proReasoning": "It rewards paying in, but can slow programs.", "commonMistake": "Confusing it with refunds.", "mentalModel": "Work follows money."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:47f3c2ef3c6f$ml$]::text[]),
($ml$340e0a07-0120-57be-9551-bfdd44d12dc3$ml$::uuid, $ml$spacetech$ml$, 20, 3, $ml${"id": "spacetech-d20-c3", "title": "Make the case for a bigger pledge", "lessonTitle": "Every euro comes home", "slot": 3, "type": "decide", "brief": {"headline": "You advise a small ESA member's space office. In November 2025, members pledged a record 22.07 billion euros, 32% more than in 2022.", "kicker": "You decide how to argue for paying in more.", "fullText": "Geo-return tracks returns program by program. Each category of program has a minimum return a country must receive, and ratios run between 0.9 and 0.95 over five years.\n\nAfter inflation, the 2025 pledges were 17% above 2022. A country that pays more can expect more ESA work for its own companies.", "sources": [{"url": "https://spacepolicyonline.com/?p=85281", "label": "SpacePolicyOnline, ESA members pledge record funding"}, {"url": "https://www.esa.int/About_Us/Business_with_ESA/Business_Opportunities/ESA_an_intergovernmental_customer", "label": "ESA, an intergovernmental customer"}, {"url": "https://europeanspaceflight.com/esa-director-general-reaffirms-geo-return-policy-as-fundamental/", "label": "European Spaceflight, geo-return policy reaffirmed"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the chain from a bigger pledge to local jobs in order.", "steps": ["The country raises its ESA pledge", "Its share of program funding grows", "Geo-return sends more contracts home", "Local firms win more ESA work"], "explanation": "A larger pledge raises the share of contracts geo-return sends back."}, "numbers": {"kind": "numberSense", "prompt": "22.07 billion euros was 32% more than 2022. About what was the 2022 total, in billions?", "min": 0, "max": 30, "value": 16.7, "unit": "B", "explanation": "22.07 divided by 1.32 is about 16.7 billion euros."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your minister asks what a bigger pledge buys.", "prompt": "What's your answer?", "options": ["A seat on every ESA rocket", "Control over where ESA is based", "More ESA contracts for local firms"], "correctIndex": 2, "consequences": ["Not how pledges work.", "Not on offer.", "Geo-return brings work back."], "explanation": "The return is industrial: contracts for the country's own companies."}, "proReasoning": "Advisers frame pledges as an investment in local industry.", "commonMistake": "Selling a pledge as prestige alone.", "mentalModel": "Pledge buys contracts."}, "invest": {"call": {"kind": "theCall", "situation": "Pledges rose 32% in 2025, or 17% after inflation.", "prompt": "Which figure do you use?", "options": ["17%, real growth after inflation", "32%, since it sounds bigger", "Neither, budgets never matter"], "correctIndex": 0, "consequences": ["Real growth is the honest measure.", "Overstates the increase.", "They drive contracts."], "explanation": "Inflation-adjusted growth shows how much more work the money can really buy."}, "proReasoning": "Investors adjust budget growth for inflation.", "commonMistake": "Using the headline number uncritically.", "mentalModel": "Use real growth."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your country just raised its ESA pledge.", "prompt": "What do you do next?", "options": ["Move to a bigger country", "Bid for the new ESA programs", "Wait for ESA to call you"], "correctIndex": 1, "consequences": ["Your country now funds more.", "Contracts follow the pledge.", "Contracts are bid for."], "explanation": "A bigger national share means more contracts for local firms that bid."}, "proReasoning": "Founders move fast when their country's share grows.", "commonMistake": "Expecting work without bidding.", "mentalModel": "Bid now."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if ESA got more money in 2025.", "prompt": "What's the answer?", "options": ["No, its budget was cut in half", "Only the EU paid more", "Yes, a record 22.07 billion euros"], "correctIndex": 2, "consequences": ["It rose sharply.", "Members pledged the record.", "32% more than 2022."], "explanation": "Member states pledged a record 22.07 billion euros for three years."}, "proReasoning": "Even after inflation, it was a big increase.", "commonMistake": "Assuming European space budgets are shrinking.", "mentalModel": "A record pledge."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:340f302dc7f9$ml$]::text[]),
($ml$b3074845-8459-5764-bbd6-f953974e8f06$ml$::uuid, $ml$spacetech$ml$, 21, 1, $ml${"id": "spacetech-d21-c1", "title": "Two spacesuit makers, then one", "lessonTitle": "Why NASA paid for two Moon landers", "slot": 1, "type": "apply", "brief": {"headline": "In June 2022, NASA picked two companies, Axiom and Collins Aerospace, to make its next spacesuits. In June 2024, Collins quit.", "kicker": "Apply the lesson: a second supplier is a hedge, and hedges get used.", "fullText": "The spacesuit contracts were worth up to $3.5 billion through 2034 if NASA used every option. On June 25, 2024, Collins stopped work, and NASA said no further work would be performed on its task orders.\n\nAxiom kept building its AxEMU suit for astronauts returning to the Moon. Because NASA had picked two companies, losing one did not leave it with no suit at all.", "sources": [{"url": "https://floridamedianow.com/2024/06/collins-aerospace-drops-out-of-space-suit-program-axiom-continues-making-steady-progress", "label": "Florida Media Now, Collins drops out of NASA spacesuit program, Jun 2024"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["NASA picked two spacesuit companies in 2022.", "Collins stopped work on its task orders in 2024.", "Axiom also left, leaving NASA with no suit."], "fakeIndex": 2, "explanation": "Axiom kept building its AxEMU suit for the Moon return."}, "numbers": {"kind": "numberSense", "prompt": "The spacesuit contracts could run from 2022 through 2034. How many years is that?", "min": 0, "max": 20, "value": 12, "unit": "years", "explanation": "2022 to 2034 is 12 years."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join NASA's spacesuit office the week Collins quits.", "prompt": "What is the first thing to secure?", "options": ["A third company by Friday", "That Axiom stays on schedule", "A new logo for the program"], "correctIndex": 1, "consequences": ["Unrealistic in a week.", "Axiom is now the only suit.", "Does not protect the mission."], "explanation": "With one supplier left, its schedule becomes the program's schedule."}, "proReasoning": "Program staff focus on the supplier that remains.", "commonMistake": "Ignoring the risk of the remaining supplier.", "mentalModel": "Protect the survivor."}, "invest": {"call": {"kind": "theCall", "situation": "Axiom is now NASA's only spacesuit maker.", "prompt": "How does its position change?", "options": ["Weaker, NASA wanted two suppliers", "Unchanged, nothing has moved", "Stronger, NASA now depends on it"], "correctIndex": 2, "consequences": ["The rival left, not Axiom.", "The balance shifted.", "Sole supplier holds more cards."], "explanation": "When a rival exits, the remaining supplier gains bargaining power."}, "proReasoning": "Investors watch how exits shift supplier power.", "commonMistake": "Missing that a rival leaving helps the survivor.", "mentalModel": "Sole supplier, more power."}, "build_startup": {"call": {"kind": "theCall", "situation": "You won one of two NASA slots for a new system.", "prompt": "What do you expect?", "options": ["Competition on price and schedule", "A guaranteed long-term monopoly", "No reviews until delivery"], "correctIndex": 0, "consequences": ["Two suppliers keep pressure on.", "NASA picked two for a reason.", "NASA reviews progress."], "explanation": "NASA picks two so it can push both and keep a backup."}, "proReasoning": "Founders treat a dual award as a race, not a prize.", "commonMistake": "Assuming the contract is safe forever.", "mentalModel": "Expect a race."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why NASA hired two spacesuit makers.", "prompt": "What's the reason?", "options": ["To test which suit looks best", "In case one fails or quits", "Each astronaut gets two suits"], "correctIndex": 1, "consequences": ["Looks are not the point.", "That is what happened.", "Not the reason."], "explanation": "A second supplier is a backup. When Collins quit, Axiom kept going."}, "proReasoning": "Buyers pay for two so one can fail.", "commonMistake": "Thinking two suppliers is waste.", "mentalModel": "One can fail."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:077f59bb63af$ml$]::text[]),
($ml$8acf2345-9f90-5049-a9bc-87ccff1ad906$ml$::uuid, $ml$spacetech$ml$, 21, 2, $ml${"id": "spacetech-d21-c2", "title": "The same rule for rockets and landers", "lessonTitle": "Why NASA paid for two Moon landers", "slot": 2, "type": "connect", "brief": {"headline": "Day 15 showed the Space Force splitting 54 launches among three companies. Day 21 showed NASA paying for a second Moon lander. It is the same idea.", "kicker": "Connect day 15 and day 21: buyers keep more than one supplier.", "fullText": "On day 15 you saw national security launches split among SpaceX, ULA and Blue Origin in April 2025, and a policy requiring at least two rockets.\n\nOn day 21 you saw NASA give Blue Origin $3.4 billion in 2023 for a second lander, after SpaceX won the first in 2021. In both cases the buyer pays more up front to avoid depending on one company.", "sources": [{"url": "https://www.satellitetoday.com/launch/2025/04/06/spacex-ula-blue-origin-receive-nssl-contracts-worth-up-to-nearly-14b/", "label": "Via Satellite, NSSL Phase 3 Lane 2 awards"}, {"url": "https://www.everycrsreport.com/files/2026-01-14_IF12900_e1a9a9283349423491e151fac8e59426a6fa6708.html", "label": "Congressional Research Service, National Security Space Launch"}, {"url": "https://spacepolicyonline.com/?p=62197", "label": "SpacePolicyOnline, Blue Origin wins second Moon lander contract"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What do the launch split and the second lander have in common?", "options": ["The buyer always picks the cheapest bid", "The buyer builds the hardware itself", "The buyer avoids depending on one company"], "correctIndex": 2, "explanation": "Both pay for more than one supplier to gain backup and bargaining power."}, "numbers": {"kind": "numberSense", "prompt": "54 launches split among three companies. If shared evenly, how many each?", "min": 0, "max": 54, "value": 18, "unit": "launches", "explanation": "54 divided by 3 is 18. The real split was not even."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks what NASA and the Space Force share as buyers.", "prompt": "What's your answer?", "options": ["Both build their own rockets", "Both buy only from SpaceX", "Both pay to keep a second supplier"], "correctIndex": 2, "consequences": ["They buy from industry.", "They split their buys.", "Redundancy is the pattern."], "explanation": "Both pay more up front so no single company holds all the cards."}, "proReasoning": "Strong answers spot the pattern across buyers.", "commonMistake": "Treating each contract as a one-off.", "mentalModel": "Two suppliers, every time."}, "invest": {"call": {"kind": "theCall", "situation": "A company is the second supplier in two big programs.", "prompt": "What does that tell you?", "options": ["Buyers value it as a backup", "It will soon lose both", "It is the cheapest supplier"], "correctIndex": 0, "consequences": ["Second slots are paid on purpose.", "Buyers keep two by design.", "Price is not why."], "explanation": "Government buyers deliberately keep a second supplier, which supports that company."}, "proReasoning": "Investors see the second slot as a policy-backed position.", "commonMistake": "Dismissing the runner-up as a loser.", "mentalModel": "Backups get paid."}, "build_startup": {"call": {"kind": "theCall", "situation": "You lost a single-supplier contest to a giant.", "prompt": "What is your best path?", "options": ["Sue to cancel the award", "Pitch as the second source", "Exit the market for good"], "correctIndex": 1, "consequences": ["Costly and slow.", "Buyers want a backup.", "Gives up a real opening."], "explanation": "Buyers that fear depending on one company often pay for a second."}, "proReasoning": "Founders pitch the redundancy the buyer wants.", "commonMistake": "Assuming one loss closes the door.", "mentalModel": "Be the backup."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why NASA pays two companies for one job.", "prompt": "What's the reason?", "options": ["Because the law requires it", "To finish the job twice as fast", "So one company cannot hold it hostage"], "correctIndex": 2, "consequences": ["It was NASA's choice.", "Not the reason.", "Competition keeps both honest."], "explanation": "With two suppliers, NASA can push both on price and schedule."}, "proReasoning": "Buyers pay for choice.", "commonMistake": "Thinking two suppliers is wasteful.", "mentalModel": "Choice is power."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f686653a271d$ml$]::text[]),
($ml$e437c5a4-2fe6-5c1a-9e9e-48eb1734e5d1$ml$::uuid, $ml$spacetech$ml$, 21, 3, $ml${"id": "spacetech-d21-c3", "title": "Is a second supplier worth $3.4 billion?", "lessonTitle": "Why NASA paid for two Moon landers", "slot": 3, "type": "decide", "brief": {"headline": "You advise NASA on its Moon plans. SpaceX holds the only crewed lander contract, won in 2021 with a $2.9 billion bid.", "kicker": "You decide what a second supplier buys.", "fullText": "A second lander would cost billions more up front. Blue Origin's eventual award was $3.4 billion, with a total effort of about $7 billion including its own money.\n\nWith one supplier, the supplier holds the cards. With two, NASA can push both on price and schedule, and still land if one design runs into trouble.", "sources": [{"url": "https://spacepolicyonline.com/?p=62197", "label": "SpacePolicyOnline, Blue Origin wins second Moon lander contract"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each point argue for paying a second lander supplier?", "buckets": ["For", "Against"], "items": [{"text": "A backup if one design fails", "bucket": 0}, {"text": "Pressure on price and schedule", "bucket": 0}, {"text": "Billions more spent up front", "bucket": 1}, {"text": "Two teams to oversee at once", "bucket": 1}, {"text": "Less dependence on one company", "bucket": 0}], "explanation": "Redundancy and bargaining power cost money, which NASA judged worth paying."}, "numbers": {"kind": "numberSense", "prompt": "Blue Origin's lander effort was about $7 billion; NASA paid $3.4 billion. How much came from elsewhere, in billions?", "min": 0, "max": 8, "value": 3.6, "unit": "B", "explanation": "$7 billion minus $3.4 billion is about $3.6 billion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks for the strongest case for a second lander.", "prompt": "Which do you lead with?", "options": ["Bargaining power and a backup", "It will be cheaper than the first", "Blue Origin asked for the job first"], "correctIndex": 0, "consequences": ["That is the real payoff.", "It cost more, not less.", "Not a reason for NASA."], "explanation": "A second lander buys bargaining power and redundancy over many missions."}, "proReasoning": "Advisers make the case on long-term bargaining power.", "commonMistake": "Arguing on price when it costs more.", "mentalModel": "Lead with bargaining power."}, "invest": {"call": {"kind": "theCall", "situation": "A supplier co-funds about half of a NASA program.", "prompt": "What do you weigh?", "options": ["Nothing, NASA pays for everything", "Its own cash at risk against the payoff", "Only the NASA money it receives"], "correctIndex": 1, "consequences": ["Not true here.", "Co-funding means real exposure.", "Ignores its own spending."], "explanation": "When a company adds its own money, it shares the risk and the upside."}, "proReasoning": "Investors check how much of their own cash a contractor spends.", "commonMistake": "Treating a contract as pure revenue.", "mentalModel": "Count its own cash."}, "build_startup": {"call": {"kind": "theCall", "situation": "NASA offers a second-source contract if you co-fund it.", "prompt": "How do you decide?", "options": ["Always, any NASA deal is good", "Never, co-funding is a trap", "Only if later missions repay you"], "correctIndex": 2, "consequences": ["Some deals lose money.", "It can pay off.", "Repeat missions pay back."], "explanation": "Co-funding makes sense when the follow-on missions repay the investment."}, "proReasoning": "Founders model the full program, not just the first award.", "commonMistake": "Signing without modeling the payback.", "mentalModel": "Model the payback."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if NASA wasted money on a second lander.", "prompt": "What's a fair answer?", "options": ["It paid for a backup and choice", "Yes, one lander does the job fine", "No, the second lander was free"], "correctIndex": 0, "consequences": ["That was the point.", "Ignores the risk of one.", "It cost $3.4 billion."], "explanation": "NASA paid more up front to avoid depending on one company."}, "proReasoning": "Redundancy has a price, and NASA chose to pay it.", "commonMistake": "Judging only on up-front cost.", "mentalModel": "It bought a backup."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:137f7b104967$ml$]::text[]),
($ml$9f49e8f5-e71c-5b7d-8d34-3f094c59b7a6$ml$::uuid, $ml$spacetech$ml$, 22, 1, $ml${"id": "spacetech-d22-c1", "title": "A 24% cut, proposed", "lessonTitle": "NASA's slice of the budget", "slot": 1, "type": "apply", "brief": {"headline": "The White House's 2026 budget request asked for $18.8 billion for NASA, down from $24.8 billion, a cut of about 24%. Science would fall 47%.", "kicker": "Apply the lesson: a budget shows what a government ranks first.", "fullText": "NASA's science budget would drop to $3.9 billion under the request, and its workforce would shrink from 17,391 to 11,853 people, nearly a third.\n\nThe request was a statement of priority. Congress later rejected the deep cuts and passed $24.4 billion for NASA in fiscal 2026.", "sources": [{"url": "https://www.space.com/space-exploration/trumps-2026-budget-would-slash-nasa-funding-by-24-percent-and-its-workforce-by-nearly-one-third", "label": "Space.com, 2026 budget request would cut NASA by 24%"}, {"url": "https://space.com/space-exploration/in-rejection-of-trumps-deep-cuts-congress-passes-usd24-4-billion-budget-for-nasa", "label": "Space.com, NASA fiscal 2026 budget"}]}, "evidence": {"kind": "multipleChoice", "prompt": "The request cut NASA 24% but science 47%. What does that show?", "options": ["Science ranked below the rest of NASA", "Science costs less to run every year", "NASA asked for its own cuts"], "correctIndex": 0, "explanation": "A deeper cut to one area shows it ranked lower in the request."}, "numbers": {"kind": "numberSense", "prompt": "The workforce would fall from 17,391 to 11,853. About how many jobs is that, in thousands?", "min": 0, "max": 10, "value": 5.5, "unit": "K", "explanation": "17,391 minus 11,853 is about 5,540 jobs."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You have a NASA science job offer the week the request comes out.", "prompt": "How do you read it?", "options": ["Turn it down, NASA is closing", "Ignore budgets, they never matter", "A request, not law; watch Congress"], "correctIndex": 2, "consequences": ["Overreacts to a request.", "Budgets shape jobs.", "Congress set the final number."], "explanation": "The request signals priority, but Congress decides. It passed $24.4 billion."}, "proReasoning": "Candidates track both the request and what Congress passes.", "commonMistake": "Treating a request as final.", "mentalModel": "Watch Congress."}, "invest": {"call": {"kind": "theCall", "situation": "A company earns most revenue from NASA science missions.", "prompt": "What do you flag?", "options": ["Science took the deepest proposed cut", "NASA will raise science spending", "Budgets do not affect suppliers"], "correctIndex": 0, "consequences": ["Exposure to the most cut area.", "The request pointed down.", "They shape contracts."], "explanation": "Suppliers to the most cut area face the most budget risk."}, "proReasoning": "Investors map revenue to budget lines.", "commonMistake": "Ignoring which line pays the company.", "mentalModel": "Map revenue to lines."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells instruments for NASA science.", "prompt": "How do you respond to the request?", "options": ["Wait and change nothing", "Add customers beyond NASA science", "Hire fast to win the remaining work"], "correctIndex": 1, "consequences": ["Leaves you exposed.", "Less dependence on one line.", "Risky if cuts pass."], "explanation": "Diversifying customers protects you if one budget line shrinks."}, "proReasoning": "Founders spread risk across buyers.", "commonMistake": "Betting everything on one budget line.", "mentalModel": "Diversify buyers."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend heard NASA's budget was cut by a quarter.", "prompt": "What's the full story?", "options": ["It was cut and NASA closed centers", "NASA got double the money", "Proposed, then Congress rejected it"], "correctIndex": 2, "consequences": ["The cut did not pass.", "Not true.", "Congress passed $24.4 billion."], "explanation": "The White House proposed $18.8 billion; Congress passed $24.4 billion."}, "proReasoning": "A request is the opening bid.", "commonMistake": "Confusing a request with a budget.", "mentalModel": "Proposed, not passed."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:92ab638dbbe6$ml$]::text[]),
($ml$6d1361ad-0023-55a4-bd4d-bcad76762efd$ml$::uuid, $ml$spacetech$ml$, 22, 2, $ml${"id": "spacetech-d22-c2", "title": "Bigger than ESA, smaller than it was", "lessonTitle": "NASA's slice of the budget", "slot": 2, "type": "connect", "brief": {"headline": "Day 19 showed NASA's budget is about three times ESA's. Day 22 showed NASA's slice of federal spending fell ninefold from 1966 to 2019.", "kicker": "Connect day 19 and day 22: big in dollars, small as a share.", "fullText": "On day 19 you saw NASA get $24.4 billion for fiscal 2026, against ESA's 7.7 billion euros in 2025.\n\nOn day 22 you saw NASA's share fall from 4.41% of the federal budget in 1966 to 0.49% in 2019, when it had $21.5 billion. A large dollar total can still be a small priority.", "sources": [{"url": "https://space.com/space-exploration/in-rejection-of-trumps-deep-cuts-congress-passes-usd24-4-billion-budget-for-nasa", "label": "Space.com, NASA fiscal 2026 budget"}, {"url": "https://aviationweek.com/space/budget-policy-regulation/esa-council-oks-initial-eu77b-2025-budget-readies-launcher-challenge", "label": "Aviation Week, ESA 2025 budget of 7.7 billion euros"}, {"url": "https://www.statista.com/chart/amp/17504/nasas-budget-share-of-the-us-federal-budget", "label": "Statista, NASA's share of the federal budget"}]}, "evidence": {"kind": "faceOff", "prompt": "Which figure shows how much a government prioritizes space?", "left": {"name": "The dollar total", "note": "$21.5 billion in 2019"}, "right": {"name": "The share of spending", "note": "0.49% in 2019"}, "correctIndex": 1, "explanation": "A share compares space with everything else the government funds."}, "numbers": {"kind": "numberSense", "prompt": "NASA had $21.5 billion in fiscal 2019 and $24.4 billion in fiscal 2026. How much more, in billions?", "min": 0, "max": 10, "value": 2.9, "unit": "B", "explanation": "$24.4 billion minus $21.5 billion is $2.9 billion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A colleague says NASA is a top US priority because it is the biggest agency.", "prompt": "How do you reply?", "options": ["Check its share of spending", "Agree, the dollars say it all", "Compare it with ESA only"], "correctIndex": 0, "consequences": ["Share shows priority.", "Dollars miss the context.", "Misses the home budget."], "explanation": "NASA is large in dollars but under half a cent of each federal dollar."}, "proReasoning": "Analysts compare budgets with total spending.", "commonMistake": "Reading size as priority.", "mentalModel": "Check the share."}, "invest": {"call": {"kind": "theCall", "situation": "NASA's dollar budget rose from 2019 to 2026.", "prompt": "What else do you check?", "options": ["Whether ESA got the same rise", "Whether its share rose too", "Only whether the number went up"], "correctIndex": 1, "consequences": ["Not the key comparison.", "Rising dollars can hide a falling share.", "Ignores inflation and context."], "explanation": "A rising total can still mean a falling priority."}, "proReasoning": "Investors read budgets against the whole.", "commonMistake": "Celebrating a raw dollar increase.", "mentalModel": "Check share and total."}, "build_startup": {"call": {"kind": "theCall", "situation": "You pitch investors that NASA money is growing.", "prompt": "What do you add?", "options": ["NASA spends more than the Pentagon", "Government money never shrinks", "Its share has been under 1% for years"], "correctIndex": 2, "consequences": ["False.", "Budgets shrink often.", "Honest context earns trust."], "explanation": "Investors will check the share. Show you know it."}, "proReasoning": "Founders show the full budget picture.", "commonMistake": "Overselling the size of the market.", "mentalModel": "Show the share."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if NASA gets a lot of money.", "prompt": "What's a fair answer?", "options": ["Big in dollars, small as a share", "Most of the federal budget now", "Almost nothing in dollars"], "correctIndex": 0, "consequences": ["$24.4 billion, under 1%.", "Under half a cent per dollar.", "Still billions."], "explanation": "NASA gets billions, yet a far smaller share than at Apollo's height."}, "proReasoning": "Shares tell you about priority.", "commonMistake": "Judging only by the dollar figure.", "mentalModel": "Big dollars, small share."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c0443649f7b4$ml$]::text[]),
($ml$51866bca-6436-501e-81ca-be5e4f6a2fe9$ml$::uuid, $ml$spacetech$ml$, 22, 3, $ml${"id": "spacetech-d22-c3", "title": "Read the budget like an analyst", "lessonTitle": "NASA's slice of the budget", "slot": 3, "type": "decide", "brief": {"headline": "You're briefing a senator's staff. In 1966, NASA got 4.41% of the federal budget. In 2019 it got 0.49%.", "kicker": "You decide how to show what space really gets.", "fullText": "At Apollo's height, about one federal dollar in 23 went to NASA. The share peaked in 1966, three years before Apollo 11, driven by one national goal.\n\nIn fiscal 2019, NASA's $21.5 billion was less than half a cent of each federal dollar. Congress passed $24.4 billion for fiscal 2026.", "sources": [{"url": "https://www.statista.com/chart/amp/17504/nasas-budget-share-of-the-us-federal-budget", "label": "Statista, NASA's share of the federal budget"}, {"url": "https://space.com/space-exploration/in-rejection-of-trumps-deep-cuts-congress-passes-usd24-4-billion-budget-for-nasa", "label": "Space.com, NASA fiscal 2026 budget"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the story of NASA's budget share in order.", "steps": ["A national goal: land on the Moon", "NASA gets 4.41% of the budget in 1966", "Apollo 11 lands in 1969", "The share falls to 0.49% by 2019"], "explanation": "The share peaked with the Moon goal, then fell for decades."}, "numbers": {"kind": "numberSense", "prompt": "NASA got 0.49% of the federal budget in 2019. About how many cents of each federal dollar is that?", "min": 0, "max": 2, "value": 0.5, "unit": "cents", "explanation": "0.49% of a dollar is about half a cent."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Staff want one slide on NASA funding.", "prompt": "What does it show?", "options": ["A photo of the Moon landing", "NASA's share of spending since 1966", "NASA's dollar total for one year"], "correctIndex": 1, "consequences": ["Not data.", "Shows priority over time.", "Misses the trend."], "explanation": "A share over time shows how priority rose and fell."}, "proReasoning": "Good briefers chart share, not just dollars.", "commonMistake": "Showing one year's dollars without context.", "mentalModel": "Chart the share."}, "invest": {"call": {"kind": "theCall", "situation": "Someone says space budgets will return to Apollo levels.", "prompt": "How do you test that?", "options": ["Assume budgets always go up", "Look only at this year's budget", "Ask what national goal would drive it"], "correctIndex": 2, "consequences": ["They often fall.", "Misses the history.", "Apollo had one big goal."], "explanation": "The 1966 peak came with one national goal. A return would need one too."}, "proReasoning": "Investors look for the driver behind budget swings.", "commonMistake": "Expecting growth with no reason.", "mentalModel": "Find the driver."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup depends on NASA growth.", "prompt": "What do you plan for?", "options": ["A share that stays under 1%", "A return to 4% of the budget", "NASA doubling next year"], "correctIndex": 0, "consequences": ["Matches recent history.", "No sign of that.", "Unrealistic."], "explanation": "Plan for the budget history shows, not the one you hope for."}, "proReasoning": "Founders plan for flat government budgets.", "commonMistake": "Planning on an Apollo-style boom.", "mentalModel": "Plan for flat."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks when NASA got the biggest share of the budget.", "prompt": "What's the answer?", "options": ["1969, the year of the landing", "1966, three years before Apollo 11", "2019, the most dollars ever"], "correctIndex": 1, "consequences": ["Close, but the peak was 1966.", "4.41% that year.", "0.49% that year."], "explanation": "The share peaked in 1966 as NASA built toward the Moon landing."}, "proReasoning": "Spending peaks before the result.", "commonMistake": "Assuming the peak was the landing year.", "mentalModel": "1966."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:245fe06b157a$ml$]::text[]),
($ml$852803ed-de43-5811-821c-3c3484f1aef8$ml$::uuid, $ml$spacetech$ml$, 23, 1, $ml${"id": "spacetech-d23-c1", "title": "NASA buys Moon dirt for $1", "lessonTitle": "No nation owns the Moon", "slot": 1, "type": "apply", "brief": {"headline": "In December 2020, NASA agreed to buy lunar soil from four companies for between $1 and $15,000. Lunar Outpost bid $1.", "kicker": "Apply the lesson: you can own what you take, not the Moon.", "fullText": "Masten Space Systems won $15,000, ispace Europe and ispace Japan $5,000 each, and Lunar Outpost $1. Each would collect a small sample, and ownership would transfer to NASA on the Moon, making it NASA's sole property.\n\nNASA said the goal was to set a precedent that private companies can extract and sell space resources. It said this was consistent with the Outer Space Treaty, which bars claiming the Moon itself.", "sources": [{"url": "https://www.space.com/nasa-will-buy-moon-dirt-masten-ispace-lunar-outpost", "label": "Space.com, NASA will buy Moon dirt from four companies, Dec 2020"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the payments for a sample in order.", "steps": ["10% when the contract is signed", "10% when the mission launches", "The company collects the soil", "80% when ownership passes to NASA"], "explanation": "Most of the money is paid only when ownership of the sample transfers."}, "numbers": {"kind": "numberSense", "prompt": "Masten's award was $15,000, with 80% paid on transfer. About how much is that, in thousands?", "min": 0, "max": 20, "value": 12, "unit": "K", "explanation": "80% of $15,000 is $12,000."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks why NASA paid $1 for Moon soil.", "prompt": "What's your answer?", "options": ["To set a precedent for selling it", "Because Moon soil is worthless", "To test the company's rockets"], "correctIndex": 0, "consequences": ["The sale was the point.", "Price was symbolic.", "Not the goal."], "explanation": "The price was tiny because the point was proving companies can sell what they extract."}, "proReasoning": "Policy analysts see the precedent behind the price.", "commonMistake": "Judging the deal by its dollar value.", "mentalModel": "It set a precedent."}, "invest": {"call": {"kind": "theCall", "situation": "A lunar mining startup claims it will own a Moon crater.", "prompt": "How do you react?", "options": ["Neutral, law does not apply", "Doubtful, the treaty bars land claims", "Excited, first to land owns it all"], "correctIndex": 1, "consequences": ["The treaty applies.", "Only extracted resources can be owned.", "Landing first gives no title."], "explanation": "The Outer Space Treaty bars claims by sovereignty, use or occupation."}, "proReasoning": "Investors check what the law lets a company own.", "commonMistake": "Believing a territorial claim is real.", "mentalModel": "No land claims."}, "build_startup": {"call": {"kind": "theCall", "situation": "You plan to sell resources gathered on the Moon.", "prompt": "How do you frame the business?", "options": ["You claim the site you land on", "You wait until space law is gone", "Sell what you extract, not land"], "correctIndex": 2, "consequences": ["The treaty bars it.", "The treaty stands.", "Matches NASA's precedent."], "explanation": "NASA's purchase shows a legal path: extract and sell, without claiming land."}, "proReasoning": "Founders build within the treaty's limits.", "commonMistake": "Basing the business on a land claim.", "mentalModel": "Sell, do not claim."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if a company can own Moon rocks.", "prompt": "What's the answer?", "options": ["It can own what it digs up, not the Moon", "No, nothing from space can be owned", "Yes, and the land around them too"], "correctIndex": 0, "consequences": ["NASA bought them.", "NASA bought some.", "No land claims allowed."], "explanation": "Extracted material can be sold, while the Moon itself cannot be claimed."}, "proReasoning": "Using resources is allowed, owning territory is not.", "commonMistake": "Mixing up resources and land.", "mentalModel": "Rocks yes, land no."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7044ef1d373d$ml$]::text[]),
($ml$d06203d2-399f-5601-899c-1dca9940eabc$ml$::uuid, $ml$spacetech$ml$, 23, 2, $ml${"id": "spacetech-d23-c2", "title": "300,000 moves, one country answers", "lessonTitle": "No nation owns the Moon", "slot": 2, "type": "connect", "brief": {"headline": "Day 12 showed Starlink making about 300,000 collision-avoidance moves in 2025. Day 23 showed why it reports them: countries answer for their companies.", "kicker": "Connect day 12 and day 23: a company flies, its country is responsible.", "fullText": "On day 12 you saw SpaceX tell the FCC its satellites dodged roughly 300,000 possible collisions in 2025.\n\nOn day 23 you saw Article VI of the Outer Space Treaty make each country responsible for its companies in space. That is why private missions need national authorization and supervision, and why a US company reports to a US regulator.", "sources": [{"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}, {"url": "https://www.unoosa.org/documents/pdf/spacelaw/activities/2020/SLC2020Presentations/SLC2020PDFPresentations/A._Newman_-_8_Dec_2020_-_Fundamentals_of_Space_Law_.pdf", "label": "UNOOSA, fundamentals of space law"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why does SpaceX report its collision moves to the FCC?", "options": ["The US answers for its companies in space", "The FCC owns the Starlink satellites", "The UN requires every company to report"], "correctIndex": 0, "explanation": "Under Article VI, countries authorize and supervise their companies in space."}, "numbers": {"kind": "numberSense", "prompt": "About 300,000 moves in one year is about how many a day?", "min": 0, "max": 2000, "value": 820, "unit": "moves", "explanation": "300,000 divided by 365 is about 820 a day."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You start at a satellite operator.", "prompt": "Why does your company report to a national regulator?", "options": ["It is optional good manners", "The country answers for what you do", "The regulator owns your satellites"], "correctIndex": 1, "consequences": ["It is required.", "Article VI makes it so.", "You own them."], "explanation": "Countries are responsible for their companies, so they supervise them."}, "proReasoning": "Staff know why the regulator is in the loop.", "commonMistake": "Treating reporting as optional.", "mentalModel": "The country answers."}, "invest": {"call": {"kind": "theCall", "situation": "An operator flies thousands of satellites.", "prompt": "Which risk do you watch?", "options": ["The Moon being claimed by others", "No regulator watching at all", "Its own country tightening rules"], "correctIndex": 2, "consequences": ["Unrelated to the operator.", "Regulators do watch.", "Its country supervises it."], "explanation": "The country that answers for an operator can change the rules it flies under."}, "proReasoning": "Investors watch the home regulator.", "commonMistake": "Assuming space is unregulated.", "mentalModel": "Watch the home regulator."}, "build_startup": {"call": {"kind": "theCall", "situation": "You plan a constellation from a small country.", "prompt": "What do you check early?", "options": ["How that country licenses space", "Whether any rules apply at all", "Which country has the most sun"], "correctIndex": 0, "consequences": ["Your country answers for you.", "The treaty applies.", "Not relevant."], "explanation": "Your home country must authorize and supervise you under the treaty."}, "proReasoning": "Founders pick a home with a clear licensing path.", "commonMistake": "Assuming a small country means no rules.", "mentalModel": "Check the licensing."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks who is in charge of private satellites.", "prompt": "What's the answer?", "options": ["The United Nations directly", "The company's home country", "Nobody, space is lawless"], "correctIndex": 1, "consequences": ["Countries supervise.", "Article VI.", "Not true."], "explanation": "Each country answers for its companies, so it licenses and supervises them."}, "proReasoning": "Private space runs on national permission.", "commonMistake": "Thinking space has no rules.", "mentalModel": "The home country."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c143545262a8$ml$]::text[]),
($ml$25edda8c-94ec-54f4-90a0-a43101507eee$ml$::uuid, $ml$spacetech$ml$, 23, 3, $ml${"id": "spacetech-d23-c3", "title": "Plan a lunar resource company", "lessonTitle": "No nation owns the Moon", "slot": 3, "type": "decide", "brief": {"headline": "You're advising a startup that wants to use water ice on the Moon. Under the 1967 Outer Space Treaty, no country can claim the Moon.", "kicker": "You decide what the company can and cannot promise.", "fullText": "Article II bars claims by sovereignty, use, occupation or any other means. Article VI makes each country responsible for its companies, so the startup needs national authorization.\n\nThe US-led Artemis Accords add practical principles. They started with eight nations in 2020 and had 76 by September 2026.", "sources": [{"url": "https://www.unoosa.org/documents/pdf/spacelaw/activities/2020/SLC2020Presentations/SLC2020PDFPresentations/A._Newman_-_8_Dec_2020_-_Fundamentals_of_Space_Law_.pdf", "label": "UNOOSA, fundamentals of space law"}, {"url": "https://www.nasa.gov/news-release/nasa-celebrates-as-artemis-accords-surpasses-75-signatories/", "label": "NASA, Artemis Accords pass 75 signatories"}]}, "evidence": {"kind": "sortSignal", "prompt": "Can the startup do this under the treaty?", "buckets": ["Allowed", "Not allowed"], "items": [{"text": "Explore the lunar surface", "bucket": 0}, {"text": "Use resources it gathers", "bucket": 0}, {"text": "Claim a crater as its land", "bucket": 1}, {"text": "Fly without national approval", "bucket": 1}, {"text": "Own land by occupying it", "bucket": 1}], "explanation": "Explore and use are allowed. Claiming land or flying unsupervised is not."}, "numbers": {"kind": "numberSense", "prompt": "The Artemis Accords grew from 8 nations in 2020 to 76 by September 2026. By how many?", "min": 0, "max": 100, "value": 68, "unit": "nations", "explanation": "76 minus 8 is 68 more nations."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "The founder wants to promise investors land rights.", "prompt": "What do you advise?", "options": ["Promise land, nobody will check", "Promise nothing at all", "Promise use of resources, not land"], "correctIndex": 2, "consequences": ["Land claims are barred.", "Too cautious; use is allowed.", "Matches the treaty."], "explanation": "The treaty bars land claims but allows exploration and use."}, "proReasoning": "Advisers keep promises within the law.", "commonMistake": "Letting a founder overpromise rights.", "mentalModel": "Use, not land."}, "invest": {"call": {"kind": "theCall", "situation": "The startup is based in a country that signed the Artemis Accords.", "prompt": "Why might that help?", "options": ["It works within shared rules", "It can now claim Moon land", "It no longer needs approval"], "correctIndex": 0, "consequences": ["76 nations share the principles.", "The treaty still bars that.", "Article VI still applies."], "explanation": "The Accords give a common framework, but do not override the treaty."}, "proReasoning": "Investors value clear rules.", "commonMistake": "Thinking the Accords allow claims.", "mentalModel": "Shared rules help."}, "build_startup": {"call": {"kind": "theCall", "situation": "You pick a home country for your lunar company.", "prompt": "What matters most?", "options": ["The lowest office rent", "A clear path to national approval", "A country that ignores the treaty"], "correctIndex": 1, "consequences": ["Minor next to licensing.", "You need its authorization.", "Risky and isolating."], "explanation": "Your home country must authorize and supervise your mission."}, "proReasoning": "Founders pick homes with workable space law.", "commonMistake": "Choosing a home with no licensing path.", "mentalModel": "Pick a clear path."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if the first company on the Moon gets to keep it.", "prompt": "What's the answer?", "options": ["Yes, landing first means owning it", "Only if it plants a flag", "No, nobody can claim the Moon"], "correctIndex": 2, "consequences": ["Occupation gives no title.", "Flags do not count.", "Article II."], "explanation": "The treaty bars claims by sovereignty, use or occupation."}, "proReasoning": "You can explore and use, not own.", "commonMistake": "Thinking first-come, first-owned applies.", "mentalModel": "Nobody owns it."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3fd000f645a7$ml$]::text[]),
($ml$121c24bd-6a8b-5e23-8ff1-e64b92b2bcc1$ml$::uuid, $ml$spacetech$ml$, 24, 1, $ml${"id": "spacetech-d24-c1", "title": "A finished rover left on the ground", "lessonTitle": "The Mars rocks that may never come home", "slot": 1, "type": "apply", "brief": {"headline": "In July 2024, NASA announced it intended to cancel VIPER, a fully assembled Moon rover, after spending about $450 million on it.", "kicker": "Apply the lesson: a mission can stop even after it is built.", "fullText": "That was about 74% of the planned $505 million cost. Launch delays to late 2025 would have added $104 million, and NASA said cancelling would save $84 million over two years.\n\nThe Planetary Society later noted that in September 2025 NASA contracted Blue Origin to deliver VIPER to the Moon in 2027. A built mission was nearly lost to cost growth.", "sources": [{"url": "https://www.planetary.org/articles/nasa-cancels-viper", "label": "The Planetary Society, NASA cancels VIPER"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["VIPER was fully assembled when NASA moved to cancel it.", "NASA had spent about $450 million on it.", "Cancelling would have cost NASA $104 million more."], "fakeIndex": 2, "explanation": "The $104 million was the cost of delay. Cancelling was said to save $84 million."}, "numbers": {"kind": "numberSense", "prompt": "VIPER was planned at $505 million and about $450 million was spent. About how much was left, in millions?", "min": 0, "max": 150, "value": 55, "unit": "M", "explanation": "$505 million minus $450 million is about $55 million."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work on a mission whose launch keeps slipping.", "prompt": "Which risk do you take seriously?", "options": ["Only the weather on launch day", "Cancellation if delays raise costs", "None, built hardware always flies"], "correctIndex": 1, "consequences": ["Cost is the bigger risk.", "VIPER was built and nearly lost.", "VIPER shows otherwise."], "explanation": "Delays add costs, and added costs can end a finished mission."}, "proReasoning": "Mission staff watch cost growth closely.", "commonMistake": "Assuming built hardware is safe.", "mentalModel": "Delays raise risk."}, "invest": {"call": {"kind": "theCall", "situation": "A supplier's NASA mission is nearly built but delayed.", "prompt": "How do you value it?", "options": ["Treat it as certain revenue now", "Ignore it until launch", "Watch for cost growth and cuts"], "correctIndex": 2, "consequences": ["Not certain.", "Risk builds before launch.", "VIPER nearly died late."], "explanation": "Even nearly finished missions can be cancelled when costs rise."}, "proReasoning": "Investors watch cost overruns on late-stage programs.", "commonMistake": "Counting late-stage work as safe.", "mentalModel": "Watch cost growth."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your company could fly a cancelled NASA payload.", "prompt": "What is the opening?", "options": ["Offer a cheaper ride to fly it", "Ask NASA to pay for a new rover", "Wait for NASA to call you"], "correctIndex": 0, "consequences": ["Blue Origin got VIPER's ride.", "NASA wants to save money.", "Openings go to bidders."], "explanation": "A cheaper delivery plan can rescue a mission cut for cost."}, "proReasoning": "Founders look for ways to save stranded missions.", "commonMistake": "Missing the opening in a cancellation.", "mentalModel": "Offer the cheaper ride."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why NASA would cancel a finished rover.", "prompt": "What's the reason?", "options": ["The Moon was already explored", "Delays would have added more cost", "The rover did not work"], "correctIndex": 1, "consequences": ["Not the reason.", "$104 million more for delays.", "It was fully built."], "explanation": "Delays would have added $104 million, so NASA moved to cancel."}, "proReasoning": "Costs can sink a mission at any stage.", "commonMistake": "Thinking only broken missions get cut.", "mentalModel": "Cost, not failure."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e47b57c282f2$ml$]::text[]),
($ml$2a5a158f-a8d7-5bd0-aab5-0640c0de3964$ml$::uuid, $ml$spacetech$ml$, 24, 2, $ml${"id": "spacetech-d24-c2", "title": "A billion a year in a small slice", "lessonTitle": "The Mars rocks that may never come home", "slot": 2, "type": "connect", "brief": {"headline": "Day 22 showed NASA's share of federal spending shrinking. Day 24 showed Mars Sample Return needing $850 million to $1 billion a year while it was built.", "kicker": "Connect day 22 and day 24: a tight budget cannot hold a giant mission.", "fullText": "On day 22 you saw NASA fall to under half a cent of each federal dollar, with $24.4 billion for fiscal 2026.\n\nOn day 24 you saw Mars Sample Return's estimate grow to as much as $11 billion, needing up to $1 billion a year. Inside a budget that size, one mission that big squeezes everything else, and in January 2026 Congress stopped supporting it.", "sources": [{"url": "https://www.statista.com/chart/amp/17504/nasas-budget-share-of-the-us-federal-budget", "label": "Statista, NASA's share of the federal budget"}, {"url": "https://space.com/space-exploration/in-rejection-of-trumps-deep-cuts-congress-passes-usd24-4-billion-budget-for-nasa", "label": "Space.com, NASA fiscal 2026 budget"}, {"url": "https://spaceflightnow.com/2024/04/16/nasa-requests-proposals-to-reduce-cost-timeline-of-mars-sample-return-mission/", "label": "Spaceflight Now, NASA seeks a cheaper Mars Sample Return"}, {"url": "https://www.livescience.com/space/mars/nasas-mars-sample-return-is-dead-leaving-china-to-retrieve-signs-of-life-from-the-red-planet", "label": "Live Science, Mars Sample Return loses support"}]}, "evidence": {"kind": "faceOff", "prompt": "Which mission is harder to protect inside a flat NASA budget?", "left": {"name": "A mission needing $1B a year", "note": "For about a decade"}, "right": {"name": "A mission needing $100M a year", "note": "For a few years"}, "correctIndex": 0, "explanation": "A billion a year crowds out other work, making it a target in a flat budget."}, "numbers": {"kind": "numberSense", "prompt": "$1 billion a year is about what percent of a $24.4 billion NASA budget?", "min": 0, "max": 20, "value": 4, "unit": "%", "explanation": "1 divided by 24.4 is about 4%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a team planning a flagship science mission.", "prompt": "Which risk do you raise early?", "options": ["Whether the logo is ready", "How many papers it will produce", "Its yearly cost inside a flat budget"], "correctIndex": 2, "consequences": ["Not a risk.", "Later concern.", "Yearly cost decides survival."], "explanation": "A mission that needs a big share of a flat budget is exposed to cuts."}, "proReasoning": "Planners compare yearly cost with the budget.", "commonMistake": "Ignoring how much of the budget it eats.", "mentalModel": "Check the yearly cost."}, "invest": {"call": {"kind": "theCall", "situation": "A supplier depends on one $11 billion NASA mission.", "prompt": "What do you flag?", "options": ["It could be cut to protect others", "It is too big to be cancelled", "Size guarantees stable funding"], "correctIndex": 0, "consequences": ["MSR lost support.", "MSR shows otherwise.", "Size raised the risk."], "explanation": "Giant missions inside a tight budget are prime targets for cuts."}, "proReasoning": "Investors flag dependence on one big program.", "commonMistake": "Thinking big means safe.", "mentalModel": "Big can mean exposed."}, "build_startup": {"call": {"kind": "theCall", "situation": "You pitch NASA a cheaper way to do a big mission.", "prompt": "What do you stress?", "options": ["More time than the old plan", "Lower yearly cost in a tight budget", "A bigger budget than the old plan"], "correctIndex": 1, "consequences": ["NASA wanted faster.", "That is what NASA asked for.", "The opposite of the need."], "explanation": "NASA asked industry for cheaper, faster Mars sample plans in 2024."}, "proReasoning": "Founders pitch to the budget pressure.", "commonMistake": "Pitching a bigger plan to a tight budget.", "mentalModel": "Cheaper, faster."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why NASA could not just find the money for Mars samples.", "prompt": "What's the reason?", "options": ["NASA has no Mars scientists", "The samples were lost", "It would crowd out other missions"], "correctIndex": 2, "consequences": ["Not the reason.", "They are on Mars.", "Up to $1B a year."], "explanation": "A billion a year is a big slice of a budget under half a cent per federal dollar."}, "proReasoning": "Every big mission competes with all the others.", "commonMistake": "Thinking NASA's budget is unlimited.", "mentalModel": "It crowds out others."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:dc19501d3409$ml$]::text[]),
($ml$76c98f8b-b382-5089-9e8b-8189422e8243$ml$::uuid, $ml$spacetech$ml$, 24, 3, $ml${"id": "spacetech-d24-c3", "title": "Save the samples or move on", "lessonTitle": "The Mars rocks that may never come home", "slot": 3, "type": "decide", "brief": {"headline": "You advise NASA's science office. Perseverance holds more than 30 Mars samples, and the return plan could cost up to $11 billion with samples home in 2040.", "kicker": "You decide how to respond when a flagship stalls.", "fullText": "Estimates grew from $5 to $7 billion to as much as $11 billion. In January 2026, Congress passed a NASA budget that does not support the existing program, keeping $110 million for future Mars mission work.\n\nChina plans to launch Tianwen-3 in 2028 and return samples in 2031, from an easier but less promising site.", "sources": [{"url": "https://spaceflightnow.com/2024/04/16/nasa-requests-proposals-to-reduce-cost-timeline-of-mars-sample-return-mission/", "label": "Spaceflight Now, NASA seeks a cheaper Mars Sample Return"}, {"url": "https://www.livescience.com/space/mars/nasas-mars-sample-return-is-dead-leaving-china-to-retrieve-signs-of-life-from-the-red-planet", "label": "Live Science, Mars Sample Return loses support"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each move keep a path to the samples open?", "buckets": ["Keeps it open", "Doesn't"], "items": [{"text": "Seek a cheaper, faster design", "bucket": 0}, {"text": "Use the $110 million on future work", "bucket": 0}, {"text": "Partner to share the cost", "bucket": 0}, {"text": "Insist on the $11 billion plan", "bucket": 1}, {"text": "Drop all Mars work for good", "bucket": 1}], "explanation": "Cheaper designs, partners and the remaining money keep options alive."}, "numbers": {"kind": "numberSense", "prompt": "China plans to return samples in 2031; the old US plan said 2040. How many years apart?", "min": 0, "max": 20, "value": 9, "unit": "years", "explanation": "2040 minus 2031 is 9 years."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your director asks for one recommendation.", "prompt": "What do you propose?", "options": ["Push for a cheaper return plan", "Defend the full $11 billion plan", "Give up on the samples for good"], "correctIndex": 0, "consequences": ["Fits the budget reality.", "Congress already said no.", "Throws away the hard part."], "explanation": "A cheaper plan has a chance. The full plan lost support."}, "proReasoning": "Advisers offer plans that fit the money.", "commonMistake": "Defending a plan Congress rejected.", "mentalModel": "Propose cheaper."}, "invest": {"call": {"kind": "theCall", "situation": "China may return Mars samples first, in 2031.", "prompt": "What does that change?", "options": ["NASA will get $11 billion now", "Pressure to find a cheaper US path", "Nothing, science is not a race"], "correctIndex": 1, "consequences": ["Congress cut it.", "Competition can move budgets.", "Rivalry shapes funding."], "explanation": "A rival returning first can add pressure for a faster, cheaper US plan."}, "proReasoning": "Investors watch rivalry as a budget driver.", "commonMistake": "Assuming rivalry has no effect.", "mentalModel": "Rivalry adds pressure."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build small Mars landers.", "prompt": "What is your pitch?", "options": ["The whole $11 billion mission", "A mission to a different planet", "A cheaper piece of the return chain"], "correctIndex": 2, "consequences": ["Too big to fund.", "Misses the need.", "Small pieces fit small budgets."], "explanation": "NASA wants cheaper paths. A smaller piece of the job is fundable."}, "proReasoning": "Founders sell the piece the budget can carry.", "commonMistake": "Pitching the full flagship.", "mentalModel": "Sell a piece."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks where Perseverance's samples are now.", "prompt": "What's the answer?", "options": ["Still on Mars, waiting", "Already back on Earth", "Lost in a crash"], "correctIndex": 0, "consequences": ["No funded way home.", "Not yet.", "They are safe."], "explanation": "More than 30 samples sit on Mars with no funded return plan."}, "proReasoning": "The hard part is done; the trip home is not.", "commonMistake": "Assuming they came back.", "mentalModel": "Still on Mars."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0decd8f0d593$ml$]::text[]),
($ml$3ddabf83-6545-5cbb-aa01-5fe5042b0a47$ml$::uuid, $ml$spacetech$ml$, 25, 1, $ml${"id": "spacetech-d25-c1", "title": "Ready to fly, waiting on a license", "lessonTitle": "Three permits before you fly", "slot": 1, "type": "apply", "brief": {"headline": "In September 2024, SpaceX said Starship's fifth flight had been ready since early August. The FAA moved its license decision to the end of November.", "kicker": "Apply the lesson: no license, no launch, however ready you are.", "fullText": "The FAA said the delay came from SpaceX changes to the mission and from new information in mid-August about the size of the environmentally affected area, which required working with the Fish and Wildlife Service.\n\nSpaceX called the analysis superfluous. At a House hearing on September 10, members questioned the FAA's rules, under which a license review can take 180 days and the FAA's space office had 158 staff.", "sources": [{"url": "https://spacepolicyonline.com/news/spacex-complains-of-starship-licensing-delay-as-house-committee-questions-faa-regs/", "label": "SpacePolicyOnline, SpaceX complains of Starship licensing delay, Sep 2024"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the Starship licensing delay in order.", "steps": ["The rocket is ready in early August", "New details on the affected area arrive", "The FAA moves its decision to November", "Congress questions the FAA's rules"], "explanation": "New information reopened the review, pushing the decision back about two months."}, "numbers": {"kind": "numberSense", "prompt": "A license review can take 180 days. About how many months is that?", "min": 0, "max": 15, "value": 6, "unit": "months", "explanation": "180 days is about six months."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You run launch planning and the license review reopens.", "prompt": "What do you do?", "options": ["Launch anyway since the rocket is ready", "Ignore it and keep the date", "Reset the schedule and send data fast"], "correctIndex": 2, "consequences": ["Illegal without a license.", "The date will slip.", "Speeds the review."], "explanation": "The FAA decides the date. Fast, complete answers help most."}, "proReasoning": "Planners treat the license as the critical path.", "commonMistake": "Planning around hardware, not permits.", "mentalModel": "The license sets the date."}, "invest": {"call": {"kind": "theCall", "situation": "A launcher's rocket is ready but its license is delayed.", "prompt": "What do you weigh?", "options": ["How long each approval takes", "Only whether the rocket is built", "Whether the CEO is popular"], "correctIndex": 0, "consequences": ["Approvals set cadence.", "Built is not licensed.", "Not a business measure."], "explanation": "License time can limit how often a new rocket flies."}, "proReasoning": "Investors count regulatory time in the schedule.", "commonMistake": "Assuming hardware readiness means launch.", "mentalModel": "Count approval time."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your first launch is planned in six months.", "prompt": "When do you start the FAA license?", "options": ["After the rocket is built", "Now, reviews can take 180 days", "A week before launch"], "correctIndex": 1, "consequences": ["Wastes months.", "Gives the review time.", "Far too late."], "explanation": "A review can take 180 days, so it must start early."}, "proReasoning": "Founders start licensing with the build.", "commonMistake": "Leaving the license until last.", "mentalModel": "Start the license early."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a ready rocket sat on the ground for months.", "prompt": "What's the reason?", "options": ["It ran out of fuel", "The weather was bad for months", "It was waiting for its FAA license"], "correctIndex": 2, "consequences": ["Not the issue.", "Not the reason.", "No license, no launch."], "explanation": "The FAA must license each launch, and new details reopened the review."}, "proReasoning": "Permission, not hardware, set the date.", "commonMistake": "Thinking a ready rocket can just go.", "mentalModel": "It needed a license."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1e5e7d360d73$ml$]::text[]),
($ml$1ec6716d-a702-5e98-95d8-9164ac7576ed$ml$::uuid, $ml$spacetech$ml$, 25, 2, $ml${"id": "spacetech-d25-c2", "title": "The same office that grounds you", "lessonTitle": "Three permits before you fly", "slot": 2, "type": "connect", "brief": {"headline": "Day 17 showed the FAA grounding Falcon 9 after a failure. Day 25 showed the FAA also licenses every US launch. One office holds both levers.", "kicker": "Connect day 17 and day 25: the launch license comes with oversight.", "fullText": "On day 17 you saw Falcon 9 stay down after its July 2024 failure until the FAA was satisfied public safety was not at risk. It flew again 16 days later.\n\nOn day 25 you saw that the FAA licenses launches and reentries to protect people on the ground and in the air. The same job explains both: it decides who can fly and when they can fly again.", "sources": [{"url": "https://spacepolicyonline.com/news/rare-spacex-failure-leaves-launch-schedules-in-flux/", "label": "SpacePolicyOnline, rare SpaceX failure"}, {"url": "https://cosmiclog.com/2024/07/27/spacex-resumes-falcon-9-launches-after-faa-go-ahead/", "label": "Cosmic Log, Falcon 9 returns after FAA go-ahead"}, {"url": "https://www.faa.gov/space", "label": "FAA, Office of Commercial Space Transportation"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is each job the FAA's?", "buckets": ["FAA", "Not the FAA"], "items": [{"text": "License a rocket launch", "bucket": 0}, {"text": "Clear a return to flight", "bucket": 0}, {"text": "License a reentry", "bucket": 0}, {"text": "License satellite radio signals", "bucket": 1}, {"text": "License an imaging satellite", "bucket": 1}], "explanation": "The FAA handles launch and reentry. The FCC and Commerce handle the rest."}, "numbers": {"kind": "numberSense", "prompt": "Falcon 9 failed on July 11, 2024 and the FAA cleared it on July 25. How many days was that?", "min": 0, "max": 40, "value": 14, "unit": "days", "explanation": "July 11 to July 25 is 14 days."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a launch company's licensing team.", "prompt": "Who is your main regulator?", "options": ["The FAA, for launches and groundings", "The FCC, for every launch step", "Nobody once you have flown once"], "correctIndex": 0, "consequences": ["It licenses and clears flights.", "The FCC handles signals.", "Oversight continues."], "explanation": "The FAA licenses launches and decides when a rocket can return after a mishap."}, "proReasoning": "Licensing staff know which office holds which lever.", "commonMistake": "Thinking the license is a one-time event.", "mentalModel": "The FAA, end to end."}, "invest": {"call": {"kind": "theCall", "situation": "A launcher has a strong record with the FAA.", "prompt": "Why does that matter?", "options": ["It never needs to report failures", "Faster licenses and faster returns", "It can skip future reviews"], "correctIndex": 1, "consequences": ["Failures must be reported.", "Trust speeds the process.", "Reviews still apply."], "explanation": "A good working record helps both licensing and return-to-flight reviews."}, "proReasoning": "Investors value regulatory relationships.", "commonMistake": "Ignoring the regulator in the valuation.", "mentalModel": "Trust saves time."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your first flight fails.", "prompt": "Who decides when you fly again?", "options": ["You, once you are confident", "Your biggest customer", "The FAA, after your investigation"], "correctIndex": 2, "consequences": ["You cannot clear yourself.", "Not their call.", "It must be satisfied first."], "explanation": "The FAA must be satisfied public safety is protected before you return."}, "proReasoning": "Founders plan for the FAA's review after any failure.", "commonMistake": "Assuming you can clear yourself.", "mentalModel": "The FAA decides."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why the FAA, an aviation agency, handles rockets.", "prompt": "What's the reason?", "options": ["It protects people on the ground", "It builds the rockets itself", "Rockets are a kind of airplane"], "correctIndex": 0, "consequences": ["That is its job.", "Companies build them.", "Not the reason."], "explanation": "The FAA licenses launches to protect the public, so it also grounds rockets after failures."}, "proReasoning": "One safety job covers both.", "commonMistake": "Thinking rockets have no regulator.", "mentalModel": "Public safety."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f47d019d7ec0$ml$]::text[]),
($ml$54d0d890-9711-561d-a74a-1edb18c829fd$ml$::uuid, $ml$spacetech$ml$, 25, 3, $ml${"id": "spacetech-d25-c3", "title": "Map the permits for an imaging satellite", "lessonTitle": "Three permits before you fly", "slot": 3, "type": "decide", "brief": {"headline": "You're the first regulatory hire at a US Earth-imaging startup. To work, its satellite needs three federal licenses.", "kicker": "You decide which permits to chase and in what order.", "fullText": "The FAA licenses the launch, the FCC licenses the radio signals and sets rules like the five-year deorbit limit, and the Commerce Department licenses private remote sensing.\n\nThe reason goes back to the 1967 Outer Space Treaty: countries answer for their companies in space, so private missions need authorization and continuing supervision.", "sources": [{"url": "https://www.faa.gov/space", "label": "FAA, Office of Commercial Space Transportation"}, {"url": "https://www.satellitetoday.com/government-military/2022/09/30/fcc-adopts-5-year-rule-for-deorbiting-satellites/", "label": "Via Satellite, FCC five-year deorbit rule"}, {"url": "https://space.commerce.gov/regulations/commercial-remote-sensing-regulatory-affairs/", "label": "Office of Space Commerce, commercial remote sensing licensing"}, {"url": "https://www.unoosa.org/documents/pdf/spacelaw/activities/2020/SLC2020Presentations/SLC2020PDFPresentations/A._Newman_-_8_Dec_2020_-_Fundamentals_of_Space_Law_.pdf", "label": "UNOOSA, fundamentals of space law"}]}, "evidence": {"kind": "faceOff", "prompt": "Your startup rides on another company's rocket. Which license is yours to get?", "left": {"name": "The FAA launch license", "note": "For the rocket's flight"}, "right": {"name": "The Commerce imaging license", "note": "For your camera"}, "correctIndex": 1, "explanation": "The launch company holds the launch license. Imaging is your responsibility."}, "numbers": {"kind": "numberSense", "prompt": "The FCC gives satellites five years to deorbit after their mission. How many months is that?", "min": 0, "max": 100, "value": 60, "unit": "months", "explanation": "Five years is 60 months."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "The CEO asks which permits the company needs.", "prompt": "What's your answer?", "options": ["None, space is not regulated at all", "FCC for signals, Commerce for images", "Only an FAA launch license"], "correctIndex": 1, "consequences": ["Not true.", "Those are yours as operator.", "The launcher holds that."], "explanation": "As a satellite operator on someone else's rocket, your licenses are FCC and Commerce."}, "proReasoning": "Regulatory leads map each permit to its owner.", "commonMistake": "Assuming the launch license covers everything.", "mentalModel": "FCC plus Commerce."}, "invest": {"call": {"kind": "theCall", "situation": "An imaging startup has no FCC or Commerce license yet.", "prompt": "How do you read it?", "options": ["Fine, licenses are a formality", "Irrelevant to its value", "A real risk to its launch date"], "correctIndex": 2, "consequences": ["They take time.", "They gate revenue.", "No license, no operation."], "explanation": "Without spectrum and imaging licenses, the satellite cannot operate."}, "proReasoning": "Investors check licenses before launch dates.", "commonMistake": "Treating licenses as paperwork.", "mentalModel": "Licenses gate revenue."}, "build_startup": {"call": {"kind": "theCall", "situation": "You design your satellite's end of life.", "prompt": "Which rule shapes it?", "options": ["The FCC five-year deorbit limit", "No rule, satellites can stay up", "The FAA launch license"], "correctIndex": 0, "consequences": ["Your design must comply.", "The FCC rule applies.", "That covers launch only."], "explanation": "The FCC requires satellites to leave orbit within five years of mission end."}, "proReasoning": "Founders design deorbit plans in from the start.", "commonMistake": "Leaving disposal until later.", "mentalModel": "Plan for five years."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why one satellite needs three licenses.", "prompt": "What's the reason?", "options": ["Because satellites are weapons", "Each agency covers a different risk", "To raise money for the government"], "correctIndex": 1, "consequences": ["Not the reason.", "Launch, signals, imaging.", "Not the purpose."], "explanation": "The FAA covers launch safety, the FCC signals, and Commerce imaging."}, "proReasoning": "Different risks, different regulators.", "commonMistake": "Thinking one license covers it all.", "mentalModel": "Different risks."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d62d91a1ad2b$ml$]::text[]),
($ml$0bc63494-abf6-5577-9c7e-7b8c985bc576$ml$::uuid, $ml$spacetech$ml$, 26, 1, $ml${"id": "spacetech-d26-c1", "title": "Debris over the Caribbean", "lessonTitle": "Who pays if a rocket hits a house", "slot": 1, "type": "apply", "brief": {"headline": "On January 16, 2025, Starship's seventh test flight broke apart over the Caribbean. The FAA grounded it and noted reports of property damage on Turks and Caicos.", "kicker": "Apply the lesson: launch damage to the public is planned for in advance.", "fullText": "SpaceX blamed a fire. The FAA activated a debris response area, diverting and delaying dozens of airline flights, and said no injuries had been reported.\n\nBefore Starship could fly again, SpaceX had to complete a mishap investigation and corrective actions. Under US rules, each launch also carries required insurance for damage to the public, sized by the FAA's estimate of the worst likely loss.", "sources": [{"url": "https://www.nbcdfw.com/news/business/money-report/faa-grounds-spacexs-starship-after-mid-flight-explosion-reports-property-damage-on-turks-and-caicos/3744180/", "label": "CNBC via NBC DFW, FAA grounds Starship after Flight 7, Jan 2025"}, {"url": "https://www.gao.gov/products/GAO-12-899", "label": "GAO, commercial space launch insurance and indemnification"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Under US rules, what covers damage to the public from a launch first?", "options": ["Taxpayers, from the first dollar", "Nothing, the public bears it", "Insurance the launch company must buy"], "correctIndex": 2, "explanation": "The FAA requires insurance up to each launch's maximum probable loss."}, "numbers": {"kind": "numberSense", "prompt": "Required insurance averages about $99 million a launch. If claims hit $40 million, how much cover is left, in millions?", "min": 0, "max": 150, "value": 59, "unit": "M", "explanation": "$99 million minus $40 million leaves about $59 million."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work in launch safety the day a test vehicle breaks up.", "prompt": "What happens before the next flight?", "options": ["A mishap investigation and fixes", "A new rocket name and paint", "Nothing if no one was hurt"], "correctIndex": 0, "consequences": ["The FAA requires both.", "Not a safety step.", "The FAA still requires a review."], "explanation": "SpaceX had to complete its investigation and corrective actions first."}, "proReasoning": "Safety teams plan the investigation path right away.", "commonMistake": "Assuming no injuries means no review.", "mentalModel": "Investigate, then fly."}, "invest": {"call": {"kind": "theCall", "situation": "A test rocket damages property abroad.", "prompt": "Who covers the claims first?", "options": ["The airlines that were delayed", "The company's required insurance", "The country where debris landed"], "correctIndex": 1, "consequences": ["They are not liable.", "Sized by maximum probable loss.", "Not how US rules work."], "explanation": "US launch companies must insure against damage to the public."}, "proReasoning": "Investors check insurance before pricing launch risk.", "commonMistake": "Assuming the company pays everything from cash.", "mentalModel": "Insurance pays first."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your rocket flies over the ocean near islands.", "prompt": "What raises your required insurance?", "options": ["A more expensive satellite on board", "A longer countdown on launch day", "More people and property under the path"], "correctIndex": 2, "consequences": ["That is a different policy.", "Not a factor.", "That raises probable loss."], "explanation": "The FAA sizes required insurance from the worst likely damage to others."}, "proReasoning": "Founders choose flight paths with risk in mind.", "commonMistake": "Ignoring what lies under the flight path.", "mentalModel": "Path sets the price."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why planes were rerouted after Starship broke up.", "prompt": "What's the reason?", "options": ["Falling debris could hit aircraft", "Pilots wanted to watch it fly", "The airports lost power"], "correctIndex": 0, "consequences": ["The FAA cleared the area.", "Not the reason.", "No outage."], "explanation": "The FAA activated a debris response area to keep aircraft away."}, "proReasoning": "Launch safety covers people in the air too.", "commonMistake": "Thinking launch risk stops at the pad.", "mentalModel": "Debris risk."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e8342555fd4a$ml$]::text[]),
($ml$51a67785-b3b7-5ea3-a918-812ed716dfcd$ml$::uuid, $ml$spacetech$ml$, 26, 2, $ml${"id": "spacetech-d26-c2", "title": "Two kinds of space insurance", "lessonTitle": "Who pays if a rocket hits a house", "slot": 2, "type": "connect", "brief": {"headline": "Day 14 showed insurers paying $995 million for failed satellites in 2023. Day 26 showed a different policy: insurance for damage to the public.", "kicker": "Connect day 14 and day 26: one policy covers you, another covers others.", "fullText": "On day 14 you saw satellite owners claim for their own losses: $445 million for ViaSat-3 and $348 million for Inmarsat-6 F2.\n\nOn day 26 you saw the FAA require launch companies to insure against harm to others, about $99 million per launch on average. The first protects the owner's asset. The second protects people on the ground, and above it taxpayers may cover more if Congress approves.", "sources": [{"url": "https://www.satellitetoday.com/sustainability/2024/05/01/slingshot-aerospace-reveals-record-insurance-losses-in-2023-in-new-satellite-deployments-report", "label": "Via Satellite, record insurance losses in 2023"}, {"url": "https://www.gao.gov/products/GAO-12-899", "label": "GAO, commercial space launch insurance and indemnification"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which policy covers each loss?", "buckets": ["Satellite insurance", "Third-party cover"], "items": [{"text": "A satellite that fails in orbit", "bucket": 0}, {"text": "A satellite lost at launch", "bucket": 0}, {"text": "Debris that damages a house", "bucket": 1}, {"text": "Injury to people near the pad", "bucket": 1}, {"text": "A satellite battery failure", "bucket": 0}], "explanation": "Owners insure their satellites. Launch companies insure against harm to others."}, "numbers": {"kind": "numberSense", "prompt": "The ViaSat-3 claim was $445 million. About how many times the $99 million average third-party cover is that?", "min": 0, "max": 10, "value": 4.5, "unit": "x", "explanation": "445 divided by 99 is about 4.5."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A new colleague mixes up the two kinds of space insurance.", "prompt": "How do you explain it?", "options": ["Only satellites ever get insured", "One for your satellite, one for others", "They are one and the same policy"], "correctIndex": 1, "consequences": ["Third-party cover is required.", "Two different risks.", "Different payers, different risks."], "explanation": "Satellite insurance protects the owner. Third-party cover protects the public."}, "proReasoning": "Good colleagues separate who is protected.", "commonMistake": "Treating all space insurance as one.", "mentalModel": "Yours vs theirs."}, "invest": {"call": {"kind": "theCall", "situation": "Satellite insurance rates jumped after record 2023 losses.", "prompt": "Does that change third-party launch cover?", "options": ["Yes, they are the same pool", "Third-party cover was scrapped too", "Not directly, it is a separate policy"], "correctIndex": 2, "consequences": ["They are separate.", "It is still required.", "Different risk, different pricing."], "explanation": "Satellite losses hit owner policies. Third-party cover is set by the FAA's loss estimate."}, "proReasoning": "Investors track each insurance line separately.", "commonMistake": "Assuming one market moves the other.", "mentalModel": "Separate lines."}, "build_startup": {"call": {"kind": "theCall", "situation": "You are launching your first satellite.", "prompt": "Which insurance is your choice?", "options": ["Insuring your own satellite", "The launcher's third-party cover", "Neither, both are automatic"], "correctIndex": 0, "consequences": ["Optional, and pricey.", "The launcher must buy that.", "Not automatic."], "explanation": "Third-party cover is the launcher's duty. Insuring your satellite is up to you."}, "proReasoning": "Founders know which policy is theirs to decide.", "commonMistake": "Assuming the launcher insures your satellite.", "mentalModel": "Yours is optional."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks who pays if a rocket damages a house.", "prompt": "What's the answer?", "options": ["Nobody, it is an accident", "The launch company's required insurance", "The satellite owner's own insurance"], "correctIndex": 1, "consequences": ["Cover is required.", "That is what it is for.", "That covers the satellite."], "explanation": "Launch companies must insure against damage to the public."}, "proReasoning": "A separate policy covers the satellite itself.", "commonMistake": "Mixing up the two policies.", "mentalModel": "Launch company insurance."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8a27dc419223$ml$]::text[]),
($ml$bae4c627-079f-59e7-95ea-f7e5fc46834c$ml$::uuid, $ml$spacetech$ml$, 26, 3, $ml${"id": "spacetech-d26-c3", "title": "Price the worst likely day", "lessonTitle": "Who pays if a rocket hits a house", "slot": 3, "type": "decide", "brief": {"headline": "You're CFO of a US launch company. The FAA will set your required insurance from each launch's maximum probable loss, about $99 million on average.", "kicker": "You decide how to plan for damage to the public.", "fullText": "Above your insurance, the government may cover up to about $2.7 billion more, but only if Congress approves the money. That backstop has never been paid.\n\nGAO found the FAA's method dated from 1988 and used a $3 million cost per casualty. A later review suggested $5 to 6 million.", "sources": [{"url": "https://www.gao.gov/products/GAO-12-899", "label": "GAO, commercial space launch insurance and indemnification"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the layers of public protection in order.", "steps": ["The FAA estimates maximum probable loss", "You buy insurance up to that amount", "Above it, the government may cover more", "Congress must approve that money"], "explanation": "Insurance covers the first layer. The government backstop needs Congress."}, "numbers": {"kind": "numberSense", "prompt": "The cost per casualty might rise from $3 million to about $5.5 million. By about what percent?", "min": 0, "max": 150, "value": 83, "unit": "%", "explanation": "$2.5 million more on $3 million is about 83%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "The board asks if the government backstop is guaranteed.", "prompt": "What's your answer?", "options": ["Yes, it pays automatically", "Yes, it has paid out many times", "No, Congress must approve the money"], "correctIndex": 2, "consequences": ["It needs Congress.", "It has never paid.", "Not automatic."], "explanation": "The backstop depends on Congress and has never been used."}, "proReasoning": "CFOs plan as if the backstop may not come.", "commonMistake": "Treating the backstop as certain.", "mentalModel": "Not guaranteed."}, "invest": {"call": {"kind": "theCall", "situation": "The FAA may raise its cost per casualty figure.", "prompt": "What do you expect?", "options": ["Higher required insurance for launches", "Lower insurance costs for everyone", "No change at all"], "correctIndex": 0, "consequences": ["A higher figure raises probable loss.", "The opposite.", "The method feeds the amount."], "explanation": "A higher casualty cost raises maximum probable loss and required cover."}, "proReasoning": "Investors watch rule changes that move costs.", "commonMistake": "Ignoring how the method sets costs.", "mentalModel": "Higher cover."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your launch site is near a town.", "prompt": "How do you keep insurance costs down?", "options": ["Skip the insurance", "Fly away from people", "Launch only at night"], "correctIndex": 1, "consequences": ["Not allowed.", "Lowers probable loss.", "Timing does not change risk much."], "explanation": "Fewer people under the path means lower maximum probable loss."}, "proReasoning": "Founders design trajectories with insurance in mind.", "commonMistake": "Ignoring the flight path's cost.", "mentalModel": "Fly away from people."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if taxpayers pay for rocket accidents.", "prompt": "What's the answer?", "options": ["Always, for every single accident", "Never, by law", "Above the insurance, if Congress agrees"], "correctIndex": 2, "consequences": ["Insurance pays first.", "A backstop exists.", "Insurance comes first."], "explanation": "Insurance covers the first layer; the government may cover more with Congress's approval."}, "proReasoning": "The backstop has never been paid.", "commonMistake": "Thinking taxpayers pay first.", "mentalModel": "Insurance first."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c3e54e702a13$ml$]::text[]),
($ml$40f7a6d1-8fca-5e80-beb6-d5f21704c237$ml$::uuid, $ml$spacetech$ml$, 27, 1, $ml${"id": "spacetech-d27-c1", "title": "A piece of the station hits a house", "lessonTitle": "When a satellite falls, a country pays", "slot": 1, "type": "apply", "brief": {"headline": "On March 8, 2024, a 700 gram piece of debris crashed through a family home in Naples, Florida. It came from a pallet of used batteries released from the space station in 2021.", "kicker": "Apply the lesson: when space objects cause damage, someone answers for it.", "fullText": "The family filed a claim with NASA for more than $80,000, and NASA had six months to respond.\n\nThe case tested how damage from falling space hardware gets paid. On day 27 you saw the international version: when Cosmos 954 fell on Canada, the launching country paid.", "sources": [{"url": "https://phys.org/news/2024-06-nasa-space-debris-family-home.html", "label": "Phys.org, family seeks payment after space debris hits home, Jun 2024"}, {"url": "https://www.unoosa.org/oosa/en/ourwork/spacelaw/nationalspacelaw/bi-multi-lateral-agreements/can_ussr_001.html", "label": "UNOOSA, Canada-USSR Cosmos 954 settlement"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The debris came from a used battery pallet.", "The family claimed more than $80,000.", "The pallet was released from the station in 2023."], "fakeIndex": 2, "explanation": "The pallet was released in 2021 and fell in 2024."}, "numbers": {"kind": "numberSense", "prompt": "The piece weighed 700 grams. How many kilograms is that?", "min": 0, "max": 2, "value": 0.7, "unit": "kg", "explanation": "700 grams is 0.7 kilograms."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join NASA's legal office the week of the claim.", "prompt": "What is the first question?", "options": ["How fast the debris fell", "Whose object it was", "Whether the family is upset"], "correctIndex": 1, "consequences": ["A detail, not the claim.", "Responsibility starts there.", "Not relevant."], "explanation": "A claim starts with whose object caused the damage."}, "proReasoning": "Lawyers trace the object to its owner first.", "commonMistake": "Arguing details before ownership.", "mentalModel": "Trace the object."}, "invest": {"call": {"kind": "theCall", "situation": "Debris from a company satellite hits a building.", "prompt": "Which risk do you see?", "options": ["None, all debris burns up", "A rise in satellite prices", "Claims and tighter rules"], "correctIndex": 2, "consequences": ["Some pieces survive.", "Not the main effect.", "Damage brings claims and scrutiny."], "explanation": "Falling hardware creates liability and pressure for stricter disposal rules."}, "proReasoning": "Investors price reentry risk into operators.", "commonMistake": "Assuming everything burns up.", "mentalModel": "Reentry carries liability."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your satellite will reenter at end of life.", "prompt": "What do you design for?", "options": ["Burning up fully on reentry", "The biggest possible pieces", "Ignoring where it falls"], "correctIndex": 0, "consequences": ["Leaves nothing to hit anyone.", "Raises the risk.", "Liability follows you."], "explanation": "A design that burns up fully avoids damage claims."}, "proReasoning": "Founders design for safe reentry.", "commonMistake": "Leaving reentry risk to chance.", "mentalModel": "Design to burn up."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks if space junk ever hits houses.", "prompt": "What's the answer?", "options": ["Every week, somewhere", "Rarely, but it did in 2024", "Never, it all burns up first"], "correctIndex": 1, "consequences": ["It is rare.", "A 700 gram piece.", "Some pieces survive."], "explanation": "A piece of a station battery pallet hit a Naples home in 2024."}, "proReasoning": "Most debris burns up, but not all.", "commonMistake": "Thinking reentry is always harmless.", "mentalModel": "Rare, but real."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:038502beff47$ml$]::text[]),
($ml$841c4c03-1337-5022-b857-8720122624ff$ml$::uuid, $ml$spacetech$ml$, 27, 2, $ml${"id": "spacetech-d27-c2", "title": "Responsible and liable", "lessonTitle": "When a satellite falls, a country pays", "slot": 2, "type": "connect", "brief": {"headline": "Day 23 showed countries are responsible for their companies in space. Day 27 showed they are also liable for damage. Together they explain why governments control launches.", "kicker": "Connect day 23 and day 27: answering for it means deciding on it.", "fullText": "On day 23 you saw Article VI of the Outer Space Treaty make each country responsible for its companies' activities in space.\n\nOn day 27 you saw that a launching country is liable for damage its objects cause, as when the USSR paid Canada C$3 million for Cosmos 954. If a government pays for the damage, it wants a say in who flies.", "sources": [{"url": "https://www.unoosa.org/documents/pdf/spacelaw/activities/2020/SLC2020Presentations/SLC2020PDFPresentations/A._Newman_-_8_Dec_2020_-_Fundamentals_of_Space_Law_.pdf", "label": "UNOOSA, fundamentals of space law"}, {"url": "https://www.unoosa.org/oosa/en/ourwork/spacelaw/nationalspacelaw/bi-multi-lateral-agreements/can_ussr_001.html", "label": "UNOOSA, Canada-USSR Cosmos 954 settlement"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why do governments license private launches?", "options": ["They want a share of every launch fee", "They own all private rockets", "They answer for the activity and its damage"], "correctIndex": 2, "explanation": "Responsibility and liability both fall on the country, so it controls who flies."}, "numbers": {"kind": "numberSense", "prompt": "Cosmos 954 broke up in January 1978 and the settlement was signed in 1981. About how many years later?", "min": 0, "max": 10, "value": 3, "unit": "years", "explanation": "1981 minus 1978 is three years."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks why launches need government approval.", "prompt": "What's your answer?", "options": ["Governments like paperwork", "Rockets are government property", "The country is liable for the damage"], "correctIndex": 2, "consequences": ["Not the reason.", "Many are private.", "Liability drives control."], "explanation": "Countries answer for their companies and for damage, so they decide who flies."}, "proReasoning": "Strong answers link liability to licensing.", "commonMistake": "Treating licensing as red tape.", "mentalModel": "Liability means control."}, "invest": {"call": {"kind": "theCall", "situation": "A country tightens launch licensing after an accident.", "prompt": "How do you read it?", "options": ["It is protecting itself from liability", "It wants to end its space industry", "It is a random choice"], "correctIndex": 0, "consequences": ["It pays for damage.", "Not likely.", "There is a reason."], "explanation": "Governments that carry liability tighten rules when risks show."}, "proReasoning": "Investors expect rules to follow accidents.", "commonMistake": "Missing the liability motive.", "mentalModel": "Liability drives rules."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want to launch from a new country.", "prompt": "What does that country weigh?", "options": ["Nothing, launch is not regulated", "Its liability if the launch fails", "Only the jobs you bring"], "correctIndex": 1, "consequences": ["Not true.", "The launch site country is liable.", "Not the only factor."], "explanation": "The country you launch from becomes liable, so it will be cautious."}, "proReasoning": "Founders address the host country's liability up front.", "commonMistake": "Ignoring the host country's exposure.", "mentalModel": "Address its liability."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks who paid when a Soviet satellite fell on Canada.", "prompt": "What's the answer?", "options": ["Canada paid for the cleanup alone", "The UN paid both sides", "The USSR, C$3 million"], "correctIndex": 2, "consequences": ["The USSR paid.", "Not the UN.", "Settled in 1981."], "explanation": "The launching country paid Canada C$3 million in 1981."}, "proReasoning": "Liability follows the launching country.", "commonMistake": "Thinking nobody pays for space debris.", "mentalModel": "The USSR paid."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:dda323deef0d$ml$]::text[]),
($ml$9c354844-859d-5fe9-8f8f-e14692780f4f$ml$::uuid, $ml$spacetech$ml$, 27, 3, $ml${"id": "spacetech-d27-c3", "title": "Should your country host this launch?", "lessonTitle": "When a satellite falls, a country pays", "slot": 3, "type": "decide", "brief": {"headline": "You advise a government that's asked to host a foreign company's launches. Under the Outer Space Treaty, the country a launch leaves from can be liable for damage.", "kicker": "You decide how much liability your country takes on.", "fullText": "Liability follows the launching country, which includes the country that launches, the one that procures the launch, and the one whose territory it leaves from.\n\nWhen Cosmos 954 broke up over Canada in 1978, the USSR later paid C$3 million. Because countries carry this liability, they keep tight control over who launches.", "sources": [{"url": "https://www.unoosa.org/documents/pdf/spacelaw/activities/2020/SLC2020Presentations/SLC2020PDFPresentations/A._Newman_-_8_Dec_2020_-_Fundamentals_of_Space_Law_.pdf", "label": "UNOOSA, fundamentals of space law"}, {"url": "https://www.unoosa.org/oosa/en/ourwork/spacelaw/nationalspacelaw/bi-multi-lateral-agreements/can_ussr_001.html", "label": "UNOOSA, Canada-USSR Cosmos 954 settlement"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each make your country a launching country?", "buckets": ["Yes", "No"], "items": [{"text": "The launch leaves from your soil", "bucket": 0}, {"text": "Your company buys the launch", "bucket": 0}, {"text": "Your agency launches it", "bucket": 0}, {"text": "Your citizens watch it on TV", "bucket": 1}, {"text": "A foreign launch from abroad", "bucket": 1}], "explanation": "Launching, procuring or hosting a launch all make a country liable."}, "numbers": {"kind": "numberSense", "prompt": "Cosmos 954 broke up in 1978. How many years before 2026 was that?", "min": 0, "max": 80, "value": 48, "unit": "years", "explanation": "2026 minus 1978 is 48 years."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "The minister asks what hosting really commits the country to.", "prompt": "What's your answer?", "options": ["Possible liability for any damage", "Only collecting a hosting fee", "Nothing, the company is liable"], "correctIndex": 0, "consequences": ["Hosting makes you a launching state.", "Ignores liability.", "The country is liable too."], "explanation": "Hosting a launch makes your country liable under the treaty."}, "proReasoning": "Advisers spell out the liability before the deal.", "commonMistake": "Treating hosting as pure revenue.", "mentalModel": "Hosting means liability."}, "invest": {"call": {"kind": "theCall", "situation": "A small country starts hosting foreign launches.", "prompt": "What will it likely demand?", "options": ["Ownership of the rockets", "Insurance and strict licensing", "Nothing beyond a fee"], "correctIndex": 1, "consequences": ["Not standard.", "It must cover its liability.", "Ignores its exposure."], "explanation": "A host country will protect itself with insurance and licensing."}, "proReasoning": "Investors expect host countries to pass risk to launchers.", "commonMistake": "Assuming hosts take risk for free.", "mentalModel": "Hosts demand cover."}, "build_startup": {"call": {"kind": "theCall", "situation": "You ask a country to host your launches.", "prompt": "What do you offer?", "options": ["Only jobs and tax revenue", "A promise nothing will fail", "Insurance and a safety plan"], "correctIndex": 2, "consequences": ["Ignores the main worry.", "Not credible.", "Addresses its liability."], "explanation": "A host weighs its liability. Insurance and safety plans answer that."}, "proReasoning": "Founders solve the host's risk, not just sell benefits.", "commonMistake": "Pitching benefits while ignoring liability.", "mentalModel": "Cover their risk."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a country would worry about a foreign rocket.", "prompt": "What's the reason?", "options": ["Launching from its soil means liability", "It wants to copy the rocket design", "It fears too much noise"], "correctIndex": 0, "consequences": ["Liability follows the launch site.", "Not the reason.", "A minor worry."], "explanation": "Under the treaty, the country a launch leaves from can be liable for damage."}, "proReasoning": "Hosting is a legal commitment.", "commonMistake": "Thinking only the company is responsible.", "mentalModel": "The host is liable too."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:95c03c8b58fe$ml$]::text[]),
($ml$88652d90-978d-57dc-afcf-6e49bc033291$ml$::uuid, $ml$spacetech$ml$, 28, 1, $ml${"id": "spacetech-d28-c1", "title": "Behind on the clock", "lessonTitle": "10%, 50%, 100%: the ITU clock", "slot": 1, "type": "apply", "brief": {"headline": "Amazon faced an FCC deadline to have 1,618 of its 3,232 planned Leo satellites up by July 30, 2026. In early 2026 it had about 180 in orbit and asked for 24 more months.", "kicker": "Apply the lesson: deployment deadlines turn on launch supply.", "fullText": "Amazon said it expected about 700 satellites in orbit by the deadline. It blamed a shortage of launch capacity, along with weather, government launch priority and launch vehicle issues.\n\nThis was a US regulator's 50% milestone rather than the ITU's, but the logic is the same as day 28: spectrum is reserved on paper and kept by launching.", "sources": [{"url": "https://www.fierce-network.com/broadband/amazon-leo-asks-fcc-extension-launch-satellites-broadband", "label": "Fierce Network, Amazon Leo asks FCC for more time, Feb 2026"}, {"url": "https://itu.int/en/mediacentre/backgrounders/Pages/Non-geostationary-satellite-systems.aspx", "label": "ITU, non-geostationary satellite systems"}]}, "evidence": {"kind": "sortSignal", "prompt": "Did Amazon cite this as a reason for the delay?", "buckets": ["Cited", "Not cited"], "items": [{"text": "A shortage of launch capacity", "bucket": 0}, {"text": "Weather", "bucket": 0}, {"text": "Government launch priority", "bucket": 0}, {"text": "No demand for broadband", "bucket": 1}, {"text": "Too many satellites built", "bucket": 1}], "explanation": "Amazon pointed mainly to launch supply, plus weather and government priority."}, "numbers": {"kind": "numberSense", "prompt": "Amazon expected about 700 of the 1,618 required satellites by the deadline. About what percent is that?", "min": 0, "max": 100, "value": 43, "unit": "%", "explanation": "700 divided by 1,618 is about 43%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You plan launches for a constellation behind its deadline.", "prompt": "What do you secure first?", "options": ["A bigger satellite factory now", "A new name for the network", "More launch slots, more rockets"], "correctIndex": 2, "consequences": ["Satellites need rides.", "Does not move the deadline.", "Launch supply is the bottleneck."], "explanation": "Amazon's delay came from launch capacity, so more rides matter most."}, "proReasoning": "Planners fix the real bottleneck.", "commonMistake": "Building more than you can launch.", "mentalModel": "Secure rides."}, "invest": {"call": {"kind": "theCall", "situation": "A constellation has 11% of the satellites its deadline needs.", "prompt": "What do you weigh?", "options": ["Whether regulators grant more time", "Only how good the satellites are", "Nothing, deadlines are flexible"], "correctIndex": 0, "consequences": ["The licence depends on it.", "Quality does not meet deadlines.", "Not guaranteed."], "explanation": "Missing a milestone can shrink a license unless more time is granted."}, "proReasoning": "Investors track milestone compliance.", "commonMistake": "Assuming extensions are automatic.", "mentalModel": "Watch the milestone."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your constellation plan assumes launches on demand.", "prompt": "What do you change?", "options": ["Wait to book until satellites ship", "Book early on several rockets", "Assume rockets will be there"], "correctIndex": 1, "consequences": ["Too late for deadlines.", "Protects your milestones.", "Amazon learned otherwise."], "explanation": "Launch supply can decide whether you meet a deployment deadline."}, "proReasoning": "Founders lock in launch capacity early.", "commonMistake": "Treating launch as always available.", "mentalModel": "Book rides early."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why Amazon needed more time.", "prompt": "What's the reason?", "options": ["It ran out of satellites", "Its customers cancelled", "Not enough rockets"], "correctIndex": 2, "consequences": ["Satellites were waiting.", "Not the reason.", "Launch shortage."], "explanation": "Amazon said launch capacity was short, so it could not meet the deadline."}, "proReasoning": "Launch supply limits how fast networks grow.", "commonMistake": "Thinking building satellites is the hard part.", "mentalModel": "Not enough rockets."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f4472316c332$ml$]::text[]),
($ml$1f4da244-303e-5b80-af15-7c253ebb9336$ml$::uuid, $ml$spacetech$ml$, 28, 2, $ml${"id": "spacetech-d28-c2", "title": "Thousands of satellites, one clock", "lessonTitle": "10%, 50%, 100%: the ITU clock", "slot": 2, "type": "connect", "brief": {"headline": "Day 8 showed low orbit networks need thousands of satellites. Day 28 showed the ITU clock: 10% in 2 years, 50% in 5, all in 7.", "kicker": "Connect day 8 and day 28: the bigger the network, the harder the clock.", "fullText": "On day 8 you saw a low satellite cover only a small patch, so Starlink flew about 9,400 satellites by early 2026, against a handful for a geostationary network.\n\nOn day 28 you saw the ITU set deployment milestones for non-geostationary systems in 2019. A network that needs thousands of satellites must launch thousands on schedule to keep its frequencies.", "sources": [{"url": "https://aerospace.csis.org/?p=22", "label": "CSIS Aerospace Security, popular orbits"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}, {"url": "https://itu.int/en/mediacentre/backgrounders/Pages/Non-geostationary-satellite-systems.aspx", "label": "ITU, non-geostationary satellite systems"}]}, "evidence": {"kind": "faceOff", "prompt": "Which system must race the ITU milestones?", "left": {"name": "A low orbit network", "note": "Thousands of satellites"}, "right": {"name": "A geostationary satellite", "note": "One fixed slot"}, "correctIndex": 0, "explanation": "The 2019 milestones apply to non-geostationary constellations."}, "numbers": {"kind": "numberSense", "prompt": "A network filed for 9,400 satellites. Under the ITU clock, how many must fly within 5 years, in thousands?", "min": 0, "max": 8, "value": 4.7, "unit": "K", "explanation": "50% of 9,400 is 4,700."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a low orbit network's planning team.", "prompt": "What deadline shapes your launch plan?", "options": ["ITU deployment milestones", "The company's anniversary", "The next trade show"], "correctIndex": 0, "consequences": ["They decide your spectrum.", "Not a real deadline.", "Not binding."], "explanation": "Milestones require large shares of the network in orbit by set dates."}, "proReasoning": "Planners build launch schedules backward from milestones.", "commonMistake": "Ignoring the regulatory clock.", "mentalModel": "Plan to the milestones."}, "invest": {"call": {"kind": "theCall", "situation": "A new low orbit network files for 10,000 satellites.", "prompt": "What do you ask?", "options": ["Does it have a big office?", "Can it fly 5,000 in five years?", "Is the logo easy to remember?"], "correctIndex": 1, "consequences": ["Not relevant.", "That is the 50% milestone.", "Not relevant."], "explanation": "A big filing only holds if launches keep up with the milestones."}, "proReasoning": "Investors test filings against the clock.", "commonMistake": "Taking the filing size at face value.", "mentalModel": "Test against the clock."}, "build_startup": {"call": {"kind": "theCall", "situation": "You plan a low orbit network.", "prompt": "How do you size your filing?", "options": ["As big as possible to block rivals", "Small, then never launch", "To what you can truly launch in time"], "correctIndex": 2, "consequences": ["Milestones will catch it.", "You lose the frequencies.", "Meets the milestones."], "explanation": "Filing for more than you can launch risks missing milestones."}, "proReasoning": "Founders size filings to launch capacity.", "commonMistake": "Filing big to warehouse spectrum.", "mentalModel": "File what you can fly."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why satellite networks rush to launch.", "prompt": "What's the reason?", "options": ["They must hit deadlines for spectrum", "Rockets get more expensive daily", "Satellites spoil on the ground"], "correctIndex": 0, "consequences": ["ITU milestones.", "Not the reason.", "Not true."], "explanation": "Low orbit networks must deploy set shares by set dates to keep frequencies."}, "proReasoning": "The clock pushes launches.", "commonMistake": "Thinking the rush is only commercial.", "mentalModel": "Beat the clock."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:70dc18002be3$ml$]::text[]),
($ml$194dcfa2-cfb3-52d8-8e69-86909d75b639$ml$::uuid, $ml$spacetech$ml$, 28, 3, $ml${"id": "spacetech-d28-c3", "title": "Plan a launch schedule to the clock", "lessonTitle": "10%, 50%, 100%: the ITU clock", "slot": 3, "type": "decide", "brief": {"headline": "You're head of planning for a new constellation. Since 2019, the ITU requires 10% deployed within 2 years, 50% within 5 and all within 7.", "kicker": "You decide how to schedule launches so you keep your frequencies.", "fullText": "The clock starts after the regulatory period for bringing frequencies into use ends. Filing at the ITU reserves frequencies on paper, and the milestones push operators to actually launch.\n\nThe goal is to keep the ITU's frequency register close to what is really flying and to stop spectrum warehousing.", "sources": [{"url": "https://itu.int/en/mediacentre/backgrounders/Pages/Non-geostationary-satellite-systems.aspx", "label": "ITU, non-geostationary satellite systems"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the ITU deployment steps in order.", "steps": ["File and reserve frequencies", "Deploy 10% within 2 years", "Deploy 50% within 5 years", "Deploy all within 7 years"], "explanation": "The milestones rise from 10% to 50% to 100% over seven years."}, "numbers": {"kind": "numberSense", "prompt": "Your filing covers 4,000 satellites. How many must be up within 2 years?", "min": 0, "max": 1000, "value": 400, "unit": "satellites", "explanation": "10% of 4,000 is 400."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CEO wants to file for twice what you can launch.", "prompt": "What do you advise?", "options": ["Do not file at all", "File for what you can deploy in time", "File big, milestones are loose"], "correctIndex": 1, "consequences": ["You need frequencies.", "Keeps the filing real.", "They are enforced."], "explanation": "Milestones were written to stop filings far larger than deployment."}, "proReasoning": "Planners keep filings honest.", "commonMistake": "Filing far beyond capacity.", "mentalModel": "File what you can fly."}, "invest": {"call": {"kind": "theCall", "situation": "A constellation is behind its 50% milestone.", "prompt": "What is the risk?", "options": ["Higher satellite prices", "No risk, milestones are advice", "Losing part of its frequencies"], "correctIndex": 2, "consequences": ["Not the main risk.", "They have teeth.", "Paper claims shrink."], "explanation": "Missing milestones can cut the frequencies an operator can keep."}, "proReasoning": "Investors track milestone progress.", "commonMistake": "Ignoring milestone risk.", "mentalModel": "Spectrum at risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "You have frequencies but launches are slipping.", "prompt": "What do you prioritize?", "options": ["Hitting the next milestone count", "Perfecting the satellite design", "A new marketing campaign"], "correctIndex": 0, "consequences": ["Keeps the frequencies.", "Can wait.", "Does not keep spectrum."], "explanation": "The next milestone decides whether you keep what you filed."}, "proReasoning": "Founders treat milestones as hard deadlines.", "commonMistake": "Polishing while the clock runs.", "mentalModel": "Hit the milestone."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what spectrum warehousing is.", "prompt": "What's the answer?", "options": ["Saving radio parts for later", "Holding frequencies you are not using", "Storing satellites in a warehouse"], "correctIndex": 1, "consequences": ["Not the meaning.", "The milestones target it.", "Not the meaning."], "explanation": "Warehousing means reserving spectrum on paper without using it."}, "proReasoning": "The ITU clock was built to stop it.", "commonMistake": "Taking the term literally.", "mentalModel": "Unused spectrum."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:78fecaf3240a$ml$]::text[]),
($ml$3271430a-bcb8-5932-bad3-01aa2efea745$ml$::uuid, $ml$spacetech$ml$, 29, 1, $ml${"id": "spacetech-d29-c1", "title": "Fined for skipping the approved plan", "lessonTitle": "The satellites launched without permission", "slot": 1, "type": "apply", "brief": {"headline": "In September 2024, the FAA proposed $633,009 in penalties against SpaceX for not following its license on two 2023 launches.", "kicker": "Apply the lesson: flying outside your license costs money.", "fullText": "For a June 2023 launch, the FAA said SpaceX used a new control room without approval and skipped a readiness poll two hours before launch, proposing $350,000. For a July 2023 launch, it said SpaceX used a new propellant farm without approval, proposing $283,009.\n\nThe FAA said failure to comply with safety requirements will result in consequences.", "sources": [{"url": "https://www.faa.gov/newsroom/faa-proposes-633009-civil-penalties-against-spacex", "label": "FAA, proposed $633,009 civil penalties against SpaceX, Sep 2024"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which launch was each alleged violation tied to?", "buckets": ["June 2023 launch", "July 2023 launch"], "items": [{"text": "Unapproved control room", "bucket": 0}, {"text": "Skipped readiness poll", "bucket": 0}, {"text": "Unapproved propellant farm", "bucket": 1}, {"text": "The $350,000 penalty", "bucket": 0}, {"text": "The $283,009 penalty", "bucket": 1}], "explanation": "Two violations were tied to the June launch and one to the July launch."}, "numbers": {"kind": "numberSense", "prompt": "The July launch penalty was $283,009 of $633,009 in total. About what percent is that?", "min": 0, "max": 100, "value": 45, "unit": "%", "explanation": "283,009 divided by 633,009 is about 45%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You run launch control and want to use a new room.", "prompt": "What do you do first?", "options": ["Get FAA approval for the change", "Use it, the room is clearly safe", "Tell the FAA after launch"], "correctIndex": 0, "consequences": ["Avoids a penalty.", "Safe is not approved.", "Too late."], "explanation": "The license covers the approved setup. Changes need approval first."}, "proReasoning": "Ops leads clear changes before using them.", "commonMistake": "Treating a license as a formality.", "mentalModel": "Approve, then change."}, "invest": {"call": {"kind": "theCall", "situation": "A launcher gets a proposed FAA penalty.", "prompt": "How do you weigh it?", "options": ["Ignore it, fines never matter", "Small cost; watch for repeats", "The company is finished"], "correctIndex": 1, "consequences": ["Repeat issues can slow licenses.", "Patterns matter more than one fine.", "Overreaction."], "explanation": "A single fine is small. A pattern can strain the regulator relationship."}, "proReasoning": "Investors watch for repeat compliance problems.", "commonMistake": "Over- or under-reacting to one fine.", "mentalModel": "Watch for patterns."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your team wants to upgrade ground systems mid-campaign.", "prompt": "What is your rule?", "options": ["Upgrade now, approve later", "Skip approvals for small changes", "No change without license approval"], "correctIndex": 2, "consequences": ["SpaceX was fined for that.", "Small changes count too.", "Keeps you compliant."], "explanation": "Using unapproved facilities drew penalties for SpaceX."}, "proReasoning": "Founders build approval into change plans.", "commonMistake": "Assuming small changes are exempt.", "mentalModel": "Approve first."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why SpaceX was fined if nothing went wrong.", "prompt": "What's the reason?", "options": ["It did not follow its approved plan", "A rocket exploded", "It launched without any license"], "correctIndex": 0, "consequences": ["The plan is the license.", "Nothing exploded.", "It had licenses."], "explanation": "The FAA fines operators for skipping approved steps, even when launches succeed."}, "proReasoning": "Following the plan is part of safety.", "commonMistake": "Thinking fines need an accident.", "mentalModel": "Follow the plan."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b8538c8dde28$ml$]::text[]),
($ml$2a30e5bb-b0f2-5250-83ef-8e801ea1fbe2$ml$::uuid, $ml$spacetech$ml$, 29, 2, $ml${"id": "spacetech-d29-c2", "title": "Too small to track", "lessonTitle": "The satellites launched without permission", "slot": 2, "type": "connect", "brief": {"headline": "Day 12 showed Starlink dodging about 300,000 possible collisions in 2025. Day 29 showed why the FCC refused Swarm's tiny satellites: they might be too hard to track.", "kicker": "Connect day 12 and day 29: you cannot dodge what you cannot see.", "fullText": "On day 12 you saw collision avoidance depend on knowing where every object is, with SpaceX moving at a risk of about three in ten million.\n\nOn day 29 you saw Swarm launch four SpaceBEEs, about a quarter the size of a standard cubesat, after the FCC refused them over tracking concerns. Swarm paid $900,000.", "sources": [{"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}, {"url": "https://techcrunch.com/2018/12/20/fcc-fines-swarm-technologies-900k-over-unauthorized-satellite-launch/", "label": "TechCrunch, FCC fines Swarm $900,000"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why does tracking matter so much in crowded orbits?", "options": ["Operators can only dodge what they can see", "Tracking makes satellites move faster", "Untracked satellites cost less to insure"], "correctIndex": 0, "explanation": "Collision avoidance needs to know where every object is."}, "numbers": {"kind": "numberSense", "prompt": "Swarm paid $900,000 for four satellites. About how much per satellite, in thousands?", "min": 0, "max": 500, "value": 225, "unit": "K", "explanation": "$900,000 divided by 4 is $225,000."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You design a very small satellite.", "prompt": "What does the regulator ask first?", "options": ["Whether it is the smallest ever", "Whether it can be tracked", "Whether it looks modern"], "correctIndex": 1, "consequences": ["Size is the worry.", "Swarm was refused over this.", "Not a criterion."], "explanation": "Satellites too small to track raise collision risk for everyone."}, "proReasoning": "Engineers plan for trackability from the start.", "commonMistake": "Shrinking a satellite past what radar sees.", "mentalModel": "Make it trackable."}, "invest": {"call": {"kind": "theCall", "situation": "A startup sells ultra-small satellites.", "prompt": "Which risk do you check?", "options": ["Whether they fit in a suitcase", "Whether they are cheap to paint", "Whether regulators will license them"], "correctIndex": 2, "consequences": ["Not a risk.", "Not relevant.", "Swarm was refused at first."], "explanation": "Very small satellites can face licensing trouble over tracking."}, "proReasoning": "Investors check licensing before scale.", "commonMistake": "Assuming smaller is always better.", "mentalModel": "Check licensing."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your satellites are tiny to save launch cost.", "prompt": "What do you add?", "options": ["Features that aid tracking", "Nothing, small is just fine", "A bigger logo on the side"], "correctIndex": 0, "consequences": ["Answers the regulator's worry.", "Swarm was refused.", "Does not help tracking."], "explanation": "Making tiny satellites trackable answers the main licensing worry."}, "proReasoning": "Founders solve the regulator's concern before filing.", "commonMistake": "Ignoring tracking until refused.", "mentalModel": "Build in trackability."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a satellite can be too small.", "prompt": "What's the reason?", "options": ["It falls to Earth at once", "Radar may not see it to dodge it", "It cannot carry a camera at all"], "correctIndex": 1, "consequences": ["Not true.", "Tracking is the issue.", "Not the reason."], "explanation": "If no one can track it, no one can dodge it."}, "proReasoning": "Crowded orbits depend on tracking.", "commonMistake": "Thinking smaller is always safer.", "mentalModel": "It must be seen."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:59fcd1f09e47$ml$]::text[]),
($ml$a3c05f17-d6a9-57c7-a4e2-0577758e5de1$ml$::uuid, $ml$spacetech$ml$, 29, 3, $ml${"id": "spacetech-d29-c3", "title": "Wait for the license or fly abroad?", "lessonTitle": "The satellites launched without permission", "slot": 3, "type": "decide", "brief": {"headline": "You're COO of a satellite startup. Your FCC license is stuck, and a foreign rocket has a seat next month.", "kicker": "You decide whether to fly before you are licensed.", "fullText": "In January 2018, Swarm Technologies flew four SpaceBEEs on India's PSLV after the FCC had refused them. As a US company, it still answered to the FCC.\n\nIn December 2018, Swarm agreed to pay $900,000 and accept extra oversight, including reporting each launch deal to the FCC within five days of signing.", "sources": [{"url": "https://techcrunch.com/2018/12/20/fcc-fines-swarm-technologies-900k-over-unauthorized-satellite-launch/", "label": "TechCrunch, FCC fines Swarm $900,000"}]}, "evidence": {"kind": "faceOff", "prompt": "Which choice costs the startup less over time?", "left": {"name": "Wait for the license", "note": "Lose a launch slot"}, "right": {"name": "Fly abroad without it", "note": "Risk a fine and oversight"}, "correctIndex": 0, "explanation": "Swarm paid $900,000 and came under closer supervision for flying first."}, "numbers": {"kind": "numberSense", "prompt": "Swarm launched in January 2018 and settled in December 2018. About how many months apart?", "min": 0, "max": 24, "value": 11, "unit": "months", "explanation": "January to December is about 11 months."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "The CEO wants to take the foreign seat now.", "prompt": "What do you advise?", "options": ["Go, a foreign rocket avoids US rules", "Go, and apologize afterward", "Wait, the license follows you abroad"], "correctIndex": 2, "consequences": ["US companies still answer.", "Swarm paid $900,000.", "Swarm learned this."], "explanation": "A US company answers to the FCC even on a foreign rocket."}, "proReasoning": "COOs protect the company from avoidable penalties.", "commonMistake": "Thinking a foreign launch escapes US rules.", "mentalModel": "Wait for the license."}, "invest": {"call": {"kind": "theCall", "situation": "A startup flew without a license and was fined.", "prompt": "What matters most now?", "options": ["How the regulator treats it now", "Only the fine amount", "Nothing, since it already flew"], "correctIndex": 0, "consequences": ["Oversight can slow future work.", "The fine is the smaller cost.", "It still needs licenses."], "explanation": "Extra oversight can slow every future license and launch deal."}, "proReasoning": "Investors weigh the lasting regulatory cost.", "commonMistake": "Looking only at the fine.", "mentalModel": "Oversight lasts."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your license will take two more months.", "prompt": "How do you protect the schedule?", "options": ["Rename the satellite, then refile", "Rebook later and push the FCC", "Launch now on any rocket"], "correctIndex": 1, "consequences": ["Does not fix it.", "Legal and on track.", "Risks a fine."], "explanation": "Rebooking keeps you compliant; engaging the regulator speeds the license."}, "proReasoning": "Founders plan launches around license timing.", "commonMistake": "Trading compliance for speed.", "mentalModel": "Rebook and push."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks what happened to the company that launched without permission.", "prompt": "What's the answer?", "options": ["Nothing at all happened to it", "Its satellites were shot down", "It paid $900,000 and got oversight"], "correctIndex": 2, "consequences": ["It was fined.", "Not true.", "FCC settlement."], "explanation": "Swarm paid $900,000 and must report launch deals to the FCC."}, "proReasoning": "Launching first cost more than waiting.", "commonMistake": "Thinking there were no consequences.", "mentalModel": "A fine and oversight."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:72903e016a51$ml$]::text[]),
($ml$c574fa1d-6c60-5c35-ba70-af77066f4733$ml$::uuid, $ml$spacetech$ml$, 30, 1, $ml${"id": "spacetech-d30-c1", "title": "200,000 satellites on paper", "lessonTitle": "327,320 satellites on paper", "slot": 1, "type": "apply", "brief": {"headline": "In January 2026, China was reported to have filed with the ITU for a constellation of about 200,000 satellites, four times SpaceX's 50,000 Starlink goal.", "kicker": "Apply the lesson: a filing is a claim, not a constellation.", "fullText": "The filing came on top of China's existing G60 and Guowang constellation projects. Like Rwanda's 327,320-satellite filing in 2021, it reserves frequencies on paper long before anything is built.\n\nUnder the ITU's 2019 milestones, any filing must be backed by launches on a fixed clock to keep its frequencies.", "sources": [{"url": "https://smallsatnews.com/2026/01/12/as-spacex-targets-50000-starlink-satellites-china-files-for-200000-unit-mega-constellation/", "label": "SmallSat News, China files for a 200,000-satellite constellation, Jan 2026"}, {"url": "https://spaceinafrica.com/2021/10/14/rwanda-has-submitted-itu-filing-for-27-orbital-shells-of-327320-satellites/", "label": "Space in Africa, Rwanda files for 327,320 satellites"}, {"url": "https://itu.int/en/mediacentre/backgrounders/Pages/Non-geostationary-satellite-systems.aspx", "label": "ITU, non-geostationary satellite systems"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What does a 200,000-satellite ITU filing actually secure?", "options": ["A fleet already being built in full", "A claim on frequencies, kept by launching", "Ownership of an orbit for good"], "correctIndex": 1, "explanation": "A filing reserves spectrum on paper. Milestones decide what it keeps."}, "numbers": {"kind": "numberSense", "prompt": "The filing covers about 200,000 satellites; Starlink had about 9,400. Roughly how many times larger?", "min": 0, "max": 50, "value": 21, "unit": "x", "explanation": "200,000 divided by 9,400 is about 21."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks if China will fly 200,000 satellites.", "prompt": "What's your answer?", "options": ["No, filings are always fake", "It is a paper claim; watch launches", "Yes, the filing guarantees it"], "correctIndex": 1, "consequences": ["Some do become real.", "Launches show what is real.", "Filings guarantee nothing."], "explanation": "Filings reserve spectrum. Only launches show what will fly."}, "proReasoning": "Analysts track launches, not filing sizes.", "commonMistake": "Taking a filing as a fleet.", "mentalModel": "Watch launches."}, "invest": {"call": {"kind": "theCall", "situation": "A rival files for 200,000 satellites.", "prompt": "How do you judge the threat?", "options": ["By the size of the filing alone", "By ignoring it entirely", "By its launches against milestones"], "correctIndex": 2, "consequences": ["Size alone misleads.", "It could become real.", "Shows real capacity."], "explanation": "Milestones force filings to show real deployment over time."}, "proReasoning": "Investors measure threats by what flies.", "commonMistake": "Reacting to headline filing size.", "mentalModel": "Measure what flies."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your network plans 1,000 satellites; a rival filed for 200,000.", "prompt": "What do you do?", "options": ["Launch on your own clock", "Give up, you cannot compete", "File for 300,000 to match it"], "correctIndex": 0, "consequences": ["Real satellites win.", "Paper does not serve users.", "Milestones will catch you."], "explanation": "A huge filing still has to meet milestones. Deploy yours."}, "proReasoning": "Founders compete on deployment, not filings.", "commonMistake": "Racing to file bigger numbers.", "mentalModel": "Deploy, do not inflate."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend heard China plans 200,000 satellites.", "prompt": "What's the context?", "options": ["It is a movie plot", "A filing; most is not built", "They are all in orbit"], "correctIndex": 1, "consequences": ["It is a real filing.", "Paper first.", "Not true."], "explanation": "A filing reserves frequencies long before anything is built."}, "proReasoning": "Filings and fleets are different things.", "commonMistake": "Mistaking a filing for a fleet.", "mentalModel": "A filing, not a fleet."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4832bc6d9cf4$ml$]::text[]),
($ml$c17ff1ec-36fa-55bf-9219-fff020c7d715$ml$::uuid, $ml$spacetech$ml$, 30, 2, $ml${"id": "spacetech-d30-c2", "title": "Rwanda against the clock", "lessonTitle": "327,320 satellites on paper", "slot": 2, "type": "connect", "brief": {"headline": "Day 28 showed the ITU clock: 10% deployed within 2 years. Day 30 showed Rwanda's 327,320-satellite filing. Run the two together and the gap is huge.", "kicker": "Connect day 28 and day 30: milestones test paper filings.", "fullText": "On day 28 you saw the ITU require 10% of a constellation in 2 years, 50% in 5 and 100% in 7, to keep the register close to what is flying.\n\nOn day 30 you saw Rwanda file in September 2021 for 327,320 satellites across 27 shells, with no clear builder. Its 10% milestone alone would be more than three times Starlink's 9,400 satellites.", "sources": [{"url": "https://itu.int/en/mediacentre/backgrounders/Pages/Non-geostationary-satellite-systems.aspx", "label": "ITU, non-geostationary satellite systems"}, {"url": "https://spaceinafrica.com/2021/10/14/rwanda-has-submitted-itu-filing-for-27-orbital-shells-of-327320-satellites/", "label": "Space in Africa, Rwanda files for 327,320 satellites"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Rwanda filed for 327,320 satellites in 2021.", "The filing spread them over 27 orbital shells.", "Rwanda had already built most of them."], "fakeIndex": 2, "explanation": "It was not clear who would build them. The filing was on paper."}, "numbers": {"kind": "numberSense", "prompt": "10% of 327,320 satellites must fly within 2 years. About how many is that, in thousands?", "min": 0, "max": 80, "value": 32.7, "unit": "K", "explanation": "10% of 327,320 is 32,732."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A colleague says Rwanda will soon rival Starlink.", "prompt": "How do you test that?", "options": ["Count the shells in the filing", "Trust the filing as written", "Compare its 10% goal with launches"], "correctIndex": 2, "consequences": ["Shells are paper too.", "Filings are not fleets.", "32,732 satellites in 2 years."], "explanation": "Its first milestone would need 32,732 satellites, over three times Starlink."}, "proReasoning": "Analysts test filings against milestones.", "commonMistake": "Taking a filing at face value.", "mentalModel": "Run the milestone."}, "invest": {"call": {"kind": "theCall", "situation": "A filing is far larger than any fleet ever launched.", "prompt": "What do you conclude?", "options": ["It is unlikely to be built as filed", "It will be built on time", "Its size guarantees a monopoly"], "correctIndex": 0, "consequences": ["Milestones will trim it.", "No sign of capacity.", "Paper is not power."], "explanation": "Milestones make oversized filings shrink to what actually launches."}, "proReasoning": "Investors discount filings beyond launch capacity.", "commonMistake": "Believing headline numbers.", "mentalModel": "Discount the paper."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your network shares a band with a huge paper filing.", "prompt": "What do you do?", "options": ["Ignore it completely", "Track its milestones", "Abandon your network now"], "correctIndex": 1, "consequences": ["It may still matter.", "Milestones may free space.", "Too early."], "explanation": "Missed milestones can shrink a paper filing, which may free spectrum."}, "proReasoning": "Founders watch rivals' milestone progress.", "commonMistake": "Giving up to a paper rival.", "mentalModel": "Track their clock."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how a small country filed for 327,320 satellites.", "prompt": "What's the answer?", "options": ["It owns the most rockets on Earth", "The ITU builds them for it", "Filing is cheap; launching is not"], "correctIndex": 2, "consequences": ["Not true.", "The ITU does not build.", "Milestones test it."], "explanation": "Anyone with a national filing can reserve frequencies; milestones check reality."}, "proReasoning": "Paper claims are easy, launches are hard.", "commonMistake": "Thinking filings require hardware.", "mentalModel": "Filing is easy."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:131b4ae01cb4$ml$]::text[]),
($ml$ef31c76a-56f5-5685-96c9-ed5f94c42149$ml$::uuid, $ml$spacetech$ml$, 30, 3, $ml${"id": "spacetech-d30-c3", "title": "Tell real filings from paper ones", "lessonTitle": "327,320 satellites on paper", "slot": 3, "type": "decide", "brief": {"headline": "You screen satellite filings for an investment fund. Rwanda's 2021 filing covered 327,320 satellites, and one part, CINNAMON-217, alone covered 52,080.", "kicker": "You decide which signs show a filing will really fly.", "fullText": "It was not clear who would build Rwanda's satellites. Starlink, the largest real fleet, had about 9,400 active satellites in early 2026.\n\nRegulators, investors and operators all need ways to judge which filings will actually launch. The ITU's milestones help, but only over years.", "sources": [{"url": "https://spaceinafrica.com/2021/10/14/rwanda-has-submitted-itu-filing-for-27-orbital-shells-of-327320-satellites/", "label": "Space in Africa, Rwanda files for 327,320 satellites"}, {"url": "https://teslanorth.com/2026/01/25/starlink-satellites-made-300000-moves-to-avoid-collisions-in-2025", "label": "TeslaNorth, citing SpaceX filing to the FCC"}, {"url": "https://itu.int/en/mediacentre/backgrounders/Pages/Non-geostationary-satellite-systems.aspx", "label": "ITU, non-geostationary satellite systems"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each sign suggest a filing will really fly?", "buckets": ["Likely real", "Likely paper"], "items": [{"text": "Signed launch contracts", "bucket": 0}, {"text": "Satellites already in production", "bucket": 0}, {"text": "Early milestones met on time", "bucket": 0}, {"text": "No named builder", "bucket": 1}, {"text": "Far more than any fleet ever flown", "bucket": 1}], "explanation": "Contracts, factories and met milestones are real signs. Size alone is not."}, "numbers": {"kind": "numberSense", "prompt": "CINNAMON-217 alone covered 52,080 satellites; Starlink had about 9,400. About how many times larger?", "min": 0, "max": 10, "value": 5.5, "unit": "x", "explanation": "52,080 divided by 9,400 is about 5.5."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your fund manager wants one test for filings.", "prompt": "Which do you propose?", "options": ["Launch contracts and met milestones", "The number of satellites filed", "The country that filed it"], "correctIndex": 0, "consequences": ["Shows real deployment.", "Size misleads.", "Not a test of reality."], "explanation": "Real constellations show contracts and meet milestones. Paper ones do not."}, "proReasoning": "Screeners look for evidence of deployment.", "commonMistake": "Ranking filings by size.", "mentalModel": "Test for deployment."}, "invest": {"call": {"kind": "theCall", "situation": "A company pitches you a 52,000-satellite filing.", "prompt": "What do you ask for?", "options": ["A list of all its shell altitudes", "Its launch contracts and factory", "A bigger filing number"], "correctIndex": 1, "consequences": ["Still paper.", "Proof of real deployment.", "Bigger is not better."], "explanation": "Without launches and production, a filing is only a reservation."}, "proReasoning": "Investors ask for proof beyond the filing.", "commonMistake": "Funding on filing size.", "mentalModel": "Ask for proof."}, "build_startup": {"call": {"kind": "theCall", "situation": "Investors doubt your constellation filing.", "prompt": "How do you prove it is real?", "options": ["File for even more satellites now", "Point to Rwanda's filing", "Show launch contracts and a factory"], "correctIndex": 2, "consequences": ["Looks less real.", "Wrong example.", "Hard evidence wins trust."], "explanation": "Launch contracts and production show a filing will fly."}, "proReasoning": "Founders back filings with real commitments.", "commonMistake": "Inflating the filing to impress.", "mentalModel": "Show commitments."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks how you tell a real constellation from a paper one.", "prompt": "What's the answer?", "options": ["Look for launches and built satellites", "Pick the one with the biggest number", "Check which has the best name"], "correctIndex": 0, "consequences": ["Real ones fly.", "Size misleads.", "Names say nothing."], "explanation": "Real constellations launch satellites; paper ones only reserve frequencies."}, "proReasoning": "Launches make claims real.", "commonMistake": "Judging by filing size.", "mentalModel": "Look for launches."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5cf7fa3dca94$ml$]::text[])
